const MIN_TRADABLE_QUANTITY = 1;
// LIVE_PARITY-Vorbereitung Schritt 1 (2026-09-07): reine, zustandslose Trade-Geometrie -
// unveraendert 1:1 aus sizePosition() extrahiert (Math.abs()-Formeln sind bereits
// richtungsagnostisch, LONG/SHORT brauchen daher keine getrennte Formel). Wird jetzt an ZWEI
// Stellen aufgerufen (hier in sizePosition() und weiter unten im Kandidaten-Loop), damit es nur
// EINE fachliche Formel gibt statt zweier unabhaengig gepflegter - beide Aufrufe sind reine
// Funktionsaufrufe mit identischen Eingaben, keine Zustandsteilung, kein Drift-Risiko.
function calculateTradeGeometry(entryReferencePrice, stopPrice, targetPrice) {
  const unitRisk = Math.abs(entryReferencePrice - stopPrice);
  const rewardDistance = Math.abs(targetPrice - entryReferencePrice);
  const rewardRiskRatio = rewardDistance / unitRisk;
  // FIX 2026-09-07 (LIVE_PARITY-Vorbereitung Schritt 1B, Geometry-NaN-Bug): klassifiziert
  // fehlende/nicht-numerische/nicht-endliche EINGABEWERTE. Bewusst NICHT hier erfasst:
  // rewardRiskRatio=Infinity/NaN, wenn sie AUSSCHLIESSLICH aus unitRisk===0 bei sonst
  // validen, endlichen Werten entsteht - das bleibt der bestehende, unveraenderte
  // STOP_WRONG_SIDE-Fachfall in sizePosition() (Phase 4 der Reparatur: bestehende Vetos
  // bleiben unangetastet). reward_risk_ratio_finite wird trotzdem als eigenes Diagnosefeld
  // zurueckgegeben, damit sie fuer spaetere Auswertung sichtbar bleibt, OHNE selbst die
  // geometry_error-Klassifikation zu beeinflussen.
  let geometryError = null;
  if (!Number.isFinite(entryReferencePrice)) geometryError = 'ENTRY_INVALID';
  else if (!Number.isFinite(stopPrice)) geometryError = 'STOP_MISSING';
  else if (!Number.isFinite(targetPrice)) geometryError = 'TARGET_MISSING';
  else if (!Number.isFinite(unitRisk) || !Number.isFinite(rewardDistance)) geometryError = 'NON_FINITE';
  return {
    entry_reference_price: entryReferencePrice,
    unit_risk: unitRisk,
    reward_distance: rewardDistance,
    reward_risk_ratio: rewardRiskRatio,
    reward_risk_ratio_finite: Number.isFinite(rewardRiskRatio),
    geometry_valid: unitRisk > 0,
    geometry_error: geometryError
  };
}
function sizePosition(signal, entryPriceEstimate, cfg, openPositionsState, sektor, region) {
  const geometry = calculateTradeGeometry(entryPriceEstimate, signal.stop_price, signal.target_price);
  const unitRisk = geometry.unit_risk;
  if (unitRisk <= 0) return { veto: 'STOP_WRONG_SIDE', unit_risk: unitRisk };
  const theoreticalRiskAmount = cfg.modelPortfolioValue * (cfg.maxRiskPerTradePct / 100);
  const riskBasedQuantity = Math.floor(theoreticalRiskAmount / unitRisk);
  if (riskBasedQuantity <= 0) return { veto: 'STOP_TARGET_INVALID', theoretical_quantity: riskBasedQuantity, unit_risk: unitRisk, theoretical_risk_amount: theoreticalRiskAmount };
  const maxSinglePositionQuantity = Math.floor((cfg.modelPortfolioValue * (cfg.maxSinglePositionPct / 100)) / entryPriceEstimate);
  const currentTotalRisk = openPositionsState.reduce((sum, p) => sum + p.risk_amount, 0);
  const remainingPortfolioRiskBudget = Math.max(0, cfg.modelPortfolioValue * (cfg.maxTotalOpenRiskPct / 100) - currentTotalRisk);
  const remainingPortfolioQuantity = Math.floor(remainingPortfolioRiskBudget / unitRisk);
  const currentSectorValue = openPositionsState.filter(p => p.sektor === sektor).reduce((sum, p) => sum + p.position_value, 0);
  const remainingSectorValue = Math.max(0, cfg.modelPortfolioValue * (cfg.maxSectorExposurePct / 100) - currentSectorValue);
  const remainingSectorQuantity = Math.floor(remainingSectorValue / entryPriceEstimate);
  const currentRegionValue = openPositionsState.filter(p => p.region === region).reduce((sum, p) => sum + p.position_value, 0);
  const remainingRegionValue = Math.max(0, cfg.modelPortfolioValue * (cfg.maxRegionExposurePct / 100) - currentRegionValue);
  const remainingRegionQuantity = Math.floor(remainingRegionValue / entryPriceEstimate);
  const candidates = [
    { quantity: riskBasedQuantity, reason: null },
    { quantity: maxSinglePositionQuantity, reason: 'SINGLE_POSITION_LIMIT' },
    { quantity: remainingPortfolioQuantity, reason: 'TOTAL_RISK_LIMIT' },
    { quantity: remainingSectorQuantity, reason: 'SECTOR_LIMIT' },
    { quantity: remainingRegionQuantity, reason: 'REGION_LIMIT' }
  ];
  let binding = candidates[0];
  for (const c of candidates) if (c.quantity < binding.quantity) binding = c;
  const finalQuantity = Math.max(0, Math.floor(binding.quantity));
  // J2 (2026-09-07): unit_risk/theoretical_risk_amount/quantity_by_value ab hier zusaetzlich
  // in jedem Veto-Zweig zurueckgegeben - reine Diagnose-Anreicherung, keine der folgenden
  // Bedingungen/Schwellen/Reihenfolgen ist gegenueber vorher veraendert.
  if (finalQuantity < MIN_TRADABLE_QUANTITY) return { veto: 'QUANTITY_TOO_SMALL', binding_limit: binding.reason, theoretical_quantity: riskBasedQuantity, unit_risk: unitRisk, theoretical_risk_amount: theoreticalRiskAmount, quantity_by_value: maxSinglePositionQuantity };
  const positionValue = finalQuantity * entryPriceEstimate;
  const actualRiskAmount = finalQuantity * unitRisk;
  const estimatedFees = positionValue * (cfg.feesBps / 10000);
  const estimatedSlippage = positionValue * (cfg.slippageBps / 10000);
  if ((estimatedFees + estimatedSlippage) * 2 > actualRiskAmount) return { veto: 'UNECONOMICAL_AFTER_COSTS', binding_limit: binding.reason, theoretical_quantity: riskBasedQuantity, unit_risk: unitRisk, theoretical_risk_amount: theoreticalRiskAmount, quantity_by_value: maxSinglePositionQuantity };
  const rewardRiskRatio = geometry.reward_risk_ratio;
  if (rewardRiskRatio < cfg.minRewardRiskRatio) return { veto: 'RRR_TOO_LOW', theoretical_quantity: riskBasedQuantity, unit_risk: unitRisk, theoretical_risk_amount: theoreticalRiskAmount, quantity_by_value: maxSinglePositionQuantity, reward_risk_ratio: rewardRiskRatio };
  return {
    veto: null, theoretical_quantity: riskBasedQuantity, actual_quantity: finalQuantity,
    theoretical_risk_amount: theoreticalRiskAmount, actual_risk_amount: actualRiskAmount,
    unit_risk: unitRisk, position_value: positionValue, reward_risk_ratio: rewardRiskRatio,
    quantity_by_value: maxSinglePositionQuantity,
    clamped: finalQuantity < riskBasedQuantity, clamp_reason: finalQuantity < riskBasedQuantity ? binding.reason : null
  };
}
// Nur noch die NICHT mengenreduzierbaren Haertegrenzen - Gesamtrisiko/Sektor/Einzelposition/
// Region werden bereits VOR der Order-Erzeugung in sizePosition() per Kappung beruecksichtigt.
function checkHardLimits(direction, positionValue, openPositionsState, cfg) {
  const blockers = [];
  if (openPositionsState.length + 1 > cfg.maxOpenPositions) blockers.push('MAX_OPEN_POSITIONS');
  const directionalValue = openPositionsState.filter(p => p.direction === direction).reduce((sum, p) => sum + p.position_value, 0) + positionValue;
  if (directionalValue / cfg.modelPortfolioValue * 100 > cfg.maxDirectionalExposurePct) blockers.push('DIRECTIONAL_LIMIT');
  return blockers;
}

// J2 (2026-09-07): reine Diagnose-Ableitungen fuer das Decision-Log, aus bereits vorhandenen
// Daten (runCtx.config_snapshot_json.regime_matrix ist Teil des beim Run-Start eingefrorenen
// Snapshots, siehe "Baue Run-Kontext"). Werden NIRGENDS zur Steuerung von Kandidaten-
// Annahme/Ablehnung verwendet - WF17 wendet fit_multiplier/regime_matrix in der eigentlichen
// Handelslogik aktuell nicht an (siehe G1-Befund Sitzungsdiagnose 2026-09-07); diese Funktionen
// machen das nur fuer die spaetere Ablation sichtbar.
function fitMultiplierFor(strategyName, combinedRegimeValue) {
  const matrix = (runCtx.config_snapshot_json && runCtx.config_snapshot_json.regime_matrix) || [];
  const row = matrix.find(m => m.strategy === strategyName && m.combined_regime === combinedRegimeValue);
  return row ? row.fit_multiplier : null;
}

// ============================================================
// LIVE_PARITY-Vorbereitung Schritt 4C (2026-09-08): fitMultiplier + Regime Point-in-Time
// Parity als bewusst UNGENUTZTE Vorbereitung. RESEARCH_BASELINE (regionRegimeHistorical(),
// symbolRegimeContext(), fitMultiplierFor(), market_regime_at_entry) bleibt komplett
// unveraendert und wird weiterhin fuer alle echten Trades verwendet -
// computeLiveParityRegime()/getLiveParityFitMultiplier() haben unten KEINEN Aufrufer.
//
// Befund aus Schritt 4C-Analyse: regionRegimeHistorical() ist bereits ein fast exaktes
// Live-Parity-Replikat von WF02b "Marktregime berechnen" - 7 synthetische
// Regime-Szenarien + reale Preisdaten fuer alle 24 verfuegbaren market_regime-
// Golden-Referenzen (21.08.-07.09.2026) stimmen ueberein, bis auf zwei erklaerte
// Ausnahmen (keine stille Toleranz, echte Root Causes):
// - USA ist im Live-Betrieb fast immer 'vorlaeufig' (WF02b laeuft 17:55 Berlin,
//   die NYSE-Sitzung (09:30-16:00 ET = 15:30-22:00 Berlin) ist dann noch offen -
//   ein reines Scheduling-Artefakt, das fuer eine historische Simulation (immer
//   "closed_complete") nicht gilt und deshalb bewusst NICHT repliziert wird.
// - Eine einzelne Europa-Abweichung (2026-09-06) beruht auf veralteten historical_
//   price_data-Staenden fuer ^GDAXI (endet dort am 14.08., siehe bekannte Luecke
//   aus Schritt 4A/4B), nicht auf einem Formelfehler.
//
// Der EINE echte, bestaetigte Formel-Gap: regionRegimeHistorical() hat KEINE
// Markt-/Makro-News-Komponente (WF02b: stress, wenn zusaetzlich mind. 1 stark
// negative Markt-/Makro-Nachricht desselben Tages vorliegt - unabhaengig von Kurs-/
// Volatilitaetslage). 10 von 12 inhaltlich vergleichbaren Golden-Referenzen (Europa,
// ohne die zwei oben erklaerten Ausnahmen) stimmen erst NACH Beruecksichtigung der
// echten Tages-News-Zahl exakt mit dem gespeicherten combined_regime ueberein.
//
// PIT-Hinweis News: trading.news_items/v_news_latest_assessment beginnen erst
// 2026-07-09/07-16 - fuer den Grossteil des Entwicklungsfensters (01.05.-15.08.)
// existieren dort schlicht keine Zeilen, macroNewsNegativHochCount faellt dann
// automatisch auf 0 zurueck (WF02bs eigenes sicheres Default-Verhalten bei keinen
// Nachrichten an dem Tag - keine Erfindung). Eine echte point-in-time-gefilterte
// Abfrage ist hier noch NICHT verdrahtet - wird als expliziter KNOWN_PARITY_GAP im
// Bericht gefuehrt, kein stiller Fallback. Zusatzbefund beim Golden-Test (2026-08-21,
// Europa): ein reines "published_at::date = D"-Datumsfilter reicht NICHT - die Nachricht
// wurde laut assessed_at erst 19:00 Berlin bewertet, WF02bs eigener Lauf (17:55 Berlin)
// hatte sie an dem Tag noch gar nicht. Eine echte Verdrahtung braucht denselben
// Tageszeit-Cutoff-Gedanken wie das bereits bestehende data_cutoff_time-Konzept
// (siehe "DB: Historische Nachrichten laden"), nicht nur einen Datumsvergleich.
//
// strategy_regime_matrix ist NICHT historisiert (keine valid_from/valid_to/rule_version-
// Mehrfachbelegung - Schema-Check bestaetigt nur die eine "regime-matrix-v1"). Jede
// Anwendung auf historische Tage ist deshalb CURRENT_POLICY_REPLAY, nicht
// HISTORICAL_AS_WAS - identisch zur bestehenden fitMultiplierFor()-Semantik
// (runCtx.config_snapshot_json.regime_matrix, ein einmaliger Snapshot pro Lauf).
// ============================================================
const LIVE_PARITY_MATRIX_POLICY = 'CURRENT_POLICY_REPLAY'; // strategy_regime_matrix nicht historisiert, siehe Kommentar oben

// 1:1 WF02b-Semantik (regionRegimeHistorical() + der fehlende News-Zweig), ansonsten volle
// Wiederverwendung der bereits verifizierten RESEARCH_BASELINE-Funktion. macroNewsNegativHochCount
// bewusst als Parameter (kein PIT-News-Datenzugriff hier verdrahtet, siehe Kommentar oben) -
// Default 0 entspricht WF02bs eigenem Verhalten an einem Tag ohne solche Nachrichten.
function computeLiveParityRegime(region, day, macroNewsNegativHochCount) {
  const symbols = REGIME_SYMBOLS[region === 'Europa' ? 'europa' : (region === 'USA' ? 'usa' : null)];
  if (!symbols) return { combined_regime: 'unknown', stress_regime: 'unknown' };
  const base = regionRegimeHistorical(symbols, day);
  const newsCount = macroNewsNegativHochCount || 0;
  if (newsCount >= 1 && base.stress_regime !== 'stress') {
    return { combined_regime: 'stress', stress_regime: 'stress' };
  }
  return base;
}

// Exakte WF06-Semantik (matrixByKey[strategy+'|'+combinedRegime] || matrixByKey[strategy+'|unknown']),
// liefert zusaetzlich regime_blocked (siehe Schritt-4C-Befund: WF06 filtert Kandidaten bereits VOR
// der dominant-Auswahl ueber !regimeBlocked - ein spaeterer opportunity_score-Baustein ohne dieses
// Feld wuerde diese vorgelagerte Live-Filterregel vergessen). Dieselbe Matrixquelle wie die bereits
// vorhandene fitMultiplierFor() (runCtx.config_snapshot_json.regime_matrix) - keine zweite Quelle.
function getLiveParityFitMultiplier(strategyName, combinedRegimeValue) {
  const matrix = (runCtx.config_snapshot_json && runCtx.config_snapshot_json.regime_matrix) || [];
  const row = matrix.find(m => m.strategy === strategyName && m.combined_regime === combinedRegimeValue)
    || matrix.find(m => m.strategy === strategyName && m.combined_regime === 'unknown');
  if (!row) return { fit_multiplier: 0.3, regime_blocked: false, matrix_row_found: false };
  return { fit_multiplier: row.fit_multiplier, regime_blocked: !!row.blocked, matrix_row_found: true };
}

// ============================================================
// LIVE_PARITY-Vorbereitung Schritt 4E (2026-09-08): Fundamentalbonus Point-in-Time
// als bewusst UNGENUTZTE Vorbereitung. RESEARCH_BASELINE (Signale, Momentum, Regime,
// Geometry, Correlation, Sizing, Portfolio, Fill, Exit) bleibt komplett unveraendert -
// getLiveParityFundTrend()/getLiveParityFundBonus() haben unten KEINEN Aufrufer.
//
// Befund aus Schritt 4D (Klassifikation B - PORTIERBAR MIT HISTORISCHEN DEFAULTS):
// trading.fundamentals_history beginnt erst 2026-07-27 (14 der 15 Kernaktien) bzw.
// 2026-08-05 (BAS.DE). Bei 14 Tickern sind die ersten 4 Snapshots (27.-30.07.) NULL
// (eigenkapitalrendite_numeric/gewinnmarge_numeric), echte Werte erst ab 31.07. -
// da rows[0] (aeltester Snapshot im 180-Tage-Fenster) bis ca. 2027-01-23 zwangslaeufig
// einer dieser Null-Snapshots bleibt, ist fundTrend.direction fuer diese 14 Ticker
// WAEHREND DES GESAMTEN ENTWICKLUNGSFENSTERS (01.05.-15.08.2026) UND WEIT DARUEBER
// HINAUS zwangslaeufig 'unbekannt' - nicht wegen fehlender Snapshots allein, sondern
// weil delta() bei einem NULL-Endpunkt immer null liefert (siehe WF06-Code unten).
// BAS.DE ist die einzige Ausnahme (echte Werte bereits im ersten Snapshot 05.08.).
// Das ist explizit KEIN Bug, sondern der laut Nutzervorgabe fachlich richtige,
// Lookahead-freie Default fuer diesen Zeitraum.
//
// Decision-Cutoff: WF06 laeuft 18:10 Europe/Berlin, NACH WF01 (06:00, Quelle) und WF02b
// (17:55) - siehe Schritt 4D. Fuer einen Simulationstag D ist der Cutoff deshalb
// D 18:10 Europe/Berlin (vom Aufrufer als decisionTimeIso zu uebergeben, keine
// Datums-/Zeitzonenlogik hier im Helper - reine As-Of-Filterung).
//
// policy_mode ist immer CURRENT_POLICY_REPLAY: die fundamentalTrend()-Formel/Schwellen
// selbst sind nicht historisiert/versioniert - ein historischer Lauf wendet die HEUTIGE
// Formel auf die damals (PIT) bekannten Daten an, siehe Schritt 4C/4D.
// ============================================================

// 1:1 WF06 round() (parseFloat(Number(v).toFixed(d))) - eigene Kopie, damit dieser Helper
// keine Abhaengigkeit zu einer anderen Node/einem anderen Workflow braucht.
function liveParityFundRound(v, d) {
  if (v === null || v === undefined || isNaN(v)) return null;
  return parseFloat(Number(v).toFixed(d === undefined ? 3 : d));
}

// rows: ALLE bekannten Revisionen eines Tickers (unvorgefiltert), je
// { snapshot_date, valid_from, valid_to, eigenkapitalrendite_numeric, gewinnmarge_numeric }.
// day: Simulationstag D ('YYYY-MM-DD'). decisionTimeIso: ISO-Timestamp des Cutoffs
// (D 18:10 Europe/Berlin - vom Aufrufer berechnet). Keine DB-Query hier - rows muessen
// bereits (einmalig/batchweise) geladen sein, siehe Kommentar oben.
function getLiveParityFundTrend(rows, day, decisionTimeIso) {
  const cutoff = new Date(decisionTimeIso);
  const dayStart = new Date(day + 'T00:00:00Z');
  const windowStart = new Date(dayStart.getTime() - 180 * 86400000);

  // As-Of: nur die Revision je logischem Snapshot, die am Cutoff bereits gueltig und noch
  // nicht wieder geschlossen war (SCD2, siehe Schritt 4D Phase 5). Pro snapshot_date kann
  // wegen uq_fundamentals_history_current hoechstens eine Revision diese Bedingung zu einem
  // gegebenen Cutoff erfuellen - keine Doppelzaehlung moeglich.
  const asOf = (rows || []).filter(r => {
    const vf = new Date(r.valid_from);
    if (isNaN(vf.getTime()) || vf > cutoff) return false;
    if (r.valid_to == null) return true;
    const vt = new Date(r.valid_to);
    return isNaN(vt.getTime()) ? true : vt > cutoff;
  });

  // 180-Tage-Fenster relativ zu D (WF06 live: relativ zu "heute") und niemals > D selbst.
  const inWindow = asOf.filter(r => {
    const sd = new Date(String(r.snapshot_date).slice(0, 10) + 'T00:00:00Z');
    return !isNaN(sd.getTime()) && sd >= windowStart && sd <= dayStart;
  });
  inWindow.sort((a, b) => String(a.snapshot_date).localeCompare(String(b.snapshot_date)));

  const oldest = inWindow.length ? inWindow[0] : null;
  const latest = inWindow.length ? inWindow[inWindow.length - 1] : null;

  if (inWindow.length < 2) {
    return {
      direction: 'unbekannt',
      snapshot_count: inWindow.length,
      oldest_snapshot_at: oldest ? oldest.snapshot_date : null,
      latest_snapshot_at: latest ? latest.snapshot_date : null,
      oldest_snapshot_null: oldest ? (oldest.eigenkapitalrendite_numeric == null && oldest.gewinnmarge_numeric == null) : null,
      pit_complete: true,
      policy_mode: 'CURRENT_POLICY_REPLAY'
    };
  }

  // 1:1 WF06 delta()/direction - exakte Null-/NaN-/Zero-Semantik, keine Aenderung.
  function delta(field) {
    const a = Number(oldest[field]), b = Number(latest[field]);
    if (isNaN(a) || isNaN(b) || a === 0) return null;
    return liveParityFundRound(((b - a) / Math.abs(a)) * 100, 2);
  }
  const roeTrend = delta('eigenkapitalrendite_numeric');
  const margeTrend = delta('gewinnmarge_numeric');
  let direction = 'unbekannt';
  if (roeTrend !== null && margeTrend !== null) direction = (roeTrend + margeTrend) > 0 ? 'positiv' : 'negativ';
  else if (roeTrend !== null) direction = roeTrend > 0 ? 'positiv' : 'negativ';
  else if (margeTrend !== null) direction = margeTrend > 0 ? 'positiv' : 'negativ';

  return {
    direction,
    snapshot_count: inWindow.length,
    oldest_snapshot_at: oldest.snapshot_date,
    latest_snapshot_at: latest.snapshot_date,
    oldest_snapshot_null: oldest.eigenkapitalrendite_numeric == null && oldest.gewinnmarge_numeric == null,
    pit_complete: true,
    policy_mode: 'CURRENT_POLICY_REPLAY'
  };
}

// Exakte WF06-Wahrheitstabelle (kauf/verkauf sind die einzigen von WF06 fachlich
// unterschiedenen Richtungen - fuer jede andere/unerwartete tradeDirection greift
// exakt derselbe Else-Zweig wie in WF06: unbekannt->0.05, sonst 0, unveraendert uebernommen).
function getLiveParityFundBonus(tradeDirection, fundDirection) {
  if ((fundDirection === 'positiv' && tradeDirection === 'kauf') || (fundDirection === 'negativ' && tradeDirection === 'verkauf')) return 0.15;
  return fundDirection === 'unbekannt' ? 0.05 : 0;
}

// ============================================================
// LIVE_PARITY-Vorbereitung Schritt 4F.1 (2026-09-08): Dominant-Selection mit News-Tri-State
// als bewusst UNGENUTZTE Vorbereitung. RESEARCH_BASELINE bleibt komplett unveraendert -
// selectLiveParityDominant() hat unten KEINEN Aufrufer.
//
// Live-Kandidatentypen (Schritt 4F/4G bestaetigt): mean_reversion, trend_following, breakout,
// news_event. momentum ist RESEARCH_BASELINE_ONLY (kein trading.strategy_signals-Eintrag,
// nie ein echter WF06-Kandidat) und darf hier nicht still auftauchen.
//
// Architekturentscheidung aus Schritt 4G: news_event darf fuer das Entwicklungsfenster
// (01.05.-15.08.2026) NICHT still weggelassen werden - Rohnews existieren, aber jede
// Bewertung in trading.historical_news_assessments wurde nachweislich per rueckblickendem
// Batch-Lauf (05.08.-01.09.2026, 66-123 Tage nach Veroeffentlichung) erzeugt und existierte
// an keinem Tag des Fensters selbst aus Sicht eines (hypothetischen) Live-Systems. Deshalb
// Tri-State statt binaerer Ja/Nein-Antwort:
//   newsEventState = {
//     status:       'KNOWN_SIGNAL' | 'KNOWN_NONE' | 'UNKNOWN',
//     candidate:    { strategy:'news_event', direction, raw_score } | null,
//     pit_complete: boolean,   // true nur wenn die Nichtexistenz/Existenz zum Zeitpunkt D bewiesen ist
//     reason:       string     // menschenlesbare Begruendung, z.B. 'assessed_at nach D'
//   }
//   KNOWN_SIGNAL = PIT-beweisbarer news_event-Kandidat vorhanden (candidate gesetzt)
//   KNOWN_NONE   = PIT-vollstaendige Datenlage, WF06 haette an Tag D sicher KEINEN erzeugt
//   UNKNOWN      = Datenlage reicht nicht aus, um Signal oder Nicht-Signal PIT-sicher zu
//                  beweisen (der Fall fuer praktisch das gesamte Entwicklungsfenster, siehe
//                  Schritt 4G)
//
// Fuer strict LIVE_PARITY (mode==='LIVE_PARITY', der sichere Default) gilt: UNKNOWN
// blockiert die gesamte Dominant-Auswahl (status='INDETERMINATE_NEWS_EVENT', dominant=null,
// live_parity_eligible=false) - es wird NICHT still unter den drei anderen Strategien
// ausgewaehlt, als gaebe es news_event gar nicht. Das waere eine andere (moeglicherweise
// falsche) Entscheidung als die echte WF06-Logik mit vollstaendiger News-Kenntnis getroffen
// haette.
//
// Fuer AVAILABLE_DATA_LIVE_REPLAY darf ein post-hoc aus historical_news_assessments
// rekonstruierter Kandidat trotzdem durchlaufen (pit_complete=false,
// replay_mode='POSTHOC_AVAILABLE_DATA_REPLAY' auf dem Candidate-Objekt) - das Ergebnis
// darf dann NIE live_parity_eligible=true setzen (siehe isPosthocReplay unten).
//
// KNOWN_PARITY_GAPS (unveraendert fortgefuehrt, siehe Schritte 4B-4G):
// (1) 52-Wochen-Hoch/Tief-Quelle weicht ab, (2) Volumen-Fenster weicht ab,
// (3) strategy_regime_matrix = CURRENT_POLICY_REPLAY (nicht historisiert),
// (4) Markt-/Makro-News-Regime-PIT nicht verdrahtet,
// (5) news_event PIT im Entwicklungsfenster nicht verfuegbar (Klassifikation C, Schritt 4G),
// (6) LIVE_STRATEGY_SIGNAL_INSERTION_ORDER_NONDETERMINISTIC: trading.strategy_signals wird
//     ohne ORDER BY gelesen; JS Array.sort ist stabil (ES2019+), also entscheidet bei exakt
//     gleichem adjustedScore die Einfuegereihenfolge - die Postgres ohne ORDER BY NICHT
//     garantiert. Echte, seltene Nichtdeterminismus-Quelle im Live-System, hier bewusst NICHT
//     durch einen erfundenen Tie-Breaker "repariert".
// GELOEST (Schritt 4C.1, commit d0e719f): fitMultiplier-Default bei komplett fehlender
// Matrix-Zeile war faelschlich null/null, jetzt korrekt 0.3/false wie WF06.

// ---- adjustedScore: 1:1 WF06 round(x,4) = parseFloat(x.toFixed(4)) ----
function calculateLiveParityAdjustedScore(rawScore, fitMultiplier) {
  const v = (Number(rawScore) || 0) * fitMultiplier;
  return parseFloat(v.toFixed(4));
}

// ---- reine, unbenutzte Dominant-Selection ----
// input: {
//   candidates:     [{strategy, direction, raw_score}, ...]  // strategy_signals-Reihenfolge,
//                                                             // OHNE news_event
//   newsEventState: siehe Tri-State-Struktur oben
//   combinedRegime: string (aus computeLiveParityRegime/regionRegimeHistorical)
//   mode:           'LIVE_PARITY' (Default) | 'AVAILABLE_DATA_LIVE_REPLAY' | 'RESEARCH_BASELINE'
// }
function selectLiveParityDominant(input) {
  const candidates = (input && input.candidates) || [];
  const newsEventState = (input && input.newsEventState) || {
    status: 'UNKNOWN', candidate: null, pit_complete: false, reason: 'kein newsEventState uebergeben'
  };
  const combinedRegime = input && input.combinedRegime;
  const mode = (input && input.mode) || 'LIVE_PARITY';

  if (mode === 'LIVE_PARITY' && newsEventState.status === 'UNKNOWN') {
    return {
      status: 'INDETERMINATE_NEWS_EVENT',
      live_parity_eligible: false,
      dominant: null,
      usable_candidates: [],
      rejected_candidates: [],
      input_count: candidates.length,
      blocked_count: null,
      below_threshold_count: null,
      usable_count: null,
      selected_strategy: null,
      selected_direction: null,
      selected_raw_score: null,
      selected_fit_multiplier: null,
      selected_adjusted_score: null,
      selected_source_index: null,
      news_event_status: newsEventState.status
    };
  }

  // Kandidatenmenge: strategy_signals-Reihenfolge EXAKT wie uebergeben (siehe GAP 6 oben),
  // news_event - falls KNOWN_SIGNAL - wird wie in WF06 (rawCandidates.push(ne)) ans ENDE
  // angehaengt, niemals davor. KNOWN_NONE haengt nichts an (= WF06 bei newsEventSignalFor()===null).
  const fullCandidateList = candidates.slice();
  if (newsEventState.status === 'KNOWN_SIGNAL' && newsEventState.candidate) {
    fullCandidateList.push(newsEventState.candidate);
  }

  const withFit = fullCandidateList.map((c, idx) => {
    const fit = getLiveParityFitMultiplier(c.strategy, combinedRegime);
    const adjustedScore = calculateLiveParityAdjustedScore(c.raw_score, fit.fit_multiplier);
    return { ...c, fitMultiplier: fit.fit_multiplier, regimeBlocked: fit.regime_blocked, adjustedScore, sourceIndex: idx };
  });

  const blocked = withFit.filter(c => c.regimeBlocked);
  const belowThreshold = withFit.filter(c => !c.regimeBlocked && c.adjustedScore < 0.15);
  const usable = withFit.filter(c => !c.regimeBlocked && c.adjustedScore >= 0.15);
  // Nur eine Kopie sortieren - stabiler Sort (V8/ES2019+), kein erfundener Tie-Breaker (GAP 6).
  const sortedUsable = usable.slice().sort((a, b) => b.adjustedScore - a.adjustedScore);
  const dominant = sortedUsable[0] || null;

  // Post-hoc (AVAILABLE_DATA_LIVE_REPLAY) rekonstruierte news_event-Kandidaten duerfen die
  // Selektion technisch durchlaufen, aber NIE live_parity_eligible=true ergeben.
  const isPosthocReplay =
    (newsEventState.status === 'KNOWN_SIGNAL' && newsEventState.pit_complete === false) ||
    (newsEventState.candidate && newsEventState.candidate.replay_mode === 'POSTHOC_AVAILABLE_DATA_REPLAY');

  return {
    status: dominant ? 'DOMINANT_SELECTED' : 'NO_USABLE_CANDIDATE',
    live_parity_eligible: mode === 'LIVE_PARITY' && !isPosthocReplay,
    dominant: dominant,
    usable_candidates: sortedUsable,
    rejected_candidates: blocked.concat(belowThreshold),
    input_count: fullCandidateList.length,
    blocked_count: blocked.length,
    below_threshold_count: belowThreshold.length,
    usable_count: usable.length,
    selected_strategy: dominant ? dominant.strategy : null,
    selected_direction: dominant ? dominant.direction : null,
    selected_raw_score: dominant ? dominant.raw_score : null,
    selected_fit_multiplier: dominant ? dominant.fitMultiplier : null,
    selected_adjusted_score: dominant ? dominant.adjustedScore : null,
    selected_source_index: dominant ? dominant.sourceIndex : null,
    news_event_status: newsEventState.status
  };
}

// ============================================================
// LIVE_PARITY-Vorbereitung Schritt 4H (2026-09-08): opportunity_score-Assembly als reiner,
// UNGENUTZTER Helper. RESEARCH_BASELINE bleibt komplett unveraendert -
// calculateLiveParityOpportunityScore() hat unten KEINEN Aufrufer.
//
// 1:1-Transkription von WF06s "Empfehlungen: Abgleich berechnen"-Block (frisch am
// 2026-09-08 gelesen, NICHT aus alten Berichten uebernommen):
//   opportunity  = 0
//   opportunity += 0.35 * Math.min(1, Number(dominant.raw_score) || 0)
//   opportunity += 0.25 * Math.min(1, dominant.fitMultiplier || 0)
//   opportunity += fundBonus   // aus getLiveParityFundBonus(), NICHT hier neu berechnet
//   opportunity += 0.25 * (risk ? Math.min(1, risk.rewardRiskRatio / 3) : 0)
//   opportunity  = round(Math.min(1, opportunity), 3)
//
// WICHTIGER, bewusst UNVERAENDERT uebernommener Asymmetrie-Fund: die fitMultiplier-Zeile
// nutzt `dominant.fitMultiplier || 0` OHNE Number()-Wrapper (anders als raw_score). In der
// Praxis irrelevant (fitMultiplier ist immer eine echte Zahl aus der Matrix), aber exakt so
// reproduziert statt "verbessert" (Auftrag Phase 4: "Nicht verbessern").
//
// SCHAERFERER FUND: die RRR-Komponente hat KEINEN ||0-Fallback auf rewardRiskRatio selbst -
// nur `risk` (die Verfuegbarkeit) wird auf Truthiness geprueft. Ist risk vorhanden aber
// rewardRiskRatio undefined/NaN, ergibt `Math.min(1, NaN/3)` = NaN, das propagiert durch die
// Summe (`opportunity` wird NaN), und round()s eigener `isNaN(v)`-Zweig liefert dann null -
// NICHT 0, NICHT ein Clamp-Ergebnis. Dieses Verhalten wird hier bewusst 1:1 reproduziert
// (siehe calculateLiveParityOpportunityScore: `riskAvailable ? Math.min(1, rewardRiskRatio / 3) : 0`
// - rewardRiskRatio wird ungeschuetzt durch 3 geteilt, exakt wie live).
//
// Rundung: reuse von liveParityFundRound() (Schritt 4E, selber Node) statt einer dritten,
// redundanten round-Funktion - dessen Semantik (null bei null/undefined/NaN, sonst
// parseFloat(Number(v).toFixed(d))) ist mit WF06s round(v,d=3) bei d=3 identisch.
//
// Architektur-Vorgaben (Phase 2/3/7/8/9, explizit eingehalten):
// - Der Helper waehlt selbst KEINEN dominant, bestimmt KEIN Regime, KEINE Fundamentals,
//   KEINE Geometry und KEINEN Candidate - er kombiniert ausschliesslich bereits korrekt
//   bestimmte, vom Aufrufer uebergebene Inputs.
// - rewardRiskRatio ist ein EXPLIZITER Input, NICHT intern aus dem aktiven
//   RESEARCH_BASELINE-candidateGeometry gelesen - ein zukuenftiger LIVE_PARITY-dominant kann
//   eine andere Strategie und damit andere Geometry/RRR besitzen als der aktive
//   RESEARCH-Candidate.
// - fundBonus ist ein EXPLIZITER Input aus getLiveParityFundBonus() (Schritt 4E) - keine
//   zweite Fundamentalbonus-Wahrheitstabelle hier.
// - fitMultiplier ist ein EXPLIZITER Input vom bereits ausgewaehlten LIVE_PARITY-dominant
//   (aus selectLiveParityDominant(), Schritt 4F.1) - kein erneuter Matrix-Lookup, kein
//   eigener 0.3/blocked-Fallback hier (der gehoert ausschliesslich in
//   getLiveParityFitMultiplier()).
//
// Dominant-Status-Kontrakt (Phase 9, nur dokumentiert, noch keine globale Verknuepfung):
// Wenn ein zukuenftiger Aufrufer selectLiveParityDominant() mit
// status==='INDETERMINATE_NEWS_EVENT' (dominant=null) erhaelt, darf
// calculateLiveParityOpportunityScore() NICHT mit einem Ersatz-dominant aus den drei
// verbleibenden Strategien aufgerufen werden - der korrekte Umgang ist, den
// opportunity_score in diesem Fall komplett auszulassen (null / "not_applicable"), nicht
// ihn aus unvollstaendiger Kandidatenkenntnis zu berechnen. Dieser Schritt fuehrt dazu noch
// KEINE Verknuepfung ein.
//
// CURRENT_POLICY_REPLAY-Hinweis (Phase 13): ein historischer opportunity_score kann
// Komponenten enthalten, die selbst nur CURRENT_POLICY_REPLAY (Regime-Matrix, Fundamentals)
// oder POSTHOC_AVAILABLE_DATA_REPLAY/UNKNOWN (News) sind. Der reine Zahlenwert allein
// beweist deshalb NOCH KEINE vollstaendige Live-Paritaet - das muss bei jeder spaeteren
// Verwendung mitgefuehrt werden, dieser Helper erfindet dafuer aber keinen eigenen Modus.
//
// KNOWN_PARITY_GAPS unveraendert fortgefuehrt (siehe Schritte 4B-4G).
// ============================================================

// input: {
//   rawScore:        number|null|undefined  // dominant.raw_score
//   fitMultiplier:   number|null|undefined  // dominant.fitMultiplier (aus selectLiveParityDominant())
//   fundBonus:       number                 // aus getLiveParityFundBonus(), NICHT hier neu berechnet
//   rewardRiskRatio: number|null|undefined  // Geometry des ausgewaehlten LIVE_PARITY-dominant
//   riskAvailable:   boolean                // entspricht WF06s `risk`-Truthiness-Check
// }
function calculateLiveParityOpportunityScore(input) {
  const rawScore = input && input.rawScore;
  const fitMultiplier = input && input.fitMultiplier;
  const fundBonus = input && input.fundBonus;
  const rewardRiskRatio = input && input.rewardRiskRatio;
  const riskAvailable = input && input.riskAvailable;

  const rawComponent = 0.35 * Math.min(1, Number(rawScore) || 0);
  const fitComponent = 0.25 * Math.min(1, fitMultiplier || 0);
  const fundComponent = fundBonus;
  const rrrComponent = 0.25 * (riskAvailable ? Math.min(1, rewardRiskRatio / 3) : 0);

  const preCapTotal = rawComponent + fitComponent + fundComponent + rrrComponent;
  const opportunityScore = liveParityFundRound(Math.min(1, preCapTotal), 3);

  return {
    opportunity_score: opportunityScore,
    components: {
      raw: rawComponent,
      fit: fitComponent,
      fundamental: fundComponent,
      rrr: rrrComponent,
      pre_cap_total: preCapTotal
    }
  };
}

