//    geometry-relevant - Stop/Target haengen nur an ATR+Kurs, nicht am 52w-Niveau selbst;
//    frisch in Schritt 4I Phase 11 bestaetigt)
// 2. volume-history window difference
// 3. strategy_regime_matrix CURRENT_POLICY_REPLAY (nicht historisiert)
// 4. Markt-/Makro-News-Regime-PIT nicht verdrahtet
// 5. news_event PIT im Entwicklungsfenster nicht verfuegbar (Klassifikation C)
// 6. strategy_signals ohne ORDER BY -> Insertion-Order-Nichtdeterminismus bei exakten Ties
// 7. NEU (Schritt 4I): news_event-Geometry nicht portiert - haengt an einer bislang nicht
//    LIVE_PARITY-replizierten, eigenstaendigen RSI/MACD-basierten "aggregierten
//    Ticker-Richtung"-Formel aus WF02 (WF06s legacy ATR-Fallback via
//    ATR_STOP_MULTIPLIER=1.5/ATR_TARGET_MULTIPLIER=2.5, gekoppelt an diese Richtung, NICHT
//    an die news_event-eigene Richtung). Klassifikation B fuer das Gesamtsystem: die 3
//    technischen Strategien sind 1:1 READY, news_event bleibt dokumentierter Gap.
// ============================================================

// input: {
//   dominantStatus: string   // aus selectLiveParityDominant().status
//   dominant:       object|null  // aus selectLiveParityDominant().dominant - fuer
//                                // mean_reversion/trend_following/breakout traegt dieser
//                                // Kandidat bereits stop_price/target_price/entry_zone_low/
//                                // entry_zone_high (aus computeLiveParitySignals(), Schritt
//                                // 4B), fuer news_event NICHT (siehe oben, dokumentierter Gap)
//   entryReferencePrice: number  // PIT-letzter Close des Tickers am Simulationstag D
//                                // (== WF06s kursWert), EXPLIZITER Input analog Schritt 4H
// }
function buildLiveParityGeometry(input) {
  const dominantStatus = input && input.dominantStatus;
  const dominant = input && input.dominant;
  const entryReferencePrice = input && input.entryReferencePrice;

  if (dominantStatus === 'INDETERMINATE_NEWS_EVENT' || dominantStatus === 'NO_USABLE_CANDIDATE' || !dominant) {
    return {
      valid: false, reason: 'NO_DOMINANT_CANDIDATE', strategy: null, direction: null,
      entry_reference_price: entryReferencePrice != null ? entryReferencePrice : null,
      entry_zone_low: null, entry_zone_high: null, stop_price: null, target_price: null,
      unit_risk: null, reward_distance: null, reward_risk_ratio: null,
      geometry_source: 'NOT_APPLICABLE', pit_complete: false
    };
  }

  if (dominant.strategy === 'news_event') {
    // Dokumentierter Gap (KNOWN_PARITY_GAPS #7) - bewusst NICHT ersatzweise eine andere
    // Strategie-Geometry verwenden, wie Phase 6 des Auftrags explizit vorschreibt.
    return {
      valid: false, reason: 'NEWS_EVENT_GEOMETRY_NOT_IMPLEMENTED', strategy: 'news_event', direction: dominant.direction || null,
      entry_reference_price: entryReferencePrice != null ? entryReferencePrice : null,
      entry_zone_low: null, entry_zone_high: null, stop_price: null, target_price: null,
      unit_risk: null, reward_distance: null, reward_risk_ratio: null,
      geometry_source: 'NOT_APPLICABLE', pit_complete: false
    };
  }

  const richtung = dominant.direction === 'long' ? 'kauf' : 'verkauf';
  const stopPrice = dominant.stop_price !== undefined && dominant.stop_price !== null ? Number(dominant.stop_price) : null;
  const targetPrice = dominant.target_price !== undefined && dominant.target_price !== null ? Number(dominant.target_price) : null;
  const entryZoneLow = dominant.entry_zone_low !== undefined ? dominant.entry_zone_low : null;
  const entryZoneHigh = dominant.entry_zone_high !== undefined ? dominant.entry_zone_high : null;

  const base = {
    strategy: dominant.strategy, direction: dominant.direction,
    entry_reference_price: entryReferencePrice != null ? entryReferencePrice : null,
    entry_zone_low: entryZoneLow, entry_zone_high: entryZoneHigh,
    stop_price: stopPrice, target_price: targetPrice,
    geometry_source: 'STRATEGY_SIGNAL_FIELDS', pit_complete: true
  };

  // Wortgleiche `=== null`-Vergleiche wie WF06 (bewusst kein isNaN-Ersatz - siehe Kommentar
  // oben zur NaN-target-Luecke).
  if (stopPrice === null || targetPrice === null) {
    return { ...base, valid: false, reason: 'STOP_TARGET_MISSING', unit_risk: null, reward_distance: null, reward_risk_ratio: null };
  }

  let stopWrongSide = false, targetWrongSide = false;
  if (richtung === 'kauf') {
    if (stopPrice >= entryReferencePrice) stopWrongSide = true;
    if (targetPrice <= entryReferencePrice) targetWrongSide = true;
  } else {
    if (stopPrice <= entryReferencePrice) stopWrongSide = true;
    if (targetPrice >= entryReferencePrice) targetWrongSide = true;
  }
  if (stopWrongSide || targetWrongSide) {
    return { ...base, valid: false, reason: stopWrongSide ? 'STOP_WRONG_SIDE' : 'TARGET_WRONG_SIDE', unit_risk: null, reward_distance: null, reward_risk_ratio: null };
  }

  // Wiederverwendung der reinen Arithmetik (Phase 13) - keine zweite RRR-Formel.
  const geom = calculateTradeGeometry(entryReferencePrice, stopPrice, targetPrice);
  if (!geom.geometry_valid) {
    // Entspricht computeRisk()s `!(unitRisk > 0) -> return null` (z.B. entry === stop).
    return { ...base, valid: false, reason: 'UNIT_RISK_NOT_POSITIVE', unit_risk: geom.unit_risk, reward_distance: geom.reward_distance, reward_risk_ratio: null };
  }

  return {
    ...base, valid: true, reason: null,
    unit_risk: geom.unit_risk, reward_distance: geom.reward_distance, reward_risk_ratio: geom.reward_risk_ratio
  };
}

