// nachgebildet. Fuer mean_reversion/trend_following/breakout ist dominant.evidence seit
// Schritt 4J.1 immer vollstaendig und PIT-sicher vorhanden - der Fallback bleibt dort
// trotzdem als woertliche WF06-Uebernahme erhalten (inert, da nie leer/undefined).
//
// AVAILABLE_DATA_LIVE_REPLAY (Phase 7): ein post-hoc rekonstruierter News-Evidence-Wert
// (TRUE oder FALSE) darf technisch durchgerechnet werden (newsEvidenceState.pit_complete
// = false), das Ergebnis ist dann aber NIE live_parity_eligible=true, unabhaengig vom
// numerischen Ergebnis.
//
// Fundamental-Wiederverwendung (Phase 10/11, frisch verifiziert): WF06s
// `fundTrend.momentum.revisions_verglichen` ist exakt `rows.length` (kein Offset, beide
// Zweige von fundamentalTrend() identisch), was exakt Schritt 4Es
// getLiveParityFundTrend().snapshot_count entspricht (= inWindow.length, beide Zweige,
// ebenfalls kein Offset). `fundTrend.quality.data_quality` ist AUSSCHLIESSLICH aus dieser
// Anzahl ableitbar (invalid < 2, limited 2-4, valid >= 5) - hier als
// liveParityFundQualityFromSnapshotCount() nachgebildet, KEINE zweite
// Fundamental-Implementierung, nur eine triviale Schwellwert-Ableitung aus dem bereits
// vorhandenen snapshot_count.
//
// KNOWN_PARITY_GAPS unveraendert fortgefuehrt (siehe Schritte 4B-4J.1), Gap #1 bleibt im
// erweiterten Scope (raw_score + direction + evidence), Gap #7 unveraendert
// (news_event Geometry/Evidence-Abhaengigkeiten).
// ============================================================

const LIVE_PARITY_EVIDENCE_GROUP_TOTAL = 6; // TOTAL_MOEGLICHE_GRUPPEN, bewusst nicht auf 8 korrigiert

function classifyLiveParityEvidenceGroup(text) {
  const t = String(text || '').toLowerCase();
  if (t.includes('rsi') || t.includes('bollinger')) return 'overextension';
  if (t.includes('macd')) return 'momentum';
  if (t.includes('ema20') || t.includes('ema200') || t.includes('trend')) return 'trend_confirmation';
  if (t.includes('volumen')) return 'volume';
  if (t.includes('bewegung') || t.includes('52-wochen') || t.includes('ausbruch')) return 'price_move';
  return 'other';
}

function liveParityFundQualityFromSnapshotCount(snapshotCount) {
  if (!(snapshotCount >= 2)) return 'invalid';
  return snapshotCount >= 5 ? 'valid' : 'limited';
}

// input: {
//   dominant:        { strategy, evidence, data_quality_score, ... } | null
//   fundTrend:       { snapshot_count, ... }  // aus getLiveParityFundTrend(), Schritt 4E
//   newsEvidenceState: { status: 'NEWS_EVIDENCE_TRUE'|'NEWS_EVIDENCE_FALSE'|'NEWS_EVIDENCE_UNKNOWN',
//                        pit_complete: boolean, reason?: string }
// }
function calculateLiveParityEvidenceConfidence(input) {
  const dominant = input && input.dominant;
  const fundTrend = input && input.fundTrend;
  const newsEvidenceState = (input && input.newsEvidenceState) || { status: 'NEWS_EVIDENCE_UNKNOWN', pit_complete: false };

  if (!dominant) {
    return {
      status: 'INDETERMINATE_DOMINANT_EVIDENCE', evidence_confidence: null, pit_complete: false,
      live_parity_eligible: false, replay_mode: null, components: null
    };
  }

  if (dominant.strategy === 'news_event') {
    return {
      status: 'INDETERMINATE_DOMINANT_EVIDENCE', evidence_confidence: null, pit_complete: false,
      live_parity_eligible: false, replay_mode: null, components: null
    };
  }

  if (newsEvidenceState.status === 'NEWS_EVIDENCE_UNKNOWN') {
    return {
      status: 'INDETERMINATE_NEWS_EVIDENCE', evidence_confidence: null, pit_complete: false,
      live_parity_eligible: false, replay_mode: null, components: null
    };
  }

  const hatNews = newsEvidenceState.status === 'NEWS_EVIDENCE_TRUE';
  const isPosthocReplay = newsEvidenceState.pit_complete === false;

  const groups = new Set();
  for (const e of (dominant.evidence || [])) groups.add(classifyLiveParityEvidenceGroup(e));

  const snapshotCount = fundTrend && fundTrend.snapshot_count;
  const fundamentalQuality = liveParityFundQualityFromSnapshotCount(snapshotCount);
  const fundamentalGroupAdded = fundamentalQuality !== 'invalid';
  if (fundamentalGroupAdded) groups.add('fundamental');
  const newsGroupAdded = hatNews;
  if (newsGroupAdded) groups.add('news');

  const groupCount = groups.size;
  const groupFraction = groupCount / LIVE_PARITY_EVIDENCE_GROUP_TOTAL;

  const dq = Number(dominant.data_quality_score);
  const dataQualityMultiplier = !isNaN(dq) ? Math.max(0.3, dq) : 0.7;

  const revisionsVerglichen = snapshotCount;
  const fallzahl = revisionsVerglichen || 0;
  const revisionMultiplier = fallzahl < 3 ? 0.8 : 1;

  const preCapConfidence = groupFraction * dataQualityMultiplier * revisionMultiplier;
  const evidenceConfidenceValue = liveParityFundRound(Math.min(1, preCapConfidence), 3);

  return {
    status: 'EVIDENCE_CONFIDENCE_CALCULATED',
    evidence_confidence: evidenceConfidenceValue,
    pit_complete: !isPosthocReplay,
    live_parity_eligible: !isPosthocReplay,
    replay_mode: isPosthocReplay ? 'POSTHOC_AVAILABLE_DATA_REPLAY' : null,
    components: {
      evidence_groups: Array.from(groups),
      group_count: groupCount,
      group_fraction: groupFraction,
      data_quality_score: isNaN(dq) ? null : dq,
      data_quality_multiplier: dataQualityMultiplier,
      revisions_verglichen: revisionsVerglichen,
      revision_multiplier: revisionMultiplier,
      fundamental_group_added: fundamentalGroupAdded,
      news_group_added: newsGroupAdded,
      pre_cap_confidence: preCapConfidence
    }
  };
}

