//   "repariert" (Phase 1: keine kosmetische Grossrefaktorierung).
// - getLiveParityFitMultiplier()/calculateTradeGeometry() geben selbst snake_case
//   (fit_multiplier, regime_blocked) bzw. andere Feldnamen zurueck - beide werden nur
//   INDIREKT ueber selectLiveParityDominant()/buildLiveParityGeometry() konsumiert, der
//   Orchestrator ruft sie nicht selbst zusaetzlich auf (keine Doppelverwendung).
//
// combinedRegime wird dem Orchestrator als bereits fertig berechneter Wert uebergeben
// (nicht hier per computeLiveParityRegime()/regionRegimeHistorical() neu abgeleitet) - die
// Regime-Schicht selbst wurde in Schritt 4C bereits eigenstaendig golden-getestet
// (37/37 Matrix-Faelle + 9/10 reale Referenzen); dieser Audit prueft die Verkettung AB dem
// Regime-Wert, nicht die Regime-Berechnung selbst erneut.
//
// ============================================================
// PHASE 2 - KANONISCHES SHADOW-CANDIDATE-SCHEMA (siehe Rueckgabeform unten)
// ============================================================
// Nur tatsaechlich vorhandene Felder, keine Persistierung, keine DB-Migration.
//
// PHASE 11/12/13 - ELIGIBILITY-MODELL (bewusst FUENF getrennte Achsen, kein einzelnes
// Boolean, um KEINE Information zu verlieren):
//   execution_semantics_complete = alle aktuell aktiven LIVE-Regeln sind mit den
//     vorhandenen Inputs technisch vollstaendig ausfuehrbar (Dominant bestimmt, Geometry
//     gueltig, Fundamentalinput vorhanden, Evidence berechnet) - UNABHAENGIG davon, ob die
//     verwendete Regime-/Gewichts-KONFIGURATION selbst historisch "as-was" ist.
//   pit_data_complete = alle verwendeten ROHDATEN (Bars, Fundamentals, News) waren zum
//     Simulationstag D bereits bekannt (PIT-sicher) - schliesst NICHT die Policy/Matrix-
//     Version ein.
//   policy_as_was_complete = zusaetzlich ist auch die verwendete Regime-Matrix-/Konfig-
//     Version historisch nachweislich exakt die damalige (nicht nur "heutige, rueckwirkend
//     angewandte" Policy). Da KNOWN_PARITY_GAP #3 (strategy_regime_matrix ist NICHT
//     historisiert) fuer JEDEN Kandidaten mit fitMultiplier-Abhaengigkeit gilt, ist dieser
//     Wert nach aktuellem Stand IMMER false, sobald ein technischer Dominant beteiligt ist -
//     erwartungsgemaess (Auftrag: "Meine Erwartung: NEIN fuer historische AS-WAS-Behauptung"),
//     hier explizit bestaetigt, nicht angenommen.
//   strict_live_parity_eligible = execution_semantics_complete && pit_data_complete &&
//     policy_as_was_complete && keine INDETERMINATE-Komponente. Wegen policy_as_was_complete
//     ist dieser Wert nach aktuellem Systemstand fuer JEDEN Candidate strukturell false -
//     kein Fehler dieses Schritts, sondern der korrekte, erwartete Endzustand vor Schliessung
//     von Gap #3.
//   available_data_replay_eligible = execution_semantics_complete && pit_data_complete &&
//     keine INDETERMINATE-Komponente (policy_as_was_complete NICHT verlangt) - das ist der
//     tatsaechlich erreichbare Modus fuer historische Shadow-Checks im Entwicklungsfenster.
//
// PHASE 15 - STATUS-CODES (nur tatsaechlich benoetigte, keine Exceptions als Kontrollfluss):
//   READY, NO_TECHNICAL_SIGNAL, ALL_CANDIDATES_FILTERED, INDETERMINATE_NEWS_EVENT,
//   INDETERMINATE_NEWS_EVIDENCE, INDETERMINATE_NEWS_EVENT_DOMINANT_INCOMPLETE,
//   GEOMETRY_INVALID, FUNDAMENTAL_INPUT_INCOMPLETE, EVIDENCE_INPUT_INCOMPLETE
// ============================================================

const LIVE_PARITY_SHADOW_STATUS = {
  READY: 'READY',
  NO_TECHNICAL_SIGNAL: 'NO_TECHNICAL_SIGNAL',
  ALL_CANDIDATES_FILTERED: 'ALL_CANDIDATES_FILTERED',
  INDETERMINATE_NEWS_EVENT: 'INDETERMINATE_NEWS_EVENT',
  INDETERMINATE_NEWS_EVIDENCE: 'INDETERMINATE_NEWS_EVIDENCE',
  INDETERMINATE_NEWS_EVENT_DOMINANT_INCOMPLETE: 'INDETERMINATE_NEWS_EVENT_DOMINANT_INCOMPLETE',
  GEOMETRY_INVALID: 'GEOMETRY_INVALID',
  FUNDAMENTAL_INPUT_INCOMPLETE: 'FUNDAMENTAL_INPUT_INCOMPLETE',
  EVIDENCE_INPUT_INCOMPLETE: 'EVIDENCE_INPUT_INCOMPLETE'
};

function shadowResult(status, extra) {
  return Object.assign({
    status, ticker: null, business_day: null,
    strategy: null, direction: null,
    raw_score: null, evidence: null, data_quality_score: null,
    combined_regime: null, fit_multiplier: null, regime_blocked: null, adjusted_score: null,
    expected_horizon_days: null,
    geometry: null, fundamental: null,
    opportunity_score: null, evidence_confidence: null,
    news: null,
    eligibility: {
      dominant_determined: false, geometry_complete: false, evidence_complete: false,
      execution_semantics_complete: false, pit_data_complete: false,
      policy_as_was_complete: false, strict_live_parity_eligible: false,
      available_data_replay_eligible: false
    },
    diagnostics: {}
  }, extra || {});
}

// input: {
//   ticker, businessDay,
//   technicalCandidates: [...],       // = computeLiveParitySignals(bars).signals, extern
//                                      // berechnet (siehe Phase-1-Fund oben)
//   combinedRegime,                   // extern berechnet (Schritt 4C, bereits verifiziert)
//   fundamentalRows, decisionTimeIso, // fuer getLiveParityFundTrend()
//   newsEventState,                   // Tri-State aus Schritt 4F.1 (fuer selectLiveParityDominant)
//   newsEvidenceState,                // Tri-State aus Schritt 4J.2 (fuer evidence_confidence)
//   entryReferencePrice,              // PIT-letzter Close (== WF06 kursWert)
//   policyAsWasComplete               // optional, Default false (siehe Gap #3 oben) -
//                                      // NUR fuer zukuenftige Tests, falls Gap #3 einmal
//                                      // geschlossen wird; heute niemals true zu setzen.
// }
function buildLiveParityShadowCandidate(input) {
  const ticker = input && input.ticker;
  const businessDay = input && input.businessDay;
  const technicalCandidates = (input && input.technicalCandidates) || [];
  const combinedRegime = input && input.combinedRegime;
  const fundamentalRows = (input && input.fundamentalRows) || [];
  const decisionTimeIso = input && input.decisionTimeIso;
  const newsEventState = input && input.newsEventState;
  const newsEvidenceState = input && input.newsEvidenceState;
  const entryReferencePrice = input && input.entryReferencePrice;
  const policyAsWasComplete = !!(input && input.policyAsWasComplete);

  if (technicalCandidates.length === 0) {
    return shadowResult(LIVE_PARITY_SHADOW_STATUS.NO_TECHNICAL_SIGNAL, { ticker, business_day: businessDay });
  }

  // Phase 4: Regime/Fit-Anreicherung - KEINE In-Place-Mutation der uebergebenen Kandidaten,
  // selectLiveParityDominant() erzeugt ohnehin neue Objekte via {...c, ...}. Wir uebergeben
  // die Kandidaten unveraendert; die Anreicherung passiert innerhalb von
  // selectLiveParityDominant() selbst (das ruft getLiveParityFitMultiplier() intern auf).
  const dominantResult = selectLiveParityDominant({
    candidates: technicalCandidates,
    newsEventState: newsEventState,
    combinedRegime: combinedRegime,
    mode: 'LIVE_PARITY'
  });

  // Phase 5: UNKNOWN News Event MUSS die Pipeline hier stoppen - keine Geometry, kein
  // Opportunity Score, keine Evidence Confidence.
  if (dominantResult.status === 'INDETERMINATE_NEWS_EVENT') {
    return shadowResult(LIVE_PARITY_SHADOW_STATUS.INDETERMINATE_NEWS_EVENT, {
      ticker, business_day: businessDay, combined_regime: combinedRegime,
      news: { event_status: newsEventState && newsEventState.status, evidence_status: null, pit_complete: false, replay_mode: null },
      diagnostics: { dominant_status: dominantResult.status }
    });
  }
  if (dominantResult.status === 'NO_USABLE_CANDIDATE') {
    return shadowResult(LIVE_PARITY_SHADOW_STATUS.ALL_CANDIDATES_FILTERED, {
      ticker, business_day: businessDay, combined_regime: combinedRegime,
      diagnostics: { dominant_status: dominantResult.status, rejected: dominantResult.rejected_candidates }
    });
  }

  const dominant = dominantResult.dominant;

  // Phase 6: news_event als Dominant ist strukturell noch NICHT vollstaendig (Geometry +
  // Evidence fehlen, Schritt 4I/4J.1) - fail-closed, KEINE technische Ersatz-Geometry.
  if (dominant.strategy === 'news_event') {
    return shadowResult(LIVE_PARITY_SHADOW_STATUS.INDETERMINATE_NEWS_EVENT_DOMINANT_INCOMPLETE, {
      ticker, business_day: businessDay, strategy: dominant.strategy, direction: dominant.direction,
      combined_regime: combinedRegime,
      news: { event_status: dominantResult.status, evidence_status: null, pit_complete: false, replay_mode: null },
      diagnostics: { dominant_status: dominantResult.status, note: 'news_event Geometry/Evidence nicht LIVE_PARITY-vorbereitet (Schritte 4I/4J.1)' }
    });
  }

  // Phase 7: Fundamental-Integration - keine zweite Implementierung, 1:1 Wiederverwendung.
  const fundTrend = getLiveParityFundTrend(fundamentalRows, businessDay, decisionTimeIso);
  const richtung = dominant.direction === 'long' ? 'kauf' : 'verkauf'; // Adapter (Phase 1)
  const fundBonus = getLiveParityFundBonus(richtung, fundTrend.direction);

  // Phase 8: Geometry gehoert garantiert zum tatsaechlich gewaehlten Dominant (dominant.strategy/
  // direction/stop_price/target_price kommen alle aus DEMSELBEN dominant-Objekt, kein
  // Cross-Candidate-Zugriff moeglich, da buildLiveParityGeometry() nur dieses eine Objekt liest).
  const geometry = buildLiveParityGeometry({
    dominantStatus: dominantResult.status, dominant, entryReferencePrice
  });
  if (!geometry.valid) {
    return shadowResult(LIVE_PARITY_SHADOW_STATUS.GEOMETRY_INVALID, {
      ticker, business_day: businessDay, strategy: dominant.strategy, direction: dominant.direction,
      raw_score: dominant.raw_score, evidence: dominant.evidence, data_quality_score: dominant.data_quality_score,
      combined_regime: combinedRegime, fit_multiplier: dominant.fitMultiplier, regime_blocked: dominant.regimeBlocked,
      adjusted_score: dominant.adjustedScore, expected_horizon_days: dominant.expected_horizon_days,
      geometry, diagnostics: { geometry_reason: geometry.reason }
    });
  }

  // Phase 9: Opportunity Score - EXAKT aus dominant.raw_score/dominant.fitMultiplier/
  // fundBonus/geometry.reward_risk_ratio (Adapter: snake_case raw_score -> camelCase
  // rawScore-Parametername, siehe Phase-1-Fund oben). Keine Research-candidateGeometry.
  const opportunityResult = calculateLiveParityOpportunityScore({
    rawScore: dominant.raw_score, fitMultiplier: dominant.fitMultiplier, fundBonus: fundBonus,
    rewardRiskRatio: geometry.reward_risk_ratio, riskAvailable: geometry.valid
  });

  // Phase 10: Evidence Confidence - UNKNOWN News Evidence -> INDETERMINATE, keine implizite FALSE-Annahme.
  const evidenceResult = calculateLiveParityEvidenceConfidence({
    dominant, fundTrend, newsEvidenceState
  });
  if (evidenceResult.status === 'INDETERMINATE_NEWS_EVIDENCE' || evidenceResult.status === 'INDETERMINATE_DOMINANT_EVIDENCE') {
    return shadowResult(
      evidenceResult.status === 'INDETERMINATE_NEWS_EVIDENCE' ? LIVE_PARITY_SHADOW_STATUS.INDETERMINATE_NEWS_EVIDENCE : LIVE_PARITY_SHADOW_STATUS.EVIDENCE_INPUT_INCOMPLETE,
      {
        ticker, business_day: businessDay, strategy: dominant.strategy, direction: dominant.direction,
        raw_score: dominant.raw_score, evidence: dominant.evidence, data_quality_score: dominant.data_quality_score,
        combined_regime: combinedRegime, fit_multiplier: dominant.fitMultiplier, regime_blocked: dominant.regimeBlocked,
        adjusted_score: dominant.adjustedScore, expected_horizon_days: dominant.expected_horizon_days,
        geometry,
        fundamental: { direction: fundTrend.direction, snapshot_count: fundTrend.snapshot_count, fund_bonus: fundBonus, pit_complete: fundTrend.pit_complete, policy_mode: fundTrend.policy_mode },
        opportunity_score: opportunityResult.opportunity_score,
        news: { event_status: dominantResult.status, evidence_status: evidenceResult.status, pit_complete: false, replay_mode: newsEvidenceState && newsEvidenceState.pit_complete === false ? 'POSTHOC_AVAILABLE_DATA_REPLAY' : null },
        diagnostics: { evidence_status: evidenceResult.status }
      }
    );
  }

  // Phase 11: newsEventState und newsEvidenceState bleiben BEWUSST getrennte Objekte -
  // niemals aus dem anderen abgeleitet (z.B. NICHT newsEvidenceState = Boolean(newsEventState)),
  // weil eine widerspruechliche Tages-News (Schritt 4J) hatNews=true UND
  // news_event-Candidate=null gleichzeitig erzeugen kann - dieser reale WF06-Fall bleibt hier
  // modellierbar, da beide States separat als Input hereinkommen.

  // Phase 12/13: Eligibility-Modell, fuenf Achsen.
  const executionSemanticsComplete = true; // alle Layer bis hierher erfolgreich durchlaufen
  const pitDataComplete = !!(fundTrend.pit_complete) && newsEvidenceState && newsEvidenceState.pit_complete === true && geometry.pit_complete === true;
  // Gap #3: strategy_regime_matrix ist nicht historisiert - policyAsWasComplete bleibt heute
  // strukturell IMMER false fuer jeden fitMultiplier-abhaengigen Candidate, sofern nicht
  // explizit (nur fuer zukuenftige Tests nach Schliessung des Gaps) anders gesetzt.
  const policyAsWas = policyAsWasComplete;
  const strictLiveParityEligible = executionSemanticsComplete && pitDataComplete && policyAsWas;
  // WICHTIG (waehrend der realen Phase-18-Laeufe gefunden): available_data_replay_eligible
  // darf NICHT an pitDataComplete gekoppelt sein - der ganze Zweck von
  // AVAILABLE_DATA_LIVE_REPLAY ist, dass auch mit post-hoc/nicht-PIT-sicheren Daten
  // (z.B. newsEvidenceState.pit_complete=false) ein Zahlenwert fuer retrospektive Analyse
  // entstehen darf. Waere dieser Wert an pitDataComplete gekoppelt, koennte
  // AVAILABLE_DATA_LIVE_REPLAY nie mehr liefern als strict PIT ohnehin schon leistet -
  // das wuerde die eigentliche Funktion dieser zweiten Achse zunichtemachen. Hier bewusst
  // nur an "erfolgreich bis READY durchgelaufen" gekoppelt.
  const availableDataReplayEligible = executionSemanticsComplete;

  const isPosthocNews = newsEvidenceState && newsEvidenceState.pit_complete === false;

  return {
    status: LIVE_PARITY_SHADOW_STATUS.READY,
    ticker, business_day: businessDay,
    strategy: dominant.strategy, direction: dominant.direction,
    raw_score: dominant.raw_score, evidence: dominant.evidence, data_quality_score: dominant.data_quality_score,
    combined_regime: combinedRegime, fit_multiplier: dominant.fitMultiplier, regime_blocked: dominant.regimeBlocked,
    adjusted_score: dominant.adjustedScore, expected_horizon_days: dominant.expected_horizon_days,
    geometry: {
      entry_reference_price: geometry.entry_reference_price, entry_zone_low: geometry.entry_zone_low,
      entry_zone_high: geometry.entry_zone_high, stop_price: geometry.stop_price, target_price: geometry.target_price,
      reward_risk_ratio: geometry.reward_risk_ratio
    },
    fundamental: { direction: fundTrend.direction, snapshot_count: fundTrend.snapshot_count, fund_bonus: fundBonus, pit_complete: fundTrend.pit_complete, policy_mode: fundTrend.policy_mode },
    opportunity_score: opportunityResult.opportunity_score,
    evidence_confidence: evidenceResult.evidence_confidence,
    news: {
      event_status: dominantResult.status, evidence_status: evidenceResult.status,
      pit_complete: !isPosthocNews, replay_mode: isPosthocNews ? 'POSTHOC_AVAILABLE_DATA_REPLAY' : null
    },
    eligibility: {
      dominant_determined: true, geometry_complete: true, evidence_complete: true,
      execution_semantics_complete: executionSemanticsComplete,
      pit_data_complete: pitDataComplete,
      policy_as_was_complete: policyAsWas,
      strict_live_parity_eligible: strictLiveParityEligible,
      available_data_replay_eligible: availableDataReplayEligible
    },
    diagnostics: {
      opportunity_components: opportunityResult.components,
      evidence_components: evidenceResult.components,
      dominant_status: dominantResult.status,
      dominant_usable_count: dominantResult.usable_count
    }
  };
}

// LIVE_PARITY - Schritt 4L: mappt einen buildLiveParityShadowCandidate()-Output auf die
// bestehende trading.simulation_decision_log-Zeilenform (Phase 13/14) - keine neue Tabelle,
// keine Migration, KEINE Aenderung an "Baue SQL fuer Paket-Ergebnisse" (dessen
// decisionLogRows-INSERT-Schleife ist bereits vollstaendig generisch/feldbasiert).
// decision_stage='LIVE_PARITY_SHADOW' ist der maschinenlesbare Diskriminator (Phase 6/14:
// Research- und Shadow-Zeilen duerfen nicht in DERSELBEN Zeile vermischt werden - hier durch
// vollstaendig getrennte, klar markierte Zeilen erfuellt, niemals in denselben Feldern
// zusammengefuehrt). decision='SHADOW_LOGGED' ist bewusst ein NEUER, eindeutig erkennbarer
// Wert (nicht ACCEPTED/REJECTED/BLOCKED/NO_FILL) - jede vorhandene Auswertung, die nach
// decision filtert, muss diesen Wert erkennen bzw. ignorieren; VOR einer echten
// Aktivierung dieses Modus auf einem realen Lauf sollten nachgelagerte Dashboards/Queries
// darauf geprueft werden (in diesem Schritt nicht auditiert - kein bestehender Lauf nutzt
// den Modus).
function buildShadowDecisionLogRow(ticker, day, shadowResult, shadowSizing, shadowSektor, shadowRegion, shadowCurrency) {
  const geom = shadowResult.geometry;
  const elig = shadowResult.eligibility || {};
  const knownGapFlags = ['GAP_POLICY_MATRIX_CURRENT_REPLAY']; // LIVE_PARITY Schritt 4L.2: GAP_FUNDAMENTALS_NOT_WIRED_IN_SHADOW_MODE geloest, Fundamentals sind jetzt verdrahtet (siehe fundamentalLiveParityRowsByTicker)
  if (shadowResult.strategy === 'breakout') { knownGapFlags.push('GAP_52W_SOURCE'); knownGapFlags.push('GAP_VOLUME_WINDOW'); }
  if (shadowResult.status === 'INDETERMINATE_NEWS_EVENT' || shadowResult.status === 'INDETERMINATE_NEWS_EVIDENCE') knownGapFlags.push('GAP_NEWS_EVENT_PIT');
  if (shadowResult.status === 'INDETERMINATE_NEWS_EVENT_DOMINANT_INCOMPLETE') { knownGapFlags.push('GAP_NEWS_EVENT_DOMINANT_INCOMPLETE'); knownGapFlags.push('GAP_NEWS_EVENT_PIT'); }
  if (shadowResult.news && shadowResult.news.replay_mode === 'POSTHOC_AVAILABLE_DATA_REPLAY') knownGapFlags.push('GAP_NEWS_EVENT_PIT');

  return {
    day, ticker, strategy: shadowResult.strategy, direction: shadowResult.direction,
    decision: 'SHADOW_LOGGED', reason: shadowResult.status,
    raw_score: shadowResult.raw_score,
    // LIVE_PARITY Schritt 4N (2026-09-12): WF14-Sizing-Parity fuer Shadow-Kandidaten. sizePosition()
    // ist dieselbe, unveraenderte Funktion, die RESEARCH_BASELINE fuer echte Kandidaten verwendet -
    // hier isoliert (openPositionsState=[]) aufgerufen, da WF17 keine Sicht auf den echten WF14/
    // paper_trades-Portfoliozustand hat (andere Tabelle, anderer Workflow). Das ist bewusst KEINE
    // vollstaendige WF14-Portfolio-Pruefung (Sektor-/Risiko-/Korrelationslimits gegen ANDERE
    // Kandidaten desselben Tages fehlen hier) - nur die EINZELTRADE-Sizing-Formel, 1:1 identisch zum
    // aktiven WF14-Engine-Pfad (sizing_mode='clamp', siehe trading_engine/position_sizing.py
    // _size_position_clamp() - dieselbe Formel, in Python portiert). Die vollstaendige sequentielle
    // Portfolio-Pruefung ist Aufgabe eines separaten Single-Day-Harness (4N Phase 13+), nicht dieser
    // WF17-Zeile. null, wenn shadowSizing fehlt (kein READY-Status oder kein sizePosition()-Aufruf).
    theoretical_quantity: shadowSizing && shadowSizing.theoretical_quantity != null ? shadowSizing.theoretical_quantity : null,
    actual_quantity: shadowSizing && shadowSizing.actual_quantity != null ? shadowSizing.actual_quantity : null,
    position_value: shadowSizing && shadowSizing.position_value != null ? shadowSizing.position_value : null,
    adjusted_score: shadowResult.adjusted_score, market_regime: null, combined_regime: shadowResult.combined_regime,
    fit_multiplier: shadowResult.fit_multiplier, direction_regime_alignment: null,
    rule_version: 'live-parity-shadow-v1',
    entry_reference_price: geom ? geom.entry_reference_price : null,
    entry_zone_low: geom ? geom.entry_zone_low : null, entry_zone_high: geom ? geom.entry_zone_high : null,
    stop_price: geom ? geom.stop_price : null, target_price: geom ? geom.target_price : null,
    reward_risk_ratio: geom ? geom.reward_risk_ratio : null,
    atr_value: null,
    risk_amount: shadowSizing && shadowSizing.actual_risk_amount != null ? shadowSizing.actual_risk_amount : null,
    unit_risk: shadowSizing && shadowSizing.unit_risk != null ? shadowSizing.unit_risk : null,
    quantity_by_risk: shadowSizing && shadowSizing.theoretical_quantity != null ? shadowSizing.theoretical_quantity : null,
    quantity_by_value: shadowSizing && shadowSizing.quantity_by_value != null ? shadowSizing.quantity_by_value : null,
    limiting_factor: shadowSizing ? (shadowSizing.veto || shadowSizing.binding_limit || shadowSizing.clamp_reason || null) : null,
    decision_stage: 'LIVE_PARITY_SHADOW', sequence_index: null, blockers_json: [],
    simulation_recommendation_id: null, simulation_order_id: null, simulation_trade_id: null,
    diagnostics_json: {
      live_parity_shadow: true, status: shadowResult.status,
      opportunity_score: shadowResult.opportunity_score, evidence_confidence: shadowResult.evidence_confidence,
      data_quality_score: shadowResult.data_quality_score, regime_blocked: shadowResult.regime_blocked,
      fundamental: shadowResult.fundamental, news: shadowResult.news, eligibility: elig,
      known_gap_flags: knownGapFlags, component_diagnostics: shadowResult.diagnostics,
      sizing: shadowSizing ? {
        quantity: shadowSizing.actual_quantity != null ? shadowSizing.actual_quantity : null,
        risk_amount: shadowSizing.actual_risk_amount != null ? shadowSizing.actual_risk_amount : null,
        position_value: shadowSizing.position_value != null ? shadowSizing.position_value : null,
        sizing_source: 'wf17_sizePosition_isolated', sizing_mode: 'clamp',
        sizing_context: 'isolated_single_candidate_no_portfolio',
        sizing_clamped: !!shadowSizing.clamped, sizing_reason: shadowSizing.veto || shadowSizing.clamp_reason || null,
        policy_mode: 'CURRENT_POLICY_REPLAY'
      } : null,
      sector: shadowSektor || null, region: shadowRegion || null, currency: shadowCurrency || null,
      is_theoretical: true
    }
  };
}


