// Reproduziert isoliert die produktive LEGACY-Semantik von WF14 "Job B: Ausfuehrung/
// Exit simulieren" (ACTIVE_PATH=LEGACY, bewiesen 4O.1 ueber TRADING_ENGINE_EXECUTION_
// ENABLED=false). KEIN Trailing-Stop, KEIN Engine-Kostenmodell, KEINE Research-
// Ausfuehrungslogik - reine 1:1-Portierung der Legacy-JS-Formeln in eine pure,
// side-effect-freie Funktion.
//
// PURE: kein DB-Zugriff, kein HTTP, keine Mutation des Eingabe-Objekts, kein
// Aufruf von Date.now()/new Date() intern (evalTimeIso wird explizit uebergeben,
// damit die Funktion fuer historischen Replay deterministisch reproduzierbar bleibt -
// die produktive Legacy-Funktion selbst verwendet echtes now(), das ist fuer
// CURRENT_POLICY_REPLAY explizit als Modellannahme dokumentiert, siehe policy_mode).
//
// 0 aktive Call-Sites (Phase 33) - dieses Modul wird von keinem WF17-Codepfad
// aufgerufen, weder RESEARCH_BASELINE noch AVAILABLE_DATA_LIVE_REPLAY.
// ============================================================================

function round(v, d) {
  if (v === null || v === undefined || isNaN(v)) return null;
  return parseFloat(Number(v).toFixed(d === undefined ? 4 : d));
}
function num(v) {
  const n = Number(v);
  return v === null || v === undefined || v === '' || isNaN(n) ? null : n;
}

const CORE_STATUSES = new Set(['proposed', 'open', 'closed', 'expired_unfilled', 'data_error']);
const NON_CORE_STATUSES = new Set(['blocked', 'awaiting_confirmation', 'cancelled']);
const TERMINAL_STATUSES = new Set(['closed', 'expired_unfilled']);

function makeDiagnostics(businessDay, statusBefore, extra) {
  return Object.assign({
    business_day: businessDay, status_before: statusBefore, status_after: statusBefore,
    fill_checked: false, fill_touched: false, fill_price: null,
    exit_checked: false, stop_touched: false, target_touched: false,
    ambiguous: false, ambiguous_policy: null,
    exit_reason: null, exit_price: null,
    entry_fee: null, entry_slippage: null, exit_fee: null, exit_slippage: null,
    gross_pnl: null, net_pnl: null,
    data_error_count: null,
    policy_mode: 'CURRENT_POLICY_REPLAY'
  }, extra || {});
}

function noAction(trade, businessDay, reasonCode) {
  return {
    trade_id: trade.trade_id, business_day: businessDay,
    status_before: trade.status, status_after: trade.status,
    transition: 'NO_ACTION',
    nextTradeState: trade,
    events: [],
    diagnostics: Object.assign(makeDiagnostics(businessDay, trade.status), { no_action_reason: reasonCode })
  };
}

/**
 * Verarbeitet GENAU EINEN ShadowTrade gegen GENAU EINEN Business Day (Phase 4:
 * kein Mehrtages-Loop hier). Mutiert `trade` NICHT - liefert einen neuen
 * nextTradeState zurueck (Phase 30, Immutability).
 *
 * @param {object} trade ShadowTrade (siehe Modul-Dokumentation/4O.2 Phase 1)
 * @param {object|null} bar ShadowDailyBar {trading_date, open, high, low, close, data_quality_status} oder null
 * @param {object} config ShadowExecutionConfig {ambiguous_bar_policy_code, default_fees_bps, default_slippage_bps, max_data_error_retries}
 * @param {object|null} currentStrategySignal {ticker, strategy, direction} oder null (Phase 18, kein DB-Lookup hier)
 * @param {string} businessDay 'YYYY-MM-DD' - der zu verarbeitende Handelstag
 * @param {string} evalTimeIso ISO-Timestamp, ersetzt produktives `now()` (deterministisch)
 */
function processShadowTradeForDay(trade, bar, config, currentStrategySignal, businessDay, evalTimeIso) {
  const evalTime = new Date(evalTimeIso);

  // --- Phase 22: Nicht-Kernstatuses - sicheres NO_ACTION, keine neue Semantik erfinden ---
  if (NON_CORE_STATUSES.has(trade.status)) {
    return noAction(trade, businessDay, 'UNSUPPORTED_OR_INACTIVE_STATE');
  }
  // --- Phase 21: Idempotenz - terminale Zustaende erneut verarbeitet -> NO_ACTION ---
  if (TERMINAL_STATUSES.has(trade.status)) {
    return noAction(trade, businessDay, 'ALREADY_TERMINAL');
  }
  if (!CORE_STATUSES.has(trade.status)) {
    return noAction(trade, businessDay, 'UNKNOWN_STATUS');
  }

  // --- Phase 6: Bar-Validierung exakt wie Legacy Job B ---
  const barInvalid = !bar || bar.open == null || bar.high == null || bar.low == null || bar.close == null;
  const sessionIncomplete = bar && bar.data_quality_status === 'session_incomplete';

  if (barInvalid) {
    if (trade.status === 'open' || trade.status === 'proposed') {
      const newCount = (Number(trade.data_error_count) || 0) + 1;
      const eskaliert = newCount >= config.max_data_error_retries;
      const newStatus = eskaliert ? 'data_error_final' : 'data_error';
      const preErrorStatus = trade.status === 'data_error' ? trade.pre_data_error_status : trade.status;
      const nextTradeState = Object.assign({}, trade, {
        status: newStatus, data_error_count: newCount,
        data_error_first_at: trade.data_error_first_at || evalTimeIso,
        data_error_last_at: evalTimeIso,
        pre_data_error_status: preErrorStatus
      });
      const events = [{ event_type: eskaliert ? 'data_error_escalated' : 'data_error_flagged', old_status: trade.status, new_status: eskaliert ? 'data_error_final' : trade.status, details: { reason: 'keine gueltige Tageskerze heute', versuch: newCount }, business_date: businessDay }];
      return {
        trade_id: trade.trade_id, business_day: businessDay,
        status_before: trade.status, status_after: newStatus,
        transition: eskaliert ? 'DATA_ERROR_FINAL' : 'DATA_ERROR',
        nextTradeState, events,
        diagnostics: makeDiagnostics(businessDay, trade.status, { status_after: newStatus, data_error_count: newCount })
      };
    }
    return noAction(trade, businessDay, 'MISSING_CANDLE_NON_ACTIVE_TRADE');
  }
  if (sessionIncomplete) {
    return noAction(trade, businessDay, 'SESSION_INCOMPLETE');
  }

  // --- Phase 7: data_error Recovery - Status zurueck, aber KEIN Fill/Exit im selben Aufruf ---
  if (trade.status === 'data_error') {
    const restoredStatus = trade.pre_data_error_status || 'open';
    const nextTradeState = Object.assign({}, trade, { status: restoredStatus, pre_data_error_status: null });
    const events = [{ event_type: 'data_error_recovered', old_status: 'data_error', new_status: restoredStatus, details: { versuche_bis_wiederherstellung: trade.data_error_count || 0 }, business_date: businessDay }];
    return {
      trade_id: trade.trade_id, business_day: businessDay,
      status_before: 'data_error', status_after: restoredStatus,
      transition: 'DATA_ERROR_RECOVERED',
      nextTradeState, events,
      diagnostics: makeDiagnostics(businessDay, 'data_error', { status_after: restoredStatus })
    };
  }

  const open = num(bar.open), high = num(bar.high), low = num(bar.low), close = num(bar.close);
  const richtungLong = trade.direction === 'long';
  const fees = config.default_fees_bps, slip = config.default_slippage_bps;
  function fee(value) { return round(value * (fees / 10000), 2); }
  function slippage(value) { return round(value * (slip / 10000), 2); }

  let workingTrade = Object.assign({}, trade);
  let entryFeeForClose = num(trade.entry_fee), entrySlippageForClose = num(trade.entry_slippage);
  let entryAmbiguous = false, filledThisBar = false;
  const diag = makeDiagnostics(businessDay, trade.status);
  const events = [];

  // ============================================================
  // Phase 5: Eligibility - proposed nur fillbar wenn decision_date < business_day
  // (repliziert die SQL-WHERE-Klausel "decision_time::date < heute" der produktiven
  // Trade-Ladequery, die in Legacy Job B *vor* der JS-Schleife greift)
  // ============================================================
  if (trade.status === 'proposed' && !(trade.decision_date < businessDay)) {
    return noAction(trade, businessDay, 'SAME_DAY_PROPOSAL_NOT_ELIGIBLE');
  }

  if (trade.status === 'proposed') {
    diag.fill_checked = true;
    const zoneLow = num(trade.zone_low), zoneHigh = num(trade.zone_high);
    let gefuellt = false, fillPrice = null, ambiguous = false;
    if (zoneLow !== null && zoneHigh !== null) {
      const beruehrt = low <= zoneHigh && high >= zoneLow;
      diag.fill_touched = beruehrt;
      if (beruehrt) {
        gefuellt = true;
        if (open >= zoneLow && open <= zoneHigh) fillPrice = open;
        else if (open < zoneLow) fillPrice = zoneLow;
        else { fillPrice = richtungLong ? zoneHigh : zoneLow; ambiguous = true; }
      }
    }
    if (gefuellt) {
      const entryFee = fee(fillPrice * trade.quantity);
      const entrySlippage = slippage(fillPrice * trade.quantity);
      events.push({ event_type: 'fill', old_status: 'proposed', new_status: 'open', details: { fillPrice, ambiguous }, business_date: businessDay });
      workingTrade = Object.assign({}, workingTrade, {
        status: 'open', entry_price: fillPrice, entry_date: businessDay,
        stop_price_current: trade.stop_price_initial,
        entry_fee: entryFee, entry_slippage: entrySlippage
      });
      entryFeeForClose = entryFee; entrySlippageForClose = entrySlippage;
      entryAmbiguous = ambiguous; filledThisBar = true;
      diag.fill_price = fillPrice; diag.ambiguous = diag.ambiguous || ambiguous;
      diag.entry_fee = entryFee; diag.entry_slippage = entrySlippage;
    } else {
      const abgelaufen = (trade.time_stop_at && new Date(trade.time_stop_at) <= evalTime) || (trade.thesis_expires_at && new Date(trade.thesis_expires_at) <= evalTime);
      if (abgelaufen) {
        const nextTradeState = Object.assign({}, trade, { status: 'expired_unfilled' });
        events.push({ event_type: 'expired_unfilled', old_status: 'proposed', new_status: 'expired_unfilled', details: {}, business_date: businessDay });
        return {
          trade_id: trade.trade_id, business_day: businessDay,
          status_before: 'proposed', status_after: 'expired_unfilled',
          transition: 'EXPIRED_UNFILLED', nextTradeState, events,
          diagnostics: Object.assign(diag, { status_after: 'expired_unfilled' })
        };
      }
      return {
        trade_id: trade.trade_id, business_day: businessDay,
        status_before: 'proposed', status_after: 'proposed',
        transition: 'NO_ACTION', nextTradeState: trade, events: [],
        diagnostics: diag
      };
    }
  }

  // ============================================================
  // Exit-Engine: fuer 'open' (bereits vorher ODER gerade in diesem Aufruf gefuellt)
  // ============================================================
  if (workingTrade.status === 'open') {
    diag.exit_checked = true;
    const entry = num(workingTrade.entry_price);
    const stop = num(workingTrade.stop_price_current != null ? workingTrade.stop_price_current : workingTrade.stop_price_initial);
    const target = num(workingTrade.target_price);
    const qty = num(workingTrade.quantity) || 0;

    const stopBeruehrt = richtungLong ? low <= stop : high >= stop;
    const targetBeruehrt = richtungLong ? high >= target : low <= target;
    diag.stop_touched = stopBeruehrt; diag.target_touched = targetBeruehrt;
    const exitReasonsAll = [];
    let exitReason = null, exitPrice = null, ambiguous = entryAmbiguous;

    function stopRawExitPrice() {
      if (richtungLong) return open < stop ? open : stop;
      return open > stop ? open : stop;
    }
    if (stopBeruehrt && targetBeruehrt) {
      ambiguous = true;
      exitReasonsAll.push('stop_loss', 'target_reached', 'ambiguous_execution');
      diag.ambiguous_policy = config.ambiguous_bar_policy_code === 2 ? 'conservative_target_first' : 'conservative_stop_first';
      if (config.ambiguous_bar_policy_code === 2) { exitReason = 'target_reached'; exitPrice = target; }
      else { exitReason = 'stop_loss'; exitPrice = stopRawExitPrice(); }
    } else if (stopBeruehrt) {
      exitReason = 'stop_loss'; exitPrice = stopRawExitPrice(); exitReasonsAll.push('stop_loss');
    } else if (targetBeruehrt) {
      exitReason = 'target_reached'; exitPrice = target; exitReasonsAll.push('target_reached');
    }

    if (!exitReason && workingTrade.time_stop_at && new Date(workingTrade.time_stop_at) <= evalTime) { exitReason = 'time_stop'; exitPrice = close; exitReasonsAll.push('time_stop'); }
    if (!exitReason && workingTrade.thesis_expires_at && new Date(workingTrade.thesis_expires_at) <= evalTime) { exitReason = 'thesis_expired'; exitPrice = close; exitReasonsAll.push('thesis_expired'); }
    if (!exitReason && currentStrategySignal && currentStrategySignal.ticker === trade.ticker && currentStrategySignal.strategy === trade.strategy) {
      const stratDirection = currentStrategySignal.direction === 'long' ? 'long' : (currentStrategySignal.direction === 'short' ? 'short' : 'neutral');
      if (stratDirection !== 'neutral' && stratDirection !== trade.direction) { exitReason = 'opposite_signal'; exitPrice = close; exitReasonsAll.push('opposite_signal'); }
    }

    if (filledThisBar && exitReason) { ambiguous = true; exitReasonsAll.push('same_bar_fill_and_exit'); }
    diag.ambiguous = diag.ambiguous || ambiguous;

    if (exitReason) {
      const grossPnl = richtungLong ? (exitPrice - entry) * qty : (entry - exitPrice) * qty;
      const exitFee = fee(exitPrice * qty);
      const exitSlippage = slippage(exitPrice * qty);
      const financingCost = 0;
      const netPnl = round(grossPnl - (entryFeeForClose || 0) - (entrySlippageForClose || 0) - exitFee - exitSlippage - financingCost, 2);
      const returnPct = entry > 0 ? round((netPnl / (entry * qty)) * 100, 3) : null;
      const riskAmount = num(workingTrade.risk_amount);
      const rMultiple = riskAmount && riskAmount > 0 ? round(netPnl / riskAmount, 3) : null;

      const nextTradeState = Object.assign({}, workingTrade, {
        status: 'closed', exit_time: evalTimeIso, exit_price: exitPrice, exit_reason: exitReason,
        gross_pnl: round(grossPnl, 2), net_pnl: netPnl, return_pct: returnPct, realized_r_multiple: rMultiple,
        ambiguous_execution: ambiguous
        // risk_amount/position_value BEWUSST NICHT veraendert (Phase 16: STATIC)
      });

      diag.exit_reason = exitReason; diag.exit_price = exitPrice;
      diag.exit_fee = exitFee; diag.exit_slippage = exitSlippage;
      diag.gross_pnl = round(grossPnl, 2); diag.net_pnl = netPnl;
      diag.status_after = 'closed';

      return {
        trade_id: trade.trade_id, business_day: businessDay,
        status_before: trade.status, status_after: 'closed',
        transition: 'CLOSED', nextTradeState, events,
        diagnostics: Object.assign(diag, { return_pct: returnPct, r_multiple: rMultiple, exit_reasons_all: exitReasonsAll })
      };
    }

    // Kein Exit - Trade bleibt offen (ggf. gerade erst gefuellt)
    diag.status_after = 'open';
    return {
      trade_id: trade.trade_id, business_day: businessDay,
      status_before: trade.status, status_after: 'open',
      transition: filledThisBar ? 'FILLED' : 'NO_ACTION',
      nextTradeState: workingTrade, events,
      diagnostics: diag
    };
  }

  // Sollte nicht erreichbar sein (alle CORE_STATUSES oben behandelt) - fail closed.
  return noAction(trade, businessDay, 'UNREACHABLE_STATE_FALLTHROUGH');
}








function regimeAlignmentFor(directionValue, combinedRegimeValue) {
  if (!combinedRegimeValue) return null;
  const isBull = combinedRegimeValue.indexOf('bull_trend') === 0;
  const isBear = combinedRegimeValue === 'bear_trend';
  if (directionValue === 'long' && isBull) return 'aligned';
  if (directionValue === 'short' && isBear) return 'aligned';
  if (directionValue === 'long' && isBear) return 'conflict';
  if (directionValue === 'short' && isBull) return 'conflict';
  return 'neutral';
}
function simulateEntryFill(zoneLow, zoneHigh, bar) {
  const touched = bar.low <= zoneHigh && bar.high >= zoneLow;
  if (!touched) return { filled: false };
  let fillPrice, ambiguous = false;
  if (bar.open >= zoneLow && bar.open <= zoneHigh) { fillPrice = bar.open; }
  else if (bar.open < zoneLow) { fillPrice = zoneLow; ambiguous = true; }
  else { fillPrice = zoneHigh; ambiguous = true; }
  return { filled: true, price: fillPrice, ambiguous };
}
function checkExit(trade, bar, asOfDateStr, ambiguousBarPolicyCode, oppositeSignalToday) {
  const isLong = trade.direction === 'long';
  const stopTouched = isLong ? bar.low <= trade.stop_price : bar.high >= trade.stop_price;
  const targetTouched = isLong ? bar.high >= trade.target_price : bar.low <= trade.target_price;
  if (stopTouched && targetTouched) {
    const stopFirst = ambiguousBarPolicyCode !== 2;
    if (stopFirst) {
      const gapped = isLong ? bar.open < trade.stop_price : bar.open > trade.stop_price;
      return { exit: true, price: gapped ? bar.open : trade.stop_price, reason: 'stop_loss', ambiguous: true, gapThroughStop: gapped };
    }
    return { exit: true, price: trade.target_price, reason: 'take_profit', ambiguous: true, gapThroughStop: false };
  }
  if (stopTouched) {
    const gapped = isLong ? bar.open < trade.stop_price : bar.open > trade.stop_price;
    return { exit: true, price: gapped ? bar.open : trade.stop_price, reason: 'stop_loss', ambiguous: false, gapThroughStop: gapped };
  }
  if (targetTouched) return { exit: true, price: trade.target_price, reason: 'take_profit', ambiguous: false, gapThroughStop: false };
  if (trade.time_stop_at && asOfDateStr >= String(trade.time_stop_at).slice(0, 10)) return { exit: true, price: bar.close, reason: 'time_stop', ambiguous: false, gapThroughStop: false };
  if (oppositeSignalToday) return { exit: true, price: bar.close, reason: 'opposite_signal', ambiguous: false, gapThroughStop: false };
  return { exit: false };
}
// Phase 6 (2026-08-03) - Nachrichten-Einfluss, 1:1 aus wf17_core_logic.js/wf17_test_core.js
// (7 Unit-Tests) portiert. Vereinfacht analog zur Phase-4-Entscheidung: kein Regime-Matrix-
// fitMultiplier, kein additiver riskScore, keine gestaffelten Verfallsfenster je Strategie -
// das SQL-seitige "gleicher Handelstag UND vor dem Datenstichtag"-Fenster (siehe
// "DB: Historische Nachrichten laden") ist bereits die engste sinnvolle Staleness-Grenze.
const STRATEGY_ATR_MULTIPLIERS = { news_event: { stop: 1.2, target: 2.0, expected_horizon_days: 5 } };
function evaluateNewsForTicker(technicalSignals, newsRowsForTicker, close, atr, ruleVersion) {
  if (!newsRowsForTicker || newsRowsForTicker.length === 0) return { veto: false, vetoReason: null, candidate: null };
  const hatPositiv = newsRowsForTicker.some(n => n.wirkungsrichtung === 'positiv');
  const hatNegativ = newsRowsForTicker.some(n => n.wirkungsrichtung === 'negativ');
  if (hatPositiv && hatNegativ) return { veto: true, vetoReason: 'WIDERSPRUECHLICHE_NEWS', candidate: null };
  if (atr === null || atr === undefined) return { veto: false, vetoReason: null, candidate: null };
  const direction = hatPositiv ? 'long' : 'short';
  if (!technicalSignals.some(s => s.direction === direction)) return { veto: false, vetoReason: null, candidate: null };
  const mult = STRATEGY_ATR_MULTIPLIERS.news_event;
  const stopPrice = direction === 'long' ? close - atr * mult.stop : close + atr * mult.stop;
  const targetPrice = direction === 'long' ? close + atr * mult.target : close - atr * mult.target;
  const zone = direction === 'long' ? { low: close * 0.997, high: close } : { low: close, high: close * 1.003 };
  return {
    veto: false, vetoReason: null,
    candidate: {
      strategy: 'news_event', direction, raw_score: 0.7, data_quality: 'gut',
      expected_horizon_days: mult.expected_horizon_days,
      entry_zone_low: zone.low, entry_zone_high: zone.high,
      stop_price: stopPrice, target_price: targetPrice,
      evidence: [`Nachrichtenrichtung=${hatPositiv ? 'positiv' : 'negativ'}`, 'bestaetigt durch technisches Signal'],
      rule_version: ruleVersion, blockers: []
    }
  };
}

