    //
    // News-Tri-State (Phase 7): newsForTicker kommt aus "DB: Historische Nachrichten laden"
    // (trading.historical_news_assessments, relevant=TRUE+wirkung_staerke='hoch'+
    // wirkungsrichtung positiv/negativ) - EXAKT dieselbe Filtersemantik wie WF06s hatNews
    // (Schritt 4J bestaetigt), nur auf der POST-HOC historisierten statt der Live-Tabelle.
    // newsForTicker.length>0 ist deshalb der direkte hatNews-Ersatz fuer den Replay-Modus -
    // IMMER mit pit_complete=false markiert (Phase 7: "keinen Versuch, diese Werte
    // schoenzurechnen"). evaluateNewsForTicker() wird hier ein zweites Mal mit denselben
    // Inputs aufgerufen wie oben fuer den Research-Pfad (reine Funktion, keine
    // Seiteneffekte, identisches Ergebnis) - keine Restrukturierung der bestehenden
    // Research-Veto-Pruefung, um deren Kontrollfluss nicht anzufassen.
    //
    // Fundamentals (Phase 8/Gap): in diesem Schritt bewusst NICHT verdrahtet - WF17 laedt
    // aktuell keine trading.fundamentals_history (kein solcher DB-Node existiert). Eine neue
    // Query/Node haette den Graphen dieses produktiven, aktiv geplanten Workflows veraendert
    // (bisher hat JEDE LIVE_PARITY-Aenderung ausschliesslich bestehenden Node-Code editiert,
    // nie die Graph-Topologie). fundamentalRows bleibt deshalb [] -> getLiveParityFundTrend()
    // liefert wohldefiniert direction:'unbekannt'/snapshot_count:0/pit_complete:true (siehe
    // Schritt 4E), kein Crash, aber auch kein echter Fundamental-Beitrag. Dokumentiert als
    // GAP_FUNDAMENTALS_NOT_WIRED_IN_SHADOW_MODE (siehe buildShadowDecisionLogRow unten).
    // ==========================================================
    if (liveParityMode === 'AVAILABLE_DATA_LIVE_REPLAY') {
      const liveParityCandidates = (sig.liveParityShadowSignals || []).slice();
      if (liveParityCandidates.length > 0) {
        const shadowNewsEval = evaluateNewsForTicker(liveParityCandidates, newsForTicker, sig.close, sig.atr, RULE_VERSION);
        let shadowNewsEventState, shadowNewsEvidenceState;
        if (!newsForTicker.length) {
          shadowNewsEventState = { status: 'KNOWN_NONE' };
          shadowNewsEvidenceState = { status: 'NEWS_EVIDENCE_FALSE', pit_complete: false };
        } else {
          shadowNewsEvidenceState = { status: 'NEWS_EVIDENCE_TRUE', pit_complete: false };
          shadowNewsEventState = shadowNewsEval.candidate
            ? { status: 'KNOWN_SIGNAL', candidate: { strategy: 'news_event', direction: shadowNewsEval.candidate.direction, raw_score: shadowNewsEval.candidate.raw_score }, pit_complete: false }
            : { status: 'KNOWN_NONE' };
        }
        const shadowResult = buildLiveParityShadowCandidate({
          ticker, businessDay: day, technicalCandidates: liveParityCandidates, combinedRegime,
          fundamentalRows: fundamentalLiveParityRowsByTicker[ticker] || [], decisionTimeIso: day + 'T' + (runCtx.data_cutoff_time || '18:00:00') + 'Z',
          entryReferencePrice: bar.close,
          newsEventState: shadowNewsEventState, newsEvidenceState: shadowNewsEvidenceState
        });
        // LIVE_PARITY Schritt 4N: Sizing nur fuer READY-Kandidaten sinnvoll (nur dort ist
        // shadowResult.geometry mit gueltigem stop_price/target_price befuellt - siehe
        // buildLiveParityShadowCandidate()). sizePosition() unveraendert wiederverwendet (siehe
        // Kommentar in buildShadowDecisionLogRow), openPositionsState bewusst leer (isoliert).
        const shadowSizing = (shadowResult.status === 'READY' && shadowResult.geometry)
          ? sizePosition(
              { stop_price: shadowResult.geometry.stop_price, target_price: shadowResult.geometry.target_price },
              shadowResult.geometry.entry_reference_price, cfg, [],
              tickerToSektor[ticker] || 'unbekannt', tickerToRegion[ticker] || 'global'
            )
          : null;
        const shadowDecisionLogRow = buildShadowDecisionLogRow(
          ticker, day, shadowResult, shadowSizing,
          tickerToSektor[ticker] || 'unbekannt', tickerToRegion[ticker] || 'global', tickerToCurrency[ticker] || null
        );
        decisionLogRows.push(shadowDecisionLogRow);
        // LIVE_PARITY 4O.3B Phase 11: nur tatsaechlich READY Kandidaten gehen in den Job-A
        // Portfolio-Check (nach Abschluss dieser Ticker-Schleife) - FILTERED/GEOMETRY_INVALID/
        // INDETERMINATE/NO_SIGNAL bleiben aussen vor.
        if (shadowResult.status === 'READY') {
          dayShadowReadyCandidates.push({
            ticker, shadowResult, sektor: tickerToSektor[ticker] || 'unbekannt',
            region: tickerToRegion[ticker] || 'global', currency: tickerToCurrency[ticker] || null,
            decisionLogRow: shadowDecisionLogRow
          });
        }
      }
    }

    // LIVE_PARITY 4L.3A Phase 4/6: kanonisches Execution-Gate fuer den gesamten
    // Research-Kandidaten->Order-Pfad (Sizing, Occupancy-/Hard-Limit-Checks, Order-/
    // Recommendation-Erzeugung). Fuer RESEARCH_BASELINE (isResearchExecution=true)
    // exakt derselbe Codepfad wie vor 4L.3A - 0 Verhaltensaenderung. Fuer
    // AVAILABLE_DATA_LIVE_REPLAY strukturell unerreichbar: kein newCandidates-Eintrag,
    // keine Order/Trade/Position - der Shadow-Block oben ist bereits vollstaendig
    // abgeschlossen und unberuehrt von diesem Gate.
    if (isResearchExecution) {
    const best = sig.signals.reduce((a, b) => (b.raw_score > a.raw_score ? b : a));
    const fitMultiplier = fitMultiplierFor(best.strategy, combinedRegime);
    const regimeAlignment = regimeAlignmentFor(best.direction, combinedRegime);
    // LIVE_PARITY-Vorbereitung Schritt 1 (2026-09-07): dieselbe Geometrie-Funktion wie in
    // sizePosition(), hier bereits VOR isOccupied()/Sizing/Hard-Limits verfuegbar gemacht.
    // sizePosition() ruft dieselbe Funktion unabhaengig fuer sich selbst auf - identische,
    // zustandslose Berechnung, kein Drift moeglich. Kandidatenpriorisierung selbst folgt erst
    // in einem spaeteren LIVE_PARITY-Schritt.
    const candidateGeometry = calculateTradeGeometry(bar.close, best.stop_price, best.target_price);

    // FIX 2026-09-07 (Schritt 1B, Geometry-NaN-Bug): fehlende/nicht-numerische stop_price/
    // target_price fuehrten bisher dazu, dass unitRisk/riskBasedQuantity/finalQuantity zu NaN
    // wurden - da 'NaN <= 0' in JS immer false ist, griff KEIN bestehendes Veto
    // (STOP_WRONG_SIDE/STOP_TARGET_INVALID/QUANTITY_TOO_SMALL/UNECONOMICAL_AFTER_COSTS/
    // RRR_TOO_LOW), der Kandidat lief mit NaN-Feldern bis zum Erfolgsfall durch (bewiesen
    // durch Golden-Test 9c waehrend Schritt 1). Dieser Guard faengt das VOR isOccupied()/
    // Sizing/Portfolio-Limits/Recommendation/Order/Trade ab - reine Dateneingabe-Pruefung,
    // veraendert keine der bestehenden fachlichen Vetos (die pruefen weiterhin unveraendert,
    // erreichen aber diesen Punkt bei kaputter Geometrie nun schlicht nicht mehr).
    if (candidateGeometry.geometry_error) {
      decisionLogRows.push({ day, ticker, strategy: best.strategy, direction: best.direction, decision: 'REJECTED', reason: 'TRADE_GEOMETRY_INVALID', decision_stage: 'SIZING', raw_score: best.raw_score, theoretical_quantity: null, actual_quantity: null, position_value: null, market_regime: region, combined_regime: combinedRegime, fit_multiplier: fitMultiplier, direction_regime_alignment: regimeAlignment, rule_version: best.rule_version || null, entry_reference_price: Number.isFinite(bar.close) ? bar.close : null, entry_zone_low: best.entry_zone_low, entry_zone_high: best.entry_zone_high, stop_price: Number.isFinite(best.stop_price) ? best.stop_price : null, target_price: Number.isFinite(best.target_price) ? best.target_price : null, unit_risk: Number.isFinite(candidateGeometry.unit_risk) ? candidateGeometry.unit_risk : null, atr_value: sig.atr, diagnostics_json: { geometry_error: candidateGeometry.geometry_error } });
      continue;
    }

    // LIVE_PARITY-Vorbereitung Schritt 3 (2026-09-08): reine Sortier-Metadaten-Vorbereitung fuer eine spaetere
    // Kandidatenpriorisierung (siehe WF14 Job A sortKey() - is_theoretical -> opportunity_score DESC ->
    // reward_risk_ratio DESC -> evidence_confidence DESC -> ticker) - NOCH NICHT verwendet, kein sort(), keine
    // Entscheidung/Reihenfolge aendert sich dadurch. is_theoretical ist hartkodiert true, weil WF06 (Live-Empfehlungen)
    // dieses Feld nachweislich fuer jede Empfehlung konstant true setzt (kein Codepfad mit false/null). reward_risk_ratio
    // kommt 1:1 aus candidateGeometry (calculateTradeGeometry(), oben bereits gegen den Guard geprueft) - keine zweite
    // Formel, keine Rundung. opportunity_score/evidence_confidence fehlen bewusst - noch nicht portiert (LIVE_PARITY
    // Schritt 4), kein Platzhalterwert.
    best.sortMetadata = {
      ticker,
      is_theoretical: true,
      reward_risk_ratio: candidateGeometry.reward_risk_ratio,
    };

    if (isOccupied(ticker)) {
      decisionLogRows.push({ day, ticker, strategy: best.strategy, direction: best.direction, decision: 'BLOCKED', reason: 'ALREADY_OCCUPIED', decision_stage: 'OCCUPANCY_GATE', raw_score: best.raw_score, theoretical_quantity: null, actual_quantity: null, position_value: null, market_regime: region, combined_regime: combinedRegime, fit_multiplier: fitMultiplier, direction_regime_alignment: regimeAlignment, rule_version: best.rule_version || null, entry_reference_price: bar.close, entry_zone_low: best.entry_zone_low, entry_zone_high: best.entry_zone_high, stop_price: best.stop_price, target_price: best.target_price, atr_value: sig.atr });
      continue;
    }

    const sizing = sizePosition(best, bar.close, cfg, openPositions, sektor, region);
    if (sizing.veto) {
      decisionLogRows.push({ day, ticker, strategy: best.strategy, direction: best.direction, decision: 'REJECTED', reason: sizing.veto, decision_stage: 'SIZING', raw_score: best.raw_score, theoretical_quantity: sizing.theoretical_quantity != null ? sizing.theoretical_quantity : null, actual_quantity: null, position_value: null, market_regime: region, combined_regime: combinedRegime, fit_multiplier: fitMultiplier, direction_regime_alignment: regimeAlignment, rule_version: best.rule_version || null, entry_reference_price: bar.close, entry_zone_low: best.entry_zone_low, entry_zone_high: best.entry_zone_high, stop_price: best.stop_price, target_price: best.target_price, reward_risk_ratio: sizing.reward_risk_ratio != null ? sizing.reward_risk_ratio : null, atr_value: sig.atr, risk_amount: sizing.theoretical_risk_amount != null ? sizing.theoretical_risk_amount : null, unit_risk: sizing.unit_risk != null ? sizing.unit_risk : null, quantity_by_risk: sizing.theoretical_quantity != null ? sizing.theoretical_quantity : null, quantity_by_value: sizing.quantity_by_value != null ? sizing.quantity_by_value : null, limiting_factor: sizing.binding_limit || null });
      continue;
    }
    const hardBlockers = checkHardLimits(best.direction, sizing.position_value, openPositions, cfg);
    if (hardBlockers.length > 0) {
      decisionLogRows.push({ day, ticker, strategy: best.strategy, direction: best.direction, decision: 'BLOCKED', reason: hardBlockers.join(','), decision_stage: 'PORTFOLIO_LIMIT', raw_score: best.raw_score, theoretical_quantity: sizing.theoretical_quantity, actual_quantity: sizing.actual_quantity, position_value: sizing.position_value, market_regime: region, combined_regime: combinedRegime, fit_multiplier: fitMultiplier, direction_regime_alignment: regimeAlignment, rule_version: best.rule_version || null, entry_reference_price: bar.close, entry_zone_low: best.entry_zone_low, entry_zone_high: best.entry_zone_high, stop_price: best.stop_price, target_price: best.target_price, reward_risk_ratio: sizing.reward_risk_ratio, atr_value: sig.atr, risk_amount: sizing.theoretical_risk_amount, unit_risk: sizing.unit_risk, quantity_by_risk: sizing.theoretical_quantity, quantity_by_value: sizing.quantity_by_value != null ? sizing.quantity_by_value : null, limiting_factor: sizing.clamp_reason || null, blockers_json: hardBlockers });
      continue;
    }

    const nextDay = nextWeekday(day);
    // expected_horizon_days sind HANDELSTAGE, nicht Kalendertage (FIX 2026-08-28).
    let timeStopDate = day;
    for (let i = 0; i < best.expected_horizon_days; i++) timeStopDate = nextWeekday(timeStopDate);
    const timeStopAt = new Date(timeStopDate + 'T00:00:00Z').toISOString();

    decisionLogRows.push({ day, ticker, strategy: best.strategy, direction: best.direction, decision: 'ACCEPTED', reason: 'OK', decision_stage: 'ACCEPTED', raw_score: best.raw_score, theoretical_quantity: sizing.theoretical_quantity, actual_quantity: sizing.actual_quantity, position_value: sizing.position_value, market_regime: region, combined_regime: combinedRegime, fit_multiplier: fitMultiplier, direction_regime_alignment: regimeAlignment, rule_version: best.rule_version || null, entry_reference_price: bar.close, entry_zone_low: best.entry_zone_low, entry_zone_high: best.entry_zone_high, stop_price: best.stop_price, target_price: best.target_price, reward_risk_ratio: sizing.reward_risk_ratio, atr_value: sig.atr, risk_amount: sizing.theoretical_risk_amount, unit_risk: sizing.unit_risk, quantity_by_risk: sizing.theoretical_quantity, quantity_by_value: sizing.quantity_by_value != null ? sizing.quantity_by_value : null, limiting_factor: sizing.clamp_reason || null, simulation_recommendation_id: null, simulation_order_id: null, simulation_trade_id: null });

    // v2: EIN kombinierter Kandidat statt getrennter newRecRows/newOrderRows (Reparaturbericht
    // Punkt 2/6) - garantiert 1:1-Zuordnung fuer die CTE-basierte Persistierung.
    newCandidates.push({
      ticker, direction: best.direction, strategy: best.strategy,
      as_of_date: day, entry_grund: best.evidence.join('; ') + (sizing.clamped ? ` [gekappt: ${sizing.clamp_reason}]` : ''),
      signal_date: day, intended_execution_date: nextDay,
      sektor, region, entry_zone_low: best.entry_zone_low, entry_zone_high: best.entry_zone_high,
      stop_price: best.stop_price, target_price: best.target_price, time_stop_at: timeStopAt,
      risk_amount: sizing.actual_risk_amount, theoretical_risk_amount: sizing.theoretical_risk_amount,
      quantity: sizing.actual_quantity, theoretical_quantity: sizing.theoretical_quantity,
      clamp_reason: sizing.clamp_reason, limit_price: bar.close
    });
    // Sofort in den lokalen Zustand aufnehmen (_pending_only) - zaehlt fuer isOccupied() und
    // die Risikopruefung nachfolgender Ticker DESSELBEN Tages mit.
    openPositions.push({ db_id: null, trade_id: null, simulation_order_id: null, ticker, strategy: best.strategy, direction: best.direction, sektor, region, risk_amount: sizing.actual_risk_amount, position_value: sizing.position_value, quantity: sizing.actual_quantity, stop_price: best.stop_price, target_price: best.target_price, time_stop_at: timeStopAt, is_new: false, _pending_only: true });
    }
  }
  // ============================================================================
  // LIVE_PARITY 4O.3B: kompletter Job A (Engine-Portfolio-Check, sequenziell, korrelations-
  // bewusst) fuer ALLE READY Shadow-Kandidaten dieses Tages, ZUERST vollstaendig abgeschlossen,
  // DANACH kompletter Job B (processShadowTradeForDay(), LEGACY) fuer den gesamten aktiven
  // Shadow-State - exakt Live-Reihenfolge (Phase 18), kein Wechsel Kandidat<->Job B. Nur bei
  // isAvailableDataReplay erreichbar; RESEARCH_BASELINE unveraendert (0 Verhaltensaenderung).
  if (isAvailableDataReplay) {
    // --- Phase 9: Tagesstart-Snapshot (State VOR Job A) ---
    const shadowStartOfDay = {
      proposed: shadowState.proposed.slice(), open: shadowState.open.slice(),
      closed: shadowState.closed.slice(), expired: shadowState.expired.slice(),
      dataError: shadowState.dataError.slice(), dataErrorFinal: shadowState.dataErrorFinal.slice()
    };

    // --- Phase 10: Drawdown NUR aus VOR heute geschlossenen Shadow-Trades. Closes aus dem
    // heutigen Job B wirken strukturell erst morgen, weil sie erst NACH diesem Job-A-Block
    // (unten) berechnet und erst am Paketende persistiert werden - Job A sieht sie damit nie
    // vorzeitig. Tie-Ordering mehrerer Closes desselben exit_date: GAP - kein dokumentiertes
    // deterministisches Live-Tie-Ordering gefunden (Phase 10 Fresh-Pruefung), Sortierung hier
    // zusaetzlich nach shadow_trade_id als stabiler, aber NICHT live-bewiesener Tie-Breaker.
    const closedBeforeToday = shadowStartOfDay.closed
      .filter(t => t.exit_date && t.exit_date < day)
      .sort((a, b) => (a.exit_date < b.exit_date ? -1 : (a.exit_date > b.exit_date ? 1 : (a.trade_id < b.trade_id ? -1 : 1))));
    let shadowEquity = runCtx._model_portfolio_value;
    let shadowPeakEquity = runCtx._model_portfolio_value;
    for (const t of closedBeforeToday) {
      shadowEquity += Number(t.net_pnl) || 0;
      if (shadowEquity > shadowPeakEquity) shadowPeakEquity = shadowEquity;
    }
    const shadowDrawdownPct = shadowPeakEquity > 0 ? (shadowPeakEquity - shadowEquity) / shadowPeakEquity * 100 : 0;

    // --- Phase 12: WF14 Job-A Sort-Key (is_theoretical=true fuer ALLE Shadow-Kandidaten) ---
    function shadowSortKey(c) {
      const rrr = c.shadowResult.geometry ? Number(c.shadowResult.geometry.reward_risk_ratio) : NaN;
      return [1, -(Number(c.shadowResult.opportunity_score) || 0), -(Number.isFinite(rrr) ? rrr : 0), -(Number(c.shadowResult.evidence_confidence) || 0), String(c.ticker)];
    }
    const sortedReady = dayShadowReadyCandidates.slice().sort((a, b) => {
      const ka = shadowSortKey(a), kb = shadowSortKey(b);
      for (let i = 0; i < ka.length; i++) { if (ka[i] < kb[i]) return -1; if (ka[i] > kb[i]) return 1; }
      return 0;
    });

    // --- Phase 13-17: sequenzieller Job-A-Engine-Portfolio-Check ---
    const shadowRiskCfg = {
      model_portfolio_value: runCtx._model_portfolio_value, max_total_open_risk_pct: runCtx._max_total_open_risk_pct,
      max_sector_exposure_pct: runCtx._max_sector_exposure_pct, max_single_position_pct: runCtx._max_single_position_pct,
      max_open_positions: runCtx._max_open_positions, max_directional_exposure_pct: runCtx._max_directional_exposure_pct,
      max_portfolio_drawdown_pct: runCtx._max_portfolio_drawdown_pct, max_pairwise_correlation: runCtx._max_pairwise_correlation,
      max_region_exposure_pct: runCtx._max_region_exposure_pct, max_non_eur_exposure_pct: runCtx._max_non_eur_exposure_pct,
      stress_risk_reduction_factor: runCtx._stress_risk_reduction_factor
    };
    const shadowSizingCfg = {
      modelPortfolioValue: shadowRiskCfg.model_portfolio_value, maxRiskPerTradePct: runCtx._max_risk_per_trade_pct,
      minRewardRiskRatio: runCtx._min_reward_risk_ratio, feesBps: runCtx._fees_bps, slippageBps: runCtx._slippage_bps,
      maxTotalOpenRiskPct: shadowRiskCfg.max_total_open_risk_pct, maxSectorExposurePct: shadowRiskCfg.max_sector_exposure_pct,
      maxSinglePositionPct: shadowRiskCfg.max_single_position_pct, maxOpenPositions: shadowRiskCfg.max_open_positions,
      maxDirectionalExposurePct: shadowRiskCfg.max_directional_exposure_pct, maxRegionExposurePct: shadowRiskCfg.max_region_exposure_pct
    };
    // GAP_STRATEGY_STATUS_NOT_WIRED_IN_SHADOW_JOB_A GELOEST (4O.3C) - siehe
    // strategyAktivByName-Hydration oben, angewendet als Vorfilter unten VOR jedem Sizing.
    const shadowOpenPositionsForCheck = () => shadowState.open.concat(shadowState.proposed).map(t => ({
      ticker: t.ticker, direction: t.direction, sektor: t.sector || 'unbekannt', region: t.region || 'global',
      currency: t.currency, risk_amount: Number(t.risk_amount) || 0, position_value: Number(t.position_value) || 0
    }));

    for (const cand of sortedReady) {
      const c = cand.shadowResult;
      let jobAOutcome;
      let sizing = null;
      // LIVE_PARITY 4O.3C Phase 7: STRATEGY_DEACTIVATED blockt VOR Sizing/Portfolio-Check -
      // identische Reihenfolge und Bedingung wie live (siehe strategyAktivByName-Kommentar oben).
      // Kein sizePosition()-Aufruf, kein Portfolio-State-Effekt fuer deaktivierte Strategien.
      if (c.strategy && strategyAktivByName[c.strategy] === false) {
        jobAOutcome = { approved: false, blockers: ['STRATEGY_DEACTIVATED'], sizing: null };
      } else {
        const shadowPortfolio = { open_positions: shadowOpenPositionsForCheck(), drawdown_pct: shadowDrawdownPct };
        sizing = sizePosition(
          { stop_price: c.geometry.stop_price, target_price: c.geometry.target_price },
          c.geometry.entry_reference_price, shadowSizingCfg, shadowPortfolio.open_positions, cand.sektor, cand.region
        );
        if (sizing.veto) {
          jobAOutcome = { approved: false, blockers: [sizing.veto], sizing };
        } else {
          // Phase 13/14: isStressRegime aus derselben, bereits Point-in-Time-korrekten
          // Regime-Klassifikation wie shadowResult.combined_regime (regimeForRegion()).
          const isStressRegime = c.combined_regime === 'stress';
          const candidateReturns = dailyReturnsForCorrelation(cand.ticker, day);
          const correlationData = { [cand.ticker]: candidateReturns.map(r => r.return) };
          for (const p of shadowPortfolio.open_positions) {
            if (p.ticker === cand.ticker) continue;
            correlationData[p.ticker] = dailyReturnsForCorrelation(p.ticker, day).map(r => r.return);
          }
          const candidateForCheck = { risk_amount: sizing.actual_risk_amount, position_value: sizing.position_value };
          const blockers = checkShadowPortfolioLimits(candidateForCheck, cand.ticker, cand.sektor, cand.region, cand.currency, c.direction, shadowPortfolio, shadowRiskCfg, isStressRegime, correlationData);
          jobAOutcome = { approved: blockers.length === 0, blockers: blockers.map(b => b.limit_name), sizing };
        }
      }

      // Additive Diagnostics auf der bereits gepushten SHADOW_LOGGED-Zeile dieses Tickers
      // (Phase 39: keine bestehende Semantik brechen, kein neuer decision_stage-Wert).
      if (cand.decisionLogRow) {
        cand.decisionLogRow.diagnostics_json = cand.decisionLogRow.diagnostics_json || {};
        cand.decisionLogRow.diagnostics_json.job_a_portfolio_check = {
          approved: jobAOutcome.approved, blockers: jobAOutcome.blockers,
          drawdown_pct_at_check: round(shadowDrawdownPct, 4),
          correlation_checked: jobAOutcome.approved !== undefined && !!sizing && !sizing.veto,
          strategy_status_policy_mode: 'CURRENT_POLICY_REPLAY'
        };
      }

      if (!jobAOutcome.approved) continue;

      // --- Phase 17: deterministische Shadow-ID, idempotent bei Doppel-Kandidat ---
      const newTradeId = makeShadowTradeId(cand.ticker, day, c.strategy);
      const alreadyExists = shadowState.proposed.some(t => t.trade_id === newTradeId) || shadowState.open.some(t => t.trade_id === newTradeId);
      if (alreadyExists) continue; // idempotente Semantik: derselbe logische Kandidat wird nicht doppelt angelegt

      const newShadowTrade = {
        trade_id: newTradeId, ticker: cand.ticker, strategy: c.strategy, direction: c.direction,
        status: 'proposed', decision_date: day,
        quantity: sizing.actual_quantity, zone_low: null, zone_high: null,
        entry_price: null, entry_date: null,
        stop_price_current: c.geometry.stop_price, stop_price_initial: c.geometry.stop_price, target_price: c.geometry.target_price,
        time_stop_at: (function () { let td = day; for (let i = 0; i < (c.expected_horizon_days || 0); i++) td = nextWeekday(td); return new Date(td + 'T00:00:00Z').toISOString(); })(),
        thesis_expires_at: null,
        risk_amount: sizing.actual_risk_amount, position_value: sizing.position_value,
        sector: cand.sektor, region: cand.region, currency: cand.currency,
        entry_fee: null, entry_slippage: null, exit_price: null, exit_date: null, exit_reason: null,
        gross_pnl: null, net_pnl: null, return_pct: null, realized_r_multiple: null,
        data_error_count: 0, pre_data_error_status: null, ambiguous_execution: false
      };
      // Zone_low/high: buildLiveParityGeometry liefert keine explizite Zone (Einzelpreis-
      // Referenz, kein Zonenmodell) - entry_reference_price als degenerierte Zone (low=high)
      // uebernommen, damit processShadowTradeForDay()s simulateEntryFill() dieselbe Semantik
      // wie bei einer punktgenauen Zone erhaelt (Fill nur wenn Kurs die Referenz beruehrt).
      newShadowTrade.zone_low = c.geometry.entry_reference_price;
      newShadowTrade.zone_high = c.geometry.entry_reference_price;

      // Phase 16: SOFORT lokal aufnehmen - beeinflusst TOTAL_RISK/SECTOR/REGION/CURRENCY/
      // MAX_OPEN/DIRECTIONAL/CORRELATION des naechsten Kandidaten DESSELBEN Tages, wie live.
      shadowState.proposed.push(newShadowTrade);
    }

    // ============================================================================
    // Phase 18-22: kompletter Job B (LEGACY processShadowTradeForDay(), 4O.2) - ERST NACHDEM
    // Job A fuer ALLE Kandidaten dieses Tages abgeschlossen ist. Phase 19: decision_date===day
    // (heute neu proposed) MUSS NO_ACTION liefern - processShadowTradeForDay() prueft dies
    // bereits selbst (Eligibility-Gate, siehe Crosscheck D aus 4O.2) und wird hier bewusst NICHT
    // dupliziert/vorgefiltert.
    // ============================================================================
    const shadowActiveForJobB = shadowState.proposed.concat(shadowState.open).concat(shadowState.dataError);
    const shadowJobBConfig = {
      ambiguous_bar_policy_code: ambiguousBarPolicyCode, default_fees_bps: runCtx._fees_bps,
      default_slippage_bps: runCtx._slippage_bps, max_data_error_retries: 5
    };
    const evalTimeIso = day + 'T' + (runCtx.data_cutoff_time || '18:00:00') + 'Z';
    const stillActiveShadow = [];
    // Phase 25 (Praezisierung): NUR die heute tatsaechlich von Job B beruehrten Trades (plus die
    // von Job A neu angelegten, die bereits Teil von shadowActiveForJobB sind) gehen in die
    // Persistenz - NICHT der komplette historische shadowState.closed/expired seit Lauf-Start.
    // Ein Upsert pro Tag pro aktivem Trade bleibt dadurch O(aktive Trades), nicht O(Lauf-Alter),
    // waehrend bereits laenger geschlossene Trades unangetastet (und trotzdem weiterhin in der
    // DB vorhanden, Phase 26) bleiben.
    const touchedThisInvocation = [];
    for (const trade of shadowActiveForJobB) {
      const bar = barOn(trade.ticker, day);
      const sig = signalsToday[trade.ticker];
      const oppositeSignal = sig && sig.signals.some(s => s.strategy === trade.strategy && s.direction !== trade.direction) ? sig.signals.find(s => s.strategy === trade.strategy && s.direction !== trade.direction) : null;
      const result = processShadowTradeForDay(trade, bar, shadowJobBConfig, oppositeSignal, day, evalTimeIso);
      const next = result.nextTradeState;
      touchedThisInvocation.push(next);
      if (next.status === 'closed') shadowState.closed.push(next);
      else if (next.status === 'expired_unfilled') shadowState.expired.push(next);
      else if (next.status === 'data_error_final') shadowState.dataErrorFinal.push(next);
      else stillActiveShadow.push(next); // proposed/open/data_error bleiben aktiv fuer den naechsten Tag
    }
    shadowState.proposed = stillActiveShadow.filter(t => t.status === 'proposed');
    shadowState.open = stillActiveShadow.filter(t => t.status === 'open');
    shadowState.dataError = stillActiveShadow.filter(t => t.status === 'data_error');

    // --- Phase 25: nur die heute beruehrten Shadow-Trades persistieren (Upsert macht
    // Wiederholung idempotent, Phase 29 - keine Unterscheidung "neu vs. geaendert" noetig,
    // da jeder hier gelistete Trade in diesem Tick durch processShadowTradeForDay() lief).
    for (const t of touchedThisInvocation) {
      shadowStateUpserts.push(mapShadowTradeToDbRow(t, runId, t.decision_date || day));
    }
  }

  // Nur-Order-Kandidaten (noch nicht gefuellt) wieder aus openPositions entfernen - die zaehlen
  // fuer die Risikopruefung INNERHALB desselben Tages, aber nicht als echte offene Position
  // fuer den naechsten Tag (sie sind ja noch nicht ausgefuehrt).
  openPositions = openPositions.filter(p => !p._pending_only);

  // --- 5. Tages-Portfolio-Zeile ---
  const positionsValue = openPositions.reduce((sum, p) => {
    const bar = barOn(p.ticker, day);
    if (!bar) return sum + p.position_value;
    const markValue = p.direction === 'long' ? bar.close * p.quantity : (2 * (p.position_value / p.quantity) - bar.close) * p.quantity;
    return sum + markValue;
  }, 0);
  const totalEquity = cash + positionsValue;
  if (totalEquity > peakEquity) peakEquity = totalEquity;
  const drawdownPct = peakEquity > 0 ? (peakEquity - totalEquity) / peakEquity * 100 : 0;
  portfolioRows.push({ day, cash, positions_value: positionsValue, total_equity: totalEquity, drawdown_pct: drawdownPct, open_positions_count: openPositions.length });

  stepCompletions.push(step.id);
}

return [{ json: {
  run_id: runId, orderUpdates, newCandidates, newTradeRows, tradeUpdates, openTradeUpdates, recCloseUpdates,
  positionRows, portfolioRows, stepCompletions, decisionLogRows, shadowStateUpserts,
  lastDay: steps.length ? String(steps[steps.length - 1].simulated_date).slice(0, 10) : null
} }];

function pgStr(v) { return v === null || v === undefined ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }
function pgBool(v) { return v === null || v === undefined ? 'NULL' : (v ? 'TRUE' : 'FALSE'); }
function pgJsonb(v) { return (v === null || v === undefined) ? "'[]'::jsonb" : `'` + JSON.stringify(v).replace(/'/g, `''`) + `'::jsonb`; }

