// PHASE 8 (TRADING_ENGINE_MIGRATION.md): Ersetzt "Verarbeite Tage-Paket" fuer
// news_enabled=false-Laeufe durch Aufrufe der getesteten trading_engine (POST
// /engine/simulation/step, ein Aufruf je Simulationstag). Nur erreichbar, wenn die IF-Weiche
// (pipeline_config.TRADING_ENGINE_STEP_ENABLED=true UND runCtx.news_enabled=false) TRUE ergibt.
// Der alte Node bleibt unveraendert bestehen (Fallback fuer news_enabled=true-Laeufe).
//
// Rueckgabeform ist BYTE-IDENTISCH zum alten Node (orderUpdates/newOrderRows/newTradeRows/
// tradeUpdates/openTradeUpdates/newRecRows/recCloseUpdates/positionRows/portfolioRows/
// stepCompletions/lastDay) - "Baue SQL fuer Paket-Ergebnisse" bleibt dadurch unveraendert.
//
// WICHTIGE ABWEICHUNG von der Nutzung in tests/trading_engine/test_golden_run.py: dort wird
// `pending_orders = result.still_pending_orders + result.new_orders` gebildet. Das waere hier
// FALSCH - der echte Live-Code haengt einen neu erzeugten Order-Kandidaten NIE in denselben
// Tages-Paket-Durchlauf ein (siehe altes "Verarbeite Tage-Paket": newOrderRows.push(...) fuegt
// NICHTS zu pendingOrders hinzu). Ein neuer Order-Kandidat wird erst mit dem NAECHSTEN
// Worker-Tick/Paket ausfuehrbar, nachdem er persistiert und ueber "DB: Ausstehende Orders laden"
// neu geladen wurde. Deshalb hier bewusst NUR still_pending_orders fuer den naechsten Tag.
//
// entry_grund fuer newRecRows ist ein generischer Ersatztext statt der detaillierten
// evidence-Liste aus WF17s eigenem computeSignals() - die Engine hat kein evidence-Feld
// (Nutzerentscheidung 2026-08-20, siehe TRADING_ENGINE_MIGRATION.md Abschnitt 1.5). Rein
// kosmetisch, keine Rechenlogik betroffen.
//
// Entry-Fee/Slippage fuer orderUpdates/newTradeRows werden LOKAL nach derselben, stabilen
// Mini-Future-Halb-Spread-Formel berechnet, die die Engine intern verwendet (Trade/DayStepResult
// geben die Entry-Fee nicht einzeln zurueck, nur ueber die cash-Gesamtbilanz) - siehe
// TRADING_ENGINE_MIGRATION.md fuer die vollstaendige Feld-Luecken-Analyse.

const ENGINE_BASE_URL = 'http://172.16.1.14:8099';

function nextWeekday(dateStr) {
  let d = new Date(dateStr + 'T00:00:00Z');
  d = new Date(d.getTime() + 24 * 3600 * 1000);
  while (d.getUTCDay() === 0 || d.getUTCDay() === 6) d = new Date(d.getTime() + 24 * 3600 * 1000);
  return d.toISOString().slice(0, 10);
}
function isoOrNull(v) {
  return v ? String(v).slice(0, 10) : null;
}

