// Marktregime (historisch, Point-in-time) - repliziert 02b "Marktanalyse berechnen" +
// "Marktregime berechnen" 1:1 fuer die 7 tatsaechlich in der Live-Regime-Formel genutzten
// Referenzsymbole (MDAX wird auch live nicht verwendet, siehe 02b). Bewusste Abweichung von
// der Live-Version: die makro-News-Stress-Bedingung (wirkungsebene markt/makro) wird NICHT
// uebernommen - dieser Workflow ist "Pilot ohne Nachrichten", und historical_news hat einen
// offenen, noch unreparierten Zukunftsdatum-Bug. Nur die preis-/volatilitaetsbasierte
// Stress-Bedingung (avgVol > 0.45 UND riskOffShare >= 0.5) bleibt bestehen.
const REGIME_SYMBOLS = { europa: ['^GDAXI', '^STOXX50E'], usa: ['^IXIC', '^GSPC'] };

function emaValue(arr, p) {
  if (arr.length < p) return null;
  const k = 2 / (p + 1);
  let e = arr.slice(0, p).reduce((a, b) => a + b, 0) / p;
  for (let i = p; i < arr.length; i++) e = arr[i] * k + e * (1 - k);
  return e;
}
function emaSeries(arr, p) {
  if (arr.length < p) return [];
  const k = 2 / (p + 1);
  const res = [];
  let e = arr.slice(0, p).reduce((a, b) => a + b, 0) / p;
  for (let i = 0; i < arr.length; i++) {
    if (i < p - 1) res.push(null);
    else if (i === p - 1) res.push(e);
    else { e = arr[i] * k + e * (1 - k); res.push(e); }
  }
  return res;
}
function realizedVol20(closes) {
  if (!closes || closes.length < 21) return null;
  const recent = closes.slice(-21);
  const returns = [];
  for (let i = 1; i < recent.length; i++) if (recent[i - 1] > 0) returns.push(Math.log(recent[i] / recent[i - 1]));
  if (returns.length < 20) return null;
  const mean = returns.reduce((a, b) => a + b, 0) / returns.length;
  const variance = returns.reduce((a, b) => a + (b - mean) * (b - mean), 0) / (returns.length - 1);
  return Math.sqrt(variance) * Math.sqrt(252);
}

// Point-in-time-Symbolkontext fuer ein Referenzsymbol an einem simulierten Tag - identische
// Formeln wie 02b "Marktanalyse berechnen" (RSI/Bollinger/EMA200 dort weggelassen, sie
// beeinflussen combined_regime dort nachweislich nicht, nur inputs-Metadaten).
function symbolRegimeContext(ticker, day) {
  const bars = barsUpTo(ticker, day);
  const closes = bars.map(b => b.close);
  if (closes.length < 26) return null;
  const aktKurs = closes[closes.length - 1];
  const vorKurs = closes[closes.length - 2];
  const veraPct = (aktKurs - vorKurs) / vorKurs * 100;

  const ema12S = emaSeries(closes, 12);
  const ema26S = emaSeries(closes, 26);
  const macdFull = closes.map((_, i) => (ema12S[i] != null && ema26S[i] != null) ? ema12S[i] - ema26S[i] : null).filter(v => v != null);
  if (macdFull.length < 9) return null;
  const sigS = emaSeries(macdFull, 9).filter(v => v != null);
  const macdV = macdFull[macdFull.length - 1];
  const macdSig = sigS[sigS.length - 1];
  const macdPrev = macdFull[macdFull.length - 2];
  const sigPrev = sigS[sigS.length - 2];
  let macdSignal = 'Neutral';
  if (macdPrev <= sigPrev && macdV > macdSig) macdSignal = 'Bullische Kreuzung';
  else if (macdPrev >= sigPrev && macdV < macdSig) macdSignal = 'B�rische Kreuzung';
  else if (macdV > macdSig) macdSignal = 'Bullisch';
  else if (macdV < macdSig) macdSignal = 'B�risch';
  const macdBullisch = macdSignal === 'Bullisch' || macdSignal === 'Bullische Kreuzung';
  const macdBaerisch = macdSignal === 'B�risch' || macdSignal === 'B�rische Kreuzung';

  const ema20V = emaValue(closes, 20);
  const aufwaerts = ema20V !== null && aktKurs > ema20V;

  let marktStatus;
  if (aufwaerts && macdBullisch && veraPct >= -0.5) marktStatus = 'risk_on';
  else if (!aufwaerts && macdBaerisch && veraPct <= -1.0) marktStatus = 'risk_off';
  else if (!aufwaerts && veraPct <= -1.0) marktStatus = 'risk_off';
  else if (aufwaerts && veraPct >= 0.5) marktStatus = 'risk_on';
  else marktStatus = 'neutral';

  return { trend: aufwaerts ? 'Aufw�rts' : 'Abw�rts', veraenderungPct: veraPct, marktStatus, closes };
}

// Region-Regime, identische Ableitungstabelle wie 02b "Marktregime berechnen", ohne
// News-Komponente (siehe Kommentar oben) und ohne session_status/vorlaeufig (historische
// Tageskerzen sind immer abgeschlossen, keine Intraday-Unterscheidung noetig).
function regionRegimeHistorical(symbols, day) {
  const rows = symbols.map(t => symbolRegimeContext(t, day)).filter(r => r !== null);
  if (rows.length === 0) return { stress_regime: 'unknown', combined_regime: 'unknown' };

  const bullShare = rows.filter(r => r.trend === 'Aufw�rts').length / rows.length;
  const trendRegime = bullShare >= 0.5 ? 'bull' : 'bear';

  const vols = rows.map(r => realizedVol20(r.closes)).filter(v => v !== null);
  const avgVol = vols.length > 0 ? vols.reduce((a, b) => a + b, 0) / vols.length : null;
  const volRegime = avgVol === null ? 'unknown' : (avgVol > 0.30 ? 'high_vol' : 'low_vol');

  const riskOffShare = rows.filter(r => r.marktStatus === 'risk_off').length / rows.length;
  const stressRegime = (avgVol !== null && avgVol > 0.45 && riskOffShare >= 0.5) ? 'stress' : 'none';

  let combined;
  if (stressRegime === 'stress') combined = 'stress';
  else if (trendRegime === 'bear' && bullShare <= 0.3) combined = 'bear_trend';
  else if (trendRegime === 'bull' && volRegime === 'low_vol') combined = 'bull_trend_low_vol';
  else if (trendRegime === 'bull' && volRegime === 'high_vol') combined = 'bull_trend_high_vol';
  else if (volRegime === 'low_vol') combined = 'sideways_low_vol';
  else if (volRegime === 'high_vol') combined = 'sideways_high_vol';
  else combined = 'unknown';

  return { stress_regime: stressRegime, combined_regime: combined };
}

function globalRegimeHistorical(day) {
  const gold = symbolRegimeContext('GC=F', day);
  const goldRiskOff = !!(gold && gold.veraenderungPct > 1.0);
  return { stress_regime: goldRiskOff ? 'stress' : 'none', combined_regime: 'cross_asset_context' };
}

let cash = lastPortfolioRows.length ? Number(lastPortfolioRows[0].cash) : Number(runCtx.initial_capital);
let peakEquity = lastPortfolioRows.length ? Number(lastPortfolioRows[0].peak_equity || lastPortfolioRows[0].total_equity) : Number(runCtx.initial_capital);

let openTradesApi = openTradesRaw.map(t => ({
  trade_id: t.trade_id, ticker: t.ticker, direction: t.direction,
  entry_price: Number(t.simulated_entry_price),
  stop_price_current: Number(t.stop_price_current || t.stop_price_initial),
