}));

const orderMetaByTicker = {};
let pendingOrdersApi = pendingOrdersRaw.map(o => {
  orderMetaByTicker[o.ticker] = { db_id: o.id, entry_zone_low: Number(o.entry_zone_low), entry_zone_high: Number(o.entry_zone_high) };
  return {
    ticker: o.ticker, direction: o.direction, entry_zone_low: Number(o.entry_zone_low), entry_zone_high: Number(o.entry_zone_high),
    stop_price: Number(o.stop_price), target_price: Number(o.target_price), quantity: Number(o.quantity),
