  };
});

const steps = [...pktCtx.steps].sort((a, b) => a.sequence_number - b.sequence_number);

const orderUpdates = [];
const newOrderRows = [];
const newTradeRows = [];
const tradeUpdates = [];
const openTradeUpdates = [];
const newRecRows = [];
const recCloseUpdates = [];
const positionRows = [];
const portfolioRows = [];
const stepCompletions = [];

for (const step of steps) {
  const day = String(step.simulated_date).slice(0, 10);
  const tickersToday = Object.keys(barsByTicker).filter(t => barOn(t, day) !== null && tradableUniverse.has(t));

  const europaRegime = regionRegimeHistorical(REGIME_SYMBOLS.europa, day);
  const usaRegime = regionRegimeHistorical(REGIME_SYMBOLS.usa, day);
  const globalRegime = globalRegimeHistorical(day);
  const isStressRegime = [europaRegime, usaRegime, globalRegime].some(r => r.stress_regime === 'stress');

  const barsToday = {};
  const barsHistory = {};
  for (const t of tickersToday) {
    barsToday[t] = toApiBar(t, barOn(t, day));
    barsHistory[t] = barsUpTo(t, day).map(b => toApiBar(t, b));
  }

  const payload = {
    as_of: day, next_trading_day: nextWeekday(day), tickers_today: tickersToday,
    bars_today: barsToday, bars_history: barsHistory,
    pending_orders: pendingOrdersApi, open_trades: openTradesApi,
    cash, previous_peak_equity: peakEquity,
    risk_cfg: riskCfgApi, fee_model: feeModelApi, rule_version: 'historische-simulation-v1',
    ticker_sektor: tickerToSektor, ticker_region: tickerToRegion, ticker_currency: tickerToCurrency,
    sizing_mode: 'clamp', strategy_filter: runCtx.strategy_filter || null,
    is_stress_regime: isStressRegime, correlation_data: null
  };

  const result = await this.helpers.httpRequest({
    method: 'POST', url: ENGINE_BASE_URL + '/engine/simulation/step',
    body: payload, json: true, timeout: 30000
  });

  const filledTickers = new Set(result.new_trades.map(t => t.ticker));
  const stillPendingTickers = new Set(result.still_pending_orders.map(o => o.ticker));

  for (const order of pendingOrdersApi) {
    if (filledTickers.has(order.ticker) || stillPendingTickers.has(order.ticker)) continue;
    const meta = orderMetaByTicker[order.ticker];
    orderUpdates.push({ id: meta ? meta.db_id : null, status: 'not_filled_price', actual_execution_date: day, executed_price: null, commission: 0, slippage_val: 0 });
    delete orderMetaByTicker[order.ticker];
  }

  for (const trade of result.new_trades) {
    const meta = orderMetaByTicker[trade.ticker];
    const positionValue = trade.entry_price * trade.quantity;
    const fee = entryFee(positionValue);
    orderUpdates.push({ id: meta ? meta.db_id : null, status: 'filled', actual_execution_date: day, executed_price: trade.entry_price, commission: fee, slippage_val: 0 });
    newTradeRows.push({
      trade_id: trade.trade_id, order_id: meta ? meta.db_id : null, ticker: trade.ticker, strategy: trade.strategy, direction: trade.direction,
      as_of_date: day, entry_zone_low: meta ? meta.entry_zone_low : null, entry_zone_high: meta ? meta.entry_zone_high : null,
      entry_price: trade.entry_price, stop_price: trade.stop_price_current, target_price: trade.target_price,
      time_stop_at: trade.time_stop_at, quantity: trade.quantity, risk_amount: trade.risk_amount,
      theoretical_quantity: trade.theoretical_quantity, theoretical_risk_amount: trade.theoretical_risk_amount,
      clamp_reason: trade.clamp_reason, sektor: trade.sektor, region: trade.region,
      market_regime_at_entry: trade.region === 'Europa' ? europaRegime.combined_regime : (trade.region === 'USA' ? usaRegime.combined_regime : null),
      position_value: positionValue, fee, slippage: 0
    });
    delete orderMetaByTicker[trade.ticker];
  }

  for (const ex of result.exited_trades) {
    const t = ex.trade, er = ex.exit_result, pnl = ex.pnl;
    tradeUpdates.push({
      trade_id: t.trade_id, exit_time: day, exit_price: er.price, exit_reason: er.reason,
      gross_pnl: pnl.gross_pnl, net_pnl: pnl.net_pnl, r_multiple: t.risk_amount > 0 ? pnl.net_pnl / t.risk_amount : null,
      commission_total: pnl.entry_fee + pnl.exit_fee, slippage_total: pnl.financing_cost
    });
    recCloseUpdates.push({ ticker: t.ticker, run_id: runId, exit_day: day });
  }

  for (const trade of result.still_open_trades) {
    openTradeUpdates.push({ trade_id: trade.trade_id, stop_price_current: trade.stop_price_current, extreme_price_since_entry: trade.extreme_price_since_entry });
    const bar = barOn(trade.ticker, day);
    const markPrice = bar ? bar.close : trade.entry_price;
    const unrealizedPnl = (trade.direction === 'long' ? (markPrice - trade.entry_price) : (trade.entry_price - markPrice)) * trade.quantity;
    positionRows.push({ ticker: trade.ticker, day, quantity: trade.quantity, cost_basis: trade.entry_price, mark_price: markPrice, unrealized_pnl: unrealizedPnl });
  }

  for (const order of result.new_orders) {
    const bar = barOn(order.ticker, day);
    newOrderRows.push({
      run_id: runId, ticker: order.ticker, signal_date: day, intended_execution_date: order.intended_execution_date,
      direction: order.direction, strategy: order.strategy, sektor: order.sektor, region: order.region,
      entry_zone_low: order.entry_zone_low, entry_zone_high: order.entry_zone_high, stop_price: order.stop_price, target_price: order.target_price,
      time_stop_at: order.time_stop_at, risk_amount: order.risk_amount, theoretical_risk_amount: order.theoretical_risk_amount,
      quantity: order.quantity, theoretical_quantity: order.theoretical_quantity, clamp_reason: order.clamp_reason,
      limit_price: bar ? bar.close : null
    });
    const grundSuffix = order.clamp_reason ? ` [gekappt: ${order.clamp_reason}]` : '';
    newRecRows.push({ run_id: runId, as_of_date: day, ticker: order.ticker, direction: order.direction, strategy: order.strategy,
      entry_grund: `${order.strategy} Signal (Engine)${grundSuffix}` });
  }

  portfolioRows.push({
    day, cash: result.cash, positions_value: result.portfolio.positions_value, total_equity: result.portfolio.total_equity,
    drawdown_pct: result.portfolio.drawdown_pct, open_positions_count: result.still_open_trades.length
  });

  stepCompletions.push(step.id);

  // Naechster Tag: NUR still_* uebernehmen, NICHT new_orders in pendingOrdersApi einhaengen
  // (siehe Modul-Kommentar oben - matcht das echte Live-Verhalten, nicht test_golden_run.py).
  cash = result.cash;
  peakEquity = result.portfolio.peak_equity;
  openTradesApi = result.still_open_trades;
  pendingOrdersApi = result.still_pending_orders;
}

return [{ json: {
  run_id: runId, orderUpdates, newOrderRows, newTradeRows, tradeUpdates, openTradeUpdates, newRecRows, recCloseUpdates,
  positionRows, portfolioRows, stepCompletions, lastDay: steps.length ? String(steps[steps.length - 1].simulated_date).slice(0, 10) : null
} }];

// FIX 2026-08-26: Signal-Berechnung (computeSignals je Ticker) war bisher Teil der einen
// grossen, synchronen "Verarbeite Tage-Paket"-Ausfuehrung - bei 15 Tickern x volle
// Indikatoren-Mathematik (SMA/EMA/RSI/MACD/Bollinger/ATR) je Ticker reichte das aus, um den
// geteilten n8n-Runner-Container komplett zu blockieren (WF15/WF16 blieben waehrenddessen
// haengen). Fix: dieser neue Zweig berechnet die Signale in kleinen Batches (separate n8n-
// Node-Ausfuehrungen statt einer einzigen), "Verarbeite Tage-Paket" liest das fertige
// Ergebnis nur noch, statt es selbst zu berechnen. Alles danach (Order-Fills, Exit-Pruefung,
// Positionsgroessen-Kappung, Hard-Limits) bleibt UNVERAENDERT - das ist bewusst sequenziell
// (eine Position, die HEUTE genehmigt wurde, zaehlt fuer die Pruefung des naechsten Tickers
// DESSELBEN Tages mit) und daher NICHT batchbar, aber auch nicht der teure Teil.
//
// Nimmt an, dass ein Paket genau EINEN Tag enthaelt (aktuell durchgesetzt via
// SIMULATION_DEFAULT_PACKAGE_SIZE=1) - bei mehreren Tagen pro Paket wuerde nur der erste Tag
// batchweise verarbeitet, siehe Warnung unten.

const pktCtx = $('Baue Paket-Kontext').all()[0].json;
const priceRows = $('DB: Preisdaten-Fenster laden').all().map(i => i.json);

const steps = [...pktCtx.steps].sort((a, b) => a.sequence_number - b.sequence_number);
if (steps.length > 1) {
  // Sollte mit der aktuellen Konfiguration (Package-Size 1) nie eintreten - Sicherheitsnetz,
  // falls das je geaendert wird, ohne dieses Batching entsprechend zu erweitern.
  throw new Error('Signal-Batching unterstuetzt aktuell nur genau 1 Tag pro Paket, steps.length=' + steps.length);
}
const day = steps.length ? String(steps[0].simulated_date).slice(0, 10) : null;

const barsByTicker = {};
