  '<table><tr><th>ID</th><th>Name</th><th>Zeitraum</th><th>Status</th><th>Fortschritt</th><th>Ergebnis</th><th>Letzter Heartbeat</th><th>Aktionen</th></tr>' +
  runsHtml +
  '</table>' +
  '</body></html>';

return [{ json: { html } }];

function pgStr(v) { return v === null || v === undefined ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }
function pgBool(v) { return v === null || v === undefined ? 'NULL' : (v ? 'TRUE' : 'FALSE'); }
function pgJsonb(v) { return (v === null || v === undefined) ? "'[]'::jsonb" : `'` + JSON.stringify(v).replace(/'/g, `''`) + `'::jsonb`; }
function getBusinessDate(date = new Date()) {
  return new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit', day: '2-digit'
  }).format(date);
}

// Aktions-Whitelist-Pattern, identisch zu Workflow 15/16. Zeitraum wird beim Run-Start in
// simulation_run_steps zerlegt (ein Schritt pro Werktag Mo-Fr - Feiertage werden vom Worker
// selbst uebersprungen, wenn an dem Tag fuer kein Instrument eine Kerze existiert).

const ALLOWED_ACTIONS = new Set(['create_run', 'pause', 'resume', 'cancel', 'delete_run']);
const MAX_INSTRUMENTS = 30;
const TICKER_REGEX = /^[A-Za-z0-9.\-^=]{1,20}$/;

const body = $input.item.json.body || $input.item.json;
const action = String(body.action || '').trim();

if (!ALLOWED_ACTIONS.has(action)) {
  return { json: { _error: 'Unbekannte Aktion: ' + action, sql: null } };
}

function randHex(n) {
  let s = '';
  for (let i = 0; i < n; i++) s += Math.floor(Math.random() * 16).toString(16);
  return s;
}

let sql = '';
let responseInfo = { action };

if (action === 'create_run') {
  const name = String(body.name || '').trim().slice(0, 200);
  const startDate = String(body.start_date || '').trim();
  const endDate = String(body.end_date || '').trim();
  const initialCapital = Number(body.initial_capital);
  const newsEnabled = body.news_enabled === 'true' || body.news_enabled === true;
  const ALLOWED_STRATEGIES = new Set(['mean_reversion', 'trend_following', 'breakout', 'news_event', 'momentum']);
  const runType = body.run_type === 'out_of_sample' ? 'out_of_sample' : 'walk_forward';
  const rawStrategyFilter = String(body.strategy_filter || '').trim();
  const strategyFilter = ALLOWED_STRATEGIES.has(rawStrategyFilter) ? rawStrategyFilter : null;
  const ALLOWED_LIVE_PARITY_MODES = new Set(['RESEARCH_BASELINE', 'AVAILABLE_DATA_LIVE_REPLAY']);
  const rawLiveParityMode = String(body.live_parity_mode || '').trim();
  // Fail-closed wie resolveLiveParityMode() in "Verarbeite Tage-Paket": jeder unbekannte/leere
  // Wert faellt auf RESEARCH_BASELINE zurueck (identisch zum bisherigen impliziten Verhalten, als
  // config_snapshot_json ueberhaupt kein mode-Feld hatte) - AVAILABLE_DATA_LIVE_REPLAY muss aktiv
  // gewaehlt werden, kann nie versehentlich zustande kommen (LIVE_PARITY Schritt 4L.3 Preflight-Fix,
  // 2026-09-12: vorher gab es ueberhaupt keinen Weg, mode ueber den regulaeren Startpfad zu setzen).
  const liveParityMode = ALLOWED_LIVE_PARITY_MODES.has(rawLiveParityMode) ? rawLiveParityMode : 'RESEARCH_BASELINE';
  // 09b (Lernagent Handelsstrategien) bestaetigt laut eigenem Code-Kommentar bewusst KEINE
  // einzelne Strategie durch einen Lauf ohne strategy_filter ("ein globaler Baseline-Test") -
  // ein Out-of-Sample-Lauf ohne strategy_filter waere deshalb wirkungslos, nicht nur unvollstaendig.
  if (runType === 'out_of_sample' && !strategyFilter) {
    return { json: { _error: 'Out-of-Sample-Laeufe brauchen eine einzelne Strategie (strategy_filter) - sonst bestaetigt der Lauf laut 09b keine einzelne Strategie.', sql: null } };
  }

  if (!name) return { json: { _error: 'Name fehlt.', sql: null } };
  if (!/^\d{4}-\d{2}-\d{2}$/.test(startDate) || !/^\d{4}-\d{2}-\d{2}$/.test(endDate)) {
    return { json: { _error: 'Start-/Enddatum fehlt oder ungueltiges Format (YYYY-MM-DD).', sql: null } };
  }
  if (endDate < startDate) return { json: { _error: 'Enddatum liegt vor dem Startdatum.', sql: null } };
  if (!Number.isFinite(initialCapital) || initialCapital < 1000) {
    return { json: { _error: 'Startkapital ungueltig (mindestens 1000).', sql: null } };
  }

  const rawInstruments = String(body.instruments || '').split(',').map(s => s.trim()).filter(Boolean);
  const seen = new Set();
  const instruments = [];
  const invalidInstruments = [];
  for (const raw of rawInstruments) {
    const t = raw.toUpperCase();
    if (!TICKER_REGEX.test(t)) { invalidInstruments.push(raw); continue; }
    if (seen.has(t)) continue;
    seen.add(t);
    instruments.push(t);
  }
  if (instruments.length === 0) {
    return { json: { _error: 'Keine gueltigen Instrumente angegeben.' + (invalidInstruments.length ? ' Ungueltig: ' + invalidInstruments.join(', ') : ''), sql: null } };
  }
  if (instruments.length > MAX_INSTRUMENTS) {
    return { json: { _error: 'Zu viele Instrumente (max ' + MAX_INSTRUMENTS + ').', sql: null } };
  }

  // Werktage Mo-Fr zwischen start/end enumerieren - der Worker ueberspringt Tage ohne echte
  // Kerzendaten selbst (Feiertage), hier nur die grobe Kalenderstruktur.
  const days = [];
  let cursor = new Date(startDate + 'T00:00:00Z');
  const end = new Date(endDate + 'T00:00:00Z');
  while (cursor <= end && days.length < 5000) {
    const dow = cursor.getUTCDay(); // 0=So, 6=Sa
    if (dow !== 0 && dow !== 6) days.push(cursor.toISOString().slice(0, 10));
    cursor = new Date(cursor.getTime() + 24 * 3600 * 1000);
  }
  if (days.length === 0) {
    return { json: { _error: 'Zeitraum enthaelt keine Werktage.', sql: null } };
  }

  const runIdHint = 'sim-' + getBusinessDate() + '-' + randHex(6);

  // Data-modifying CTE: new_run haelt genau 1 Zeile (die neu eingefuegte backtest_runs-Zeile
  // mit ihrer id). Die Tages-Schritte werden per CROSS JOIN mit dieser einen Zeile verknuepft -
  // die VALUES-Liste selbst enthaelt NUR (seq, day)-Tupel, new_run.id wird erst im SELECT
  // dazugemischt (new_run.id INNERHALB der VALUES-Tupel waere ungueltiges SQL, da VALUES keinen
  // Zugriff auf andere Tabellen/CTEs hat).
  const stepValues = days.map((day, idx) => `(${pgNum(idx + 1)}, ${pgStr(day)}::date)`).join(',\n    ');

  // Out-of-Sample-Ueberschneidungs-Sperre: dieselbe Strategie darf nicht zweimal ueber densel
  // ben (oder ueberlappenden) Zeitraum als OOS bestaetigt werden - sonst liesse sich ein
  // unerwuenschtes Ergebnis durch einfaches Wiederholen "wegwuerfeln" (p-hacking-Schutz).
  // Als WHERE-Klausel im INSERT SELECT statt eines separaten Pruef-Node, um im selben
  // Statement/derselben Transaktion atomar zu bleiben (kein zusaetzlicher Roundtrip noetig).
  sql = `WITH new_run AS (
  INSERT INTO trading.backtest_runs
    (backtest_id, run_type, configuration_version, rule_version, status, data_category, name, start_date, end_date, current_simulation_date,
     timezone, instrument_selection_json, news_enabled, fundamentals_enabled, portfolio_enabled,
     learning_enabled, initial_capital, currency, progress_total, created_by, strategy_filter, config_snapshot_json)
  SELECT ${pgStr(runIdHint)}, ${pgStr(runType)}, 'historische-simulation-v1', 'historische-simulation-v1', 'queued', 'historical_replay', ${pgStr(name)}, ${pgStr(startDate)}, ${pgStr(endDate)},
         ${pgStr(startDate)}, 'Europe/Berlin', ${pgJsonb(instruments)}, ${pgBool(newsEnabled)}, FALSE, TRUE, FALSE,
         ${pgNum(initialCapital)}, 'EUR', ${pgNum(days.length)}, 'simulation-steuerzentrale', ${pgStr(strategyFilter)},
         -- FIX 2026-08-20 (EXPERIMENT_PLATFORM_REVIEW.md, Config-Snapshot-Fix): friert die
         -- tatsaechlich aktive Konfiguration EINMALIG bei Run-Erstellung ein, damit der Worker
         -- (Baue Run-Kontext) sie nicht mehr bei jedem Tick live nachladen muss/kann - siehe dort.
         (SELECT jsonb_build_object(
            'pipeline_config', (SELECT jsonb_object_agg(config_key, jsonb_build_object('value_bool', value_bool, 'value_text', value_text, 'value_numeric', value_numeric)) FROM trading.pipeline_config),
            'scoring_weights', (SELECT jsonb_object_agg(weight_key, jsonb_build_object('value', weight_value, 'version', version)) FROM trading.scoring_weights WHERE active = TRUE),
            'regime_matrix', (SELECT jsonb_agg(jsonb_build_object('rule_version', rule_version, 'strategy', strategy, 'combined_regime', combined_regime, 'fit_multiplier', fit_multiplier, 'blocked', blocked)) FROM trading.strategy_regime_matrix WHERE active = TRUE),
            'mode', ${pgStr(liveParityMode)},
            'snapshot_taken_at', now()
         ))
  WHERE ${pgStr(runType)} <> 'out_of_sample' OR NOT EXISTS (
    SELECT 1 FROM trading.backtest_runs br2
    WHERE br2.run_type = 'out_of_sample' AND br2.strategy_filter = ${pgStr(strategyFilter)}
      AND br2.status IN ('queued','running','pausing','completed','completed_with_warnings')
      AND daterange(br2.start_date, br2.end_date, '[]') && daterange(${pgStr(startDate)}::date, ${pgStr(endDate)}::date, '[]')
  )
  RETURNING id
)
INSERT INTO trading.simulation_run_steps (simulation_run_id, sequence_number, simulated_date, status)
SELECT new_run.id, s.seq, s.day, 'pending'
FROM new_run, (VALUES\n    ${stepValues}\n) AS s(seq, day);
SELECT EXISTS(SELECT 1 FROM trading.backtest_runs WHERE backtest_id = ${pgStr(runIdHint)}) AS created;`;

  responseInfo = { action, run_id_hint: runIdHint, day_count: days.length, instrument_count: instruments.length, invalid_instruments: invalidInstruments, run_type: runType, strategy_filter: strategyFilter };

} else if (action === 'pause') {
  const runId = String(body.run_id || '').trim();
  if (!runId) return { json: { _error: 'run_id fehlt.', sql: null } };
  sql = `UPDATE trading.backtest_runs SET status = 'pausing' WHERE id = ${pgNum(runId)} AND status IN ('queued','running');`;
  responseInfo = { action, run_id: runId };

} else if (action === 'resume') {
  const runId = String(body.run_id || '').trim();
  if (!runId) return { json: { _error: 'run_id fehlt.', sql: null } };
  sql = `UPDATE trading.backtest_runs SET status = 'queued' WHERE id = ${pgNum(runId)} AND status = 'paused';`;
  responseInfo = { action, run_id: runId };

} else if (action === 'cancel') {
  const runId = String(body.run_id || '').trim();
  if (!runId) return { json: { _error: 'run_id fehlt.', sql: null } };
  sql = `UPDATE trading.backtest_runs SET status = 'cancelled', cancelled_at = now() WHERE id = ${pgNum(runId)} AND status IN ('draft','queued','running','pausing','paused');
UPDATE trading.simulation_run_steps SET status = 'skipped' WHERE simulation_run_id = ${pgNum(runId)} AND status IN ('pending','running');`;
  responseInfo = { action, run_id: runId };

} else if (action === 'delete_run') {
  const runIdRaw = String(body.run_id || '').trim();
  if (!/^\d+$/.test(runIdRaw)) return { json: { _error: 'run_id fehlt oder ungueltig.', sql: null } };
  const rid = Number(runIdRaw);
  // Ein Lauf wird komplett entfernt (alle FK-Kindtabellen + backtest_runs), aber NUR wenn er
  // in einem Endzustand ist - ein laufender/wartender Lauf muss erst abgebrochen werden, sonst
  // schreibt der Worker parallel weiter in gerade geloeschte Tabellen. Umsetzung als EIN
  // data-modifying CTE (n8n Postgres "Execute Query" fuehrt Multi-Statement als eine implizite
  // Transaktion aus): `target` ist leer, wenn der Lauf nicht loeschbar ist -> alle DELETEs sind
  // No-ops und `deleted` kommt false zurueck. learning_rule_proposals.source_run_id wird auf
  // NULL gesetzt (der Vorschlag bleibt gueltig, nur die Herkunftsangabe entfaellt).
  sql = `WITH target AS (
  SELECT id, backtest_id FROM trading.backtest_runs
  WHERE id = ${rid} AND status IN ('completed','completed_with_warnings','failed','cancelled')
),
d_trades AS (DELETE FROM trading.simulation_trades         WHERE simulation_run_id IN (SELECT id FROM target) RETURNING 1),
d_orders AS (DELETE FROM trading.simulation_orders         WHERE simulation_run_id IN (SELECT id FROM target) RETURNING 1),
d_pos    AS (DELETE FROM trading.simulation_positions       WHERE simulation_run_id IN (SELECT id FROM target) RETURNING 1),
d_port   AS (DELETE FROM trading.simulation_daily_portfolio WHERE simulation_run_id IN (SELECT id FROM target) RETURNING 1),
d_recs   AS (DELETE FROM trading.simulation_recommendations WHERE simulation_run_id IN (SELECT id FROM target) RETURNING 1),
d_steps  AS (DELETE FROM trading.simulation_run_steps       WHERE simulation_run_id IN (SELECT id FROM target) RETURNING 1),
d_err    AS (DELETE FROM trading.simulation_errors          WHERE simulation_run_id IN (SELECT id FROM target) RETURNING 1),
d_evt    AS (DELETE FROM trading.simulation_events          WHERE simulation_run_id IN (SELECT id FROM target) RETURNING 1),
d_met    AS (DELETE FROM trading.simulation_metrics         WHERE simulation_run_id IN (SELECT id FROM target) RETURNING 1),
d_bt     AS (DELETE FROM trading.backtest_trades            WHERE backtest_id     IN (SELECT backtest_id FROM target) RETURNING 1),
u_lrp    AS (UPDATE trading.learning_rule_proposals SET source_run_id = NULL WHERE source_run_id IN (SELECT id FROM target) RETURNING 1),
d_run    AS (DELETE FROM trading.backtest_runs              WHERE id IN (SELECT id FROM target) RETURNING 1)
SELECT (SELECT count(*) FROM d_run) > 0 AS deleted;`;
  responseInfo = { action, run_id: rid };
}

return { json: { sql, ...responseInfo } };

// Gleiches Muster wie Workflow 15/16.
const items = $input.all().filter(i => i.json && i.json.id);
if (items.length === 0) {
  return [{ json: { _kein_run: true } }];
}
const run = items[0].json;
return [{ json: { ...run, _kein_run: false, _run_pausierend: run.status === 'pausing' } }];

// alwaysOutputData:true liefert bei 0 aktualisierten Zeilen (Lock nicht erhalten, ein anderer
// Tick bearbeitet diesen Lauf gerade) ein Platzhalter-Item ohne id.
const items = $input.all().filter(i => i.json && i.json.id !== undefined && i.json.id !== null);
return [{ json: { _lock_acquired: items.length > 0 } }];

// Traegt Lauf-Daten und Konfigurationswerte zusammen. Fehlende Config-Werte bekommen
// dieselben Standardwerte wie in 06/14 dokumentiert.
//
// FIX 2026-08-20 (EXPERIMENT_PLATFORM_REVIEW.md, Config-Snapshot-Fix): cfgByKey kam bisher aus
// einer bei JEDEM Worker-Tick frisch ausgefuehrten Live-Query gegen trading.pipeline_config
// ("DB: Simulations-Konfiguration laden" - jetzt aus dem Ausfuehrungspfad entfernt, Node bleibt
// zur Nachvollziehbarkeit stehen, ist aber nicht mehr verbunden). run.config_snapshot_json wird
// EINMALIG bei Run-Erstellung eingefroren und hier fuer die GESAMTE Laufzeit des Laufs
// unveraendert wiederverwendet.
//
// v2 (2026-09-06, Reparaturbericht Punkt 2): _package_size ist fuer historische-simulation-v2
// AUSDRUECKLICH auf 1 erzwungen (nicht mehr aus der Config gelesen) - der neue
// Recommendation/Order/Trade-Ablauf enthaelt zeitlich abhaengige Zustandsuebergaenge
// (Same-Day-Close-and-Reopen), die nur bei genau einem Simulationstag je Worker-Tick/SQL-
// Transaktion garantiert korrekt bleiben. Package-Batching darf erst nach separatem Design +
// Tests wieder eingefuehrt werden (nicht Teil dieser Reparatur).
//
// v2 Punkt 9: MINI_FUTURE_LEVERAGE entfernt (nachweislich nie in einer Rechenoperation
// verwendet, siehe Sitzungsdiagnose 2026-09-06) - v2 ist ein ausdruecklich ungehebelter
// Research-Backtest. Das Kostenmodell (Spread+Finanzierung) bleibt inhaltlich unveraendert,
// liest aber die neuen, eindeutig benannten RESEARCH_BACKTEST_*-Keys (Migration 085) statt
// MINI_FUTURE_*. Die MINI_FUTURE_*-Keys bleiben fuer v1 unangetastet in der Config bestehen.
const run = $('Pruefe Run-Zustand').all()[0].json;
const snapshot = run.config_snapshot_json || {};
const cfgByKey = {};
for (const [key, entry] of Object.entries(snapshot.pipeline_config || {})) {
  const v = entry && entry.value_numeric !== null && entry.value_numeric !== undefined ? Number(entry.value_numeric) : null;
  if (v !== null && !isNaN(v)) cfgByKey[key] = v;
}

function num(key, fallback) {
  const v = cfgByKey[key];
  return (v !== undefined && v !== null && !isNaN(v)) ? v : fallback;
}

return [{ json: {
  ...run,
  _package_size: 1, // v2: hart erzwungen, siehe Kommentar oben - NICHT aus der Config gelesen
  _model_portfolio_value: run.initial_capital || num('MODEL_PORTFOLIO_VALUE', 100000),
  _max_risk_per_trade_pct: num('MAX_RISK_PER_TRADE_PCT', 1.0),
  _min_reward_risk_ratio: num('MIN_REWARD_RISK_RATIO', 1.5),
  _fees_bps: num('DEFAULT_FEES_BPS', 15),
  _slippage_bps: num('DEFAULT_SLIPPAGE_BPS', 10),
  _ambiguous_bar_policy_code: num('AMBIGUOUS_BAR_POLICY_CODE', 1),
  _max_total_open_risk_pct: num('MAX_TOTAL_OPEN_RISK_PCT', 6.0),
  _max_sector_exposure_pct: num('MAX_SECTOR_EXPOSURE_PCT', 15.0),
  _max_single_position_pct: num('MAX_SINGLE_POSITION_PCT', 8.0),
  _max_open_positions: num('MAX_OPEN_POSITIONS', 10),
  _max_directional_exposure_pct: num('MAX_DIRECTIONAL_EXPOSURE_PCT', 40.0),
