const MIN_TRADABLE_QUANTITY = 1;
// LIVE_PARITY-Vorbereitung Schritt 1 (2026-09-07): reine, zustandslose Trade-Geometrie -
// unveraendert 1:1 aus sizePosition() extrahiert (Math.abs()-Formeln sind bereits
// richtungsagnostisch, LONG/SHORT brauchen daher keine getrennte Formel). Wird jetzt an ZWEI
// Stellen aufgerufen (hier in sizePosition() und weiter unten im Kandidaten-Loop), damit es nur
// EINE fachliche Formel gibt statt zweier unabhaengig gepflegter - beide Aufrufe sind reine
// Funktionsaufrufe mit identischen Eingaben, keine Zustandsteilung, kein Drift-Risiko.
function calculateTradeGeometry(entryReferencePrice, stopPrice, targetPrice) {
  const unitRisk = Math.abs(entryReferencePrice - stopPrice);
  const rewardDistance = Math.abs(targetPrice - entryReferencePrice);
  const rewardRiskRatio = rewardDistance / unitRisk;
  // FIX 2026-09-07 (LIVE_PARITY-Vorbereitung Schritt 1B, Geometry-NaN-Bug): klassifiziert
  // fehlende/nicht-numerische/nicht-endliche EINGABEWERTE. Bewusst NICHT hier erfasst:
  // rewardRiskRatio=Infinity/NaN, wenn sie AUSSCHLIESSLICH aus unitRisk===0 bei sonst
  // validen, endlichen Werten entsteht - das bleibt der bestehende, unveraenderte
  // STOP_WRONG_SIDE-Fachfall in sizePosition() (Phase 4 der Reparatur: bestehende Vetos
  // bleiben unangetastet). reward_risk_ratio_finite wird trotzdem als eigenes Diagnosefeld
  // zurueckgegeben, damit sie fuer spaetere Auswertung sichtbar bleibt, OHNE selbst die
  // geometry_error-Klassifikation zu beeinflussen.
  let geometryError = null;
  if (!Number.isFinite(entryReferencePrice)) geometryError = 'ENTRY_INVALID';
  else if (!Number.isFinite(stopPrice)) geometryError = 'STOP_MISSING';
  else if (!Number.isFinite(targetPrice)) geometryError = 'TARGET_MISSING';
  else if (!Number.isFinite(unitRisk) || !Number.isFinite(rewardDistance)) geometryError = 'NON_FINITE';
  return {
    entry_reference_price: entryReferencePrice,
    unit_risk: unitRisk,
    reward_distance: rewardDistance,
    reward_risk_ratio: rewardRiskRatio,
    reward_risk_ratio_finite: Number.isFinite(rewardRiskRatio),
    geometry_valid: unitRisk > 0,
    geometry_error: geometryError
  };
}
function sizePosition(signal, entryPriceEstimate, cfg, openPositionsState, sektor, region) {
  const geometry = calculateTradeGeometry(entryPriceEstimate, signal.stop_price, signal.target_price);
  const unitRisk = geometry.unit_risk;
  if (unitRisk <= 0) return { veto: 'STOP_WRONG_SIDE', unit_risk: unitRisk };
  const theoreticalRiskAmount = cfg.modelPortfolioValue * (cfg.maxRiskPerTradePct / 100);
  const riskBasedQuantity = Math.floor(theoreticalRiskAmount / unitRisk);
  if (riskBasedQuantity <= 0) return { veto: 'STOP_TARGET_INVALID', theoretical_quantity: riskBasedQuantity, unit_risk: unitRisk, theoretical_risk_amount: theoreticalRiskAmount };
  const maxSinglePositionQuantity = Math.floor((cfg.modelPortfolioValue * (cfg.maxSinglePositionPct / 100)) / entryPriceEstimate);
  const currentTotalRisk = openPositionsState.reduce((sum, p) => sum + p.risk_amount, 0);
  const remainingPortfolioRiskBudget = Math.max(0, cfg.modelPortfolioValue * (cfg.maxTotalOpenRiskPct / 100) - currentTotalRisk);
  const remainingPortfolioQuantity = Math.floor(remainingPortfolioRiskBudget / unitRisk);
  const currentSectorValue = openPositionsState.filter(p => p.sektor === sektor).reduce((sum, p) => sum + p.position_value, 0);
  const remainingSectorValue = Math.max(0, cfg.modelPortfolioValue * (cfg.maxSectorExposurePct / 100) - currentSectorValue);
  const remainingSectorQuantity = Math.floor(remainingSectorValue / entryPriceEstimate);
  const currentRegionValue = openPositionsState.filter(p => p.region === region).reduce((sum, p) => sum + p.position_value, 0);
  const remainingRegionValue = Math.max(0, cfg.modelPortfolioValue * (cfg.maxRegionExposurePct / 100) - currentRegionValue);
  const remainingRegionQuantity = Math.floor(remainingRegionValue / entryPriceEstimate);
  const candidates = [
    { quantity: riskBasedQuantity, reason: null },
    { quantity: maxSinglePositionQuantity, reason: 'SINGLE_POSITION_LIMIT' },
    { quantity: remainingPortfolioQuantity, reason: 'TOTAL_RISK_LIMIT' },
    { quantity: remainingSectorQuantity, reason: 'SECTOR_LIMIT' },
    { quantity: remainingRegionQuantity, reason: 'REGION_LIMIT' }
  ];
  let binding = candidates[0];
  for (const c of candidates) if (c.quantity < binding.quantity) binding = c;
  const finalQuantity = Math.max(0, Math.floor(binding.quantity));
  // J2 (2026-09-07): unit_risk/theoretical_risk_amount/quantity_by_value ab hier zusaetzlich
  // in jedem Veto-Zweig zurueckgegeben - reine Diagnose-Anreicherung, keine der folgenden
  // Bedingungen/Schwellen/Reihenfolgen ist gegenueber vorher veraendert.
  if (finalQuantity < MIN_TRADABLE_QUANTITY) return { veto: 'QUANTITY_TOO_SMALL', binding_limit: binding.reason, theoretical_quantity: riskBasedQuantity, unit_risk: unitRisk, theoretical_risk_amount: theoreticalRiskAmount, quantity_by_value: maxSinglePositionQuantity };
  const positionValue = finalQuantity * entryPriceEstimate;
  const actualRiskAmount = finalQuantity * unitRisk;
  const estimatedFees = positionValue * (cfg.feesBps / 10000);
  const estimatedSlippage = positionValue * (cfg.slippageBps / 10000);
  if ((estimatedFees + estimatedSlippage) * 2 > actualRiskAmount) return { veto: 'UNECONOMICAL_AFTER_COSTS', binding_limit: binding.reason, theoretical_quantity: riskBasedQuantity, unit_risk: unitRisk, theoretical_risk_amount: theoreticalRiskAmount, quantity_by_value: maxSinglePositionQuantity };
  const rewardRiskRatio = geometry.reward_risk_ratio;
  if (rewardRiskRatio < cfg.minRewardRiskRatio) return { veto: 'RRR_TOO_LOW', theoretical_quantity: riskBasedQuantity, unit_risk: unitRisk, theoretical_risk_amount: theoreticalRiskAmount, quantity_by_value: maxSinglePositionQuantity, reward_risk_ratio: rewardRiskRatio };
  return {
    veto: null, theoretical_quantity: riskBasedQuantity, actual_quantity: finalQuantity,
    theoretical_risk_amount: theoreticalRiskAmount, actual_risk_amount: actualRiskAmount,
    unit_risk: unitRisk, position_value: positionValue, reward_risk_ratio: rewardRiskRatio,
    quantity_by_value: maxSinglePositionQuantity,
    clamped: finalQuantity < riskBasedQuantity, clamp_reason: finalQuantity < riskBasedQuantity ? binding.reason : null
  };
}
// Nur noch die NICHT mengenreduzierbaren Haertegrenzen - Gesamtrisiko/Sektor/Einzelposition/
// Region werden bereits VOR der Order-Erzeugung in sizePosition() per Kappung beruecksichtigt.
function checkHardLimits(direction, positionValue, openPositionsState, cfg) {
  const blockers = [];
  if (openPositionsState.length + 1 > cfg.maxOpenPositions) blockers.push('MAX_OPEN_POSITIONS');
  const directionalValue = openPositionsState.filter(p => p.direction === direction).reduce((sum, p) => sum + p.position_value, 0) + positionValue;
  if (directionalValue / cfg.modelPortfolioValue * 100 > cfg.maxDirectionalExposurePct) blockers.push('DIRECTIONAL_LIMIT');
  return blockers;
}

// J2 (2026-09-07): reine Diagnose-Ableitungen fuer das Decision-Log, aus bereits vorhandenen
// Daten (runCtx.config_snapshot_json.regime_matrix ist Teil des beim Run-Start eingefrorenen
// Snapshots, siehe "Baue Run-Kontext"). Werden NIRGENDS zur Steuerung von Kandidaten-
// Annahme/Ablehnung verwendet - WF17 wendet fit_multiplier/regime_matrix in der eigentlichen
// Handelslogik aktuell nicht an (siehe G1-Befund Sitzungsdiagnose 2026-09-07); diese Funktionen
// machen das nur fuer die spaetere Ablation sichtbar.
function fitMultiplierFor(strategyName, combinedRegimeValue) {
  const matrix = (runCtx.config_snapshot_json && runCtx.config_snapshot_json.regime_matrix) || [];
  const row = matrix.find(m => m.strategy === strategyName && m.combined_regime === combinedRegimeValue);
  return row ? row.fit_multiplier : null;
}

