// Job-A ENGINE-Portfolio-Check, 1:1 aus trading_engine/risk_limits.py::check_portfolio_limits()
// (frisch gegen die aktuelle Python-Quelle verglichen, 4O.3B Phase 15) - nutzt WF17s EIGENE,
// bereits Schritt-2-parity-gepruefte pearsonCorrelation() statt einer zweiten Kopie.
function checkShadowPortfolioLimits(candidate, ticker, sektor, region, currency, direction, shadowPortfolio, riskCfg, isStressRegime, correlationData) {
  const blockers = [];
  const mpv = riskCfg.model_portfolio_value;
  const openPositions = shadowPortfolio.open_positions;

  const riskBefore = openPositions.reduce((s, p) => s + p.risk_amount, 0);
  const riskAfter = riskBefore + candidate.risk_amount;
  const portfolioRiskAfterPct = mpv > 0 ? (riskAfter / mpv) * 100 : 0;
  const effectiveMaxTotalRiskPct = isStressRegime ? riskCfg.max_total_open_risk_pct * riskCfg.stress_risk_reduction_factor : riskCfg.max_total_open_risk_pct;
  if (portfolioRiskAfterPct > effectiveMaxTotalRiskPct) blockers.push({ limit_name: 'TOTAL_RISK_LIMIT', current_value: portfolioRiskAfterPct, limit_value: effectiveMaxTotalRiskPct });

  const sektorWert = openPositions.filter(p => p.sektor === sektor).reduce((s, p) => s + p.position_value, 0) + candidate.position_value;
  const sektorPct = mpv > 0 ? (sektorWert / mpv) * 100 : 0;
  if (sektorPct > riskCfg.max_sector_exposure_pct) blockers.push({ limit_name: 'SECTOR_LIMIT', current_value: sektorPct, limit_value: riskCfg.max_sector_exposure_pct });

  const regionWert = openPositions.filter(p => p.region === region).reduce((s, p) => s + p.position_value, 0) + candidate.position_value;
  const regionPct = mpv > 0 ? (regionWert / mpv) * 100 : 0;
  if (regionPct > riskCfg.max_region_exposure_pct) blockers.push({ limit_name: 'REGION_LIMIT', current_value: regionPct, limit_value: riskCfg.max_region_exposure_pct });

  if (currency !== 'EUR') {
    const nonEurWert = openPositions.filter(p => p.currency !== 'EUR').reduce((s, p) => s + p.position_value, 0) + candidate.position_value;
    const nonEurPct = mpv > 0 ? (nonEurWert / mpv) * 100 : 0;
    if (nonEurPct > riskCfg.max_non_eur_exposure_pct) blockers.push({ limit_name: 'CURRENCY_LIMIT', current_value: nonEurPct, limit_value: riskCfg.max_non_eur_exposure_pct });
  }

  const einzelAnteilPct = mpv > 0 ? (candidate.position_value / mpv) * 100 : 0;
  if (einzelAnteilPct > riskCfg.max_single_position_pct) blockers.push({ limit_name: 'SINGLE_POSITION_LIMIT', current_value: einzelAnteilPct, limit_value: riskCfg.max_single_position_pct });

  if (openPositions.length + 1 > riskCfg.max_open_positions) blockers.push({ limit_name: 'MAX_OPEN_POSITIONS', current_value: openPositions.length + 1, limit_value: riskCfg.max_open_positions });

  const richtungWert = openPositions.filter(p => p.direction === direction).reduce((s, p) => s + p.position_value, 0) + candidate.position_value;
  const richtungPct = mpv > 0 ? (richtungWert / mpv) * 100 : 0;
  if (richtungPct > riskCfg.max_directional_exposure_pct) blockers.push({ limit_name: 'DIRECTIONAL_LIMIT', current_value: richtungPct, limit_value: riskCfg.max_directional_exposure_pct });

  if (shadowPortfolio.drawdown_pct > riskCfg.max_portfolio_drawdown_pct) blockers.push({ limit_name: 'DRAWDOWN_LIMIT', current_value: shadowPortfolio.drawdown_pct, limit_value: riskCfg.max_portfolio_drawdown_pct });

  if (correlationData) {
    const candReturns = correlationData[ticker];
    if (candReturns) {
      let maxCorr = null, maxCorrTicker = null;
      for (const p of openPositions) {
        if (p.ticker === ticker) continue;
        const other = correlationData[p.ticker];
        if (!other) continue;
        const c = pearsonCorrelation(candReturns, other);
        if (c !== null && (maxCorr === null || Math.abs(c) > Math.abs(maxCorr))) { maxCorr = c; maxCorrTicker = p.ticker; }
      }
      if (maxCorr !== null && Math.abs(maxCorr) > riskCfg.max_pairwise_correlation) blockers.push({ limit_name: 'CORRELATION_LIMIT', current_value: Math.abs(maxCorr), limit_value: riskCfg.max_pairwise_correlation, ref_ticker: maxCorrTicker });
    }
  }
  return blockers;
}


