// LIVE_PARITY-Vorbereitung Schritt 2 (2026-09-07): reine Daten-/Helper-Vorbereitung fuer
// Point-in-Time Pearson-Korrelation - NOCH NICHT an checkHardLimits()/sizePosition()
// angeschlossen, keine Entscheidung aendert sich dadurch (siehe Bericht).
//
// 1:1 uebersetzt aus WF14 "Job A: Portfoliopruefung + Trade-Anlage" (dailyReturns()/
// pearson()), identisch nochmal uebersetzt in trading_engine/risk_limits.py::_pearson().
// WICHTIGER BEFUND (am aktuellen Code verifiziert, nicht aus frueherem Bericht uebernommen):
// die Referenz fuehrt KEIN echtes Datums-Alignment zwischen zwei Return-Serien durch - sie
// nimmt naiv die jeweils letzten n = min(len(a), len(b)) Werte beider Arrays (a.slice(-n),
// b.slice(-n)) und rechnet sie rein positionell gegeneinander, ohne zu pruefen, ob die
// zugrundeliegenden Handelstage tatsaechlich uebereinstimmen. "Dieselben Daten wie die
// Python-Engine" heisst deshalb hier bewusst: dieses naive Verhalten 1:1 nachbauen, NICHT
// durch ein "korrekteres" echtes Datums-Matching ersetzen, das von der Referenz abweichen
// wuerde. dailyReturnsForCorrelation() liefert Datumsbezug trotzdem mit zurueck (additiv,
// aendert die numerische Berechnung nicht) - fuer spaetere Diagnose/Debugging.
const CORRELATION_LOOKBACK_DAYS = 60;
const correlationReturnsCache = {};
// Point-in-Time ausschliesslich ueber barsUpTo() (kein Kursdatum > day moeglich). Analogon zu
// dailyReturns(ticker) aus WF14 Job A, aber auf der bereits geladenen vollstaendigen
// Point-in-Time-Historie statt einer live gefensterten DB-Abfrage (dort: "trading_date >=
// heute - 70 Kalendertage"). Das Live-70-Tage-Fenster liefert bei ueblichem Handelskalender
// typischerweise nur ~48-50 Handelstage, nicht die vollen CORRELATION_LOOKBACK_DAYS+1=61 -
// das ist eine Limitierung dieser einen Live-Abfrage, keine Eigenschaft von dailyReturns()
// selbst. WF17 haelt die komplette Historie bereits in barsByTicker vor, daher hier bewusst
// gegen die volle point-in-time verfuegbare Reihe geslict statt das Live-Limit nachzubauen -
// das ist die treuere Umsetzung der in dailyReturns()/CORRELATION_LOOKBACK_DAYS erklaerten
// Absicht, keine Abweichung von ihr.
function dailyReturnsForCorrelation(ticker, day) {
  const cacheKey = ticker + '|' + day;
  if (correlationReturnsCache[cacheKey]) return correlationReturnsCache[cacheKey];
  const rows = barsUpTo(ticker, day).slice(-(CORRELATION_LOOKBACK_DAYS + 1));
  const parsed = rows.map(r => ({ date: r.date, close: Number(r.close) })).filter(r => !isNaN(r.close));
  const rets = [];
  for (let i = 1; i < parsed.length; i++) {
    if (parsed[i - 1].close > 0) rets.push({ date: parsed[i].date, return: (parsed[i].close - parsed[i - 1].close) / parsed[i - 1].close });
  }
  correlationReturnsCache[cacheKey] = rets;
  return rets;
}
// 1:1 aus WF14 pearson() / risk_limits.py::_pearson(). Nimmt entweder {date, return}-Objekte
// (aus dailyReturnsForCorrelation) oder reine Zahlen entgegen - in die Berechnung fliessen
// ausschliesslich die numerischen Werte ein, exakt wie in der Referenz (siehe Kommentar oben:
// KEIN echtes Datums-Matching, rein positionelles Trimmen auf die kuerzere Laenge).
function pearsonCorrelation(seriesA, seriesB) {
  const a = seriesA.map(x => (typeof x === 'number' ? x : x.return));
  const b = seriesB.map(x => (typeof x === 'number' ? x : x.return));
  const n = Math.min(a.length, b.length);
  if (n < 10) return null;
  const av = a.slice(-n), bv = b.slice(-n);
  const meanA = av.reduce((x, y) => x + y, 0) / n, meanB = bv.reduce((x, y) => x + y, 0) / n;
  let cov = 0, varA = 0, varB = 0;
  for (let i = 0; i < n; i++) { cov += (av[i] - meanA) * (bv[i] - meanB); varA += (av[i] - meanA) ** 2; varB += (bv[i] - meanB) ** 2; }
  if (varA === 0 || varB === 0) return null;
  return cov / Math.sqrt(varA * varB);
}
// Vorbereitende Buendel-Funktion fuer den spaeteren LIVE_PARITY-Engine-Aufruf (Phase 12) -
// WICHTIG: wird in Schritt 2 an keiner Stelle aufgerufen, keine Entscheidung nutzt dies.
function getCorrelationData(candidateTicker, openPositionsState, day) {
  const candidateReturns = dailyReturnsForCorrelation(candidateTicker, day);
  const perTicker = {};
  for (const pos of openPositionsState) {
    if (pos.ticker === candidateTicker) continue;
    if (perTicker[pos.ticker]) continue;
    perTicker[pos.ticker] = pearsonCorrelation(candidateReturns, dailyReturnsForCorrelation(pos.ticker, day));
