function nextWeekday(dateStr) {
  let d = new Date(dateStr + 'T00:00:00Z');
  d = new Date(d.getTime() + 24 * 3600 * 1000);
  while (d.getUTCDay() === 0 || d.getUTCDay() === 6) d = new Date(d.getTime() + 24 * 3600 * 1000);
  return d.toISOString().slice(0, 10);
}
