function deriveRegion(exchange) {
  const ex = String(exchange || '').toUpperCase();
  if (ex.includes('XETRA') || ex.includes('FRA') || ex.includes('GER')) return 'Europa';
  if (ex.includes('NASDAQ') || ex.includes('NYSE')) return 'USA';
  return 'global';
}
