  const t = r.ticker;
  if (!barsByTicker[t]) barsByTicker[t] = [];
  barsByTicker[t].push({ date: String(r.trading_date).slice(0, 10), open: Number(r.open), high: Number(r.high), low: Number(r.low), close: Number(r.close), volume: Number(r.volume) });
}
for (const t in barsByTicker) barsByTicker[t].sort((a, b) => a.date < b.date ? -1 : (a.date > b.date ? 1 : 0));

function barsUpTo(ticker, dateStr) {
  const all = barsByTicker[ticker] || [];
  const idx = all.findIndex(b => b.date > dateStr);
  return idx === -1 ? all : all.slice(0, idx);
}
function barOn(ticker, dateStr) {
  const all = barsByTicker[ticker] || [];
  return all.find(b => b.date === dateStr) || null;
}
function toApiBar(ticker, b) {
  return { ticker, trading_date: b.date, open: b.open, high: b.high, low: b.low, close: b.close, volume: b.volume };
}

