    strategy: o.strategy || '', sektor: o.sektor || tickerToSektor[o.ticker] || 'unbekannt',
    region: o.region || tickerToRegion[o.ticker] || 'global', risk_amount: Number(o.risk_amount),
    time_stop_at: isoOrNull(o.time_stop_at),
    theoretical_quantity: Number(o.theoretical_quantity || 0), theoretical_risk_amount: Number(o.theoretical_risk_amount || 0),
    clamp_reason: o.clamp_reason || null
  };
});

const steps = [...pktCtx.steps].sort((a, b) => a.sequence_number - b.sequence_number);

const orderUpdates = [];
const newOrderRows = [];
const newTradeRows = [];
const tradeUpdates = [];
const openTradeUpdates = [];
const newRecRows = [];
