    });
    delete orderMetaByTicker[trade.ticker];
  }

  for (const ex of result.exited_trades) {
    const t = ex.trade, er = ex.exit_result, pnl = ex.pnl;
    tradeUpdates.push({
      trade_id: t.trade_id, exit_time: day, exit_price: er.price, exit_reason: er.reason,
      gross_pnl: pnl.gross_pnl, net_pnl: pnl.net_pnl, r_multiple: t.risk_amount > 0 ? pnl.net_pnl / t.risk_amount : null,
      commission_total: pnl.entry_fee + pnl.exit_fee, slippage_total: pnl.financing_cost
    });
    recCloseUpdates.push({ ticker: t.ticker, run_id: runId, exit_day: day });
  }

  for (const trade of result.still_open_trades) {
    openTradeUpdates.push({ trade_id: trade.trade_id, stop_price_current: trade.stop_price_current, extreme_price_since_entry: trade.extreme_price_since_entry });
    const bar = barOn(trade.ticker, day);
    const markPrice = bar ? bar.close : trade.entry_price;
    const unrealizedPnl = (trade.direction === 'long' ? (markPrice - trade.entry_price) : (trade.entry_price - markPrice)) * trade.quantity;
    positionRows.push({ ticker: trade.ticker, day, quantity: trade.quantity, cost_basis: trade.entry_price, mark_price: markPrice, unrealized_pnl: unrealizedPnl });
  }

  for (const order of result.new_orders) {
    const bar = barOn(order.ticker, day);
    newOrderRows.push({
      run_id: runId, ticker: order.ticker, signal_date: day, intended_execution_date: order.intended_execution_date,
      direction: order.direction, strategy: order.strategy, sektor: order.sektor, region: order.region,
      entry_zone_low: order.entry_zone_low, entry_zone_high: order.entry_zone_high, stop_price: order.stop_price, target_price: order.target_price,
      time_stop_at: order.time_stop_at, risk_amount: order.risk_amount, theoretical_risk_amount: order.theoretical_risk_amount,
      quantity: order.quantity, theoretical_quantity: order.theoretical_quantity, clamp_reason: order.clamp_reason,
      limit_price: bar ? bar.close : null
    });
    const grundSuffix = order.clamp_reason ? ` [gekappt: ${order.clamp_reason}]` : '';
    newRecRows.push({ run_id: runId, as_of_date: day, ticker: order.ticker, direction: order.direction, strategy: order.strategy,
      entry_grund: `${order.strategy} Signal (Engine)${grundSuffix}` });
  }

  portfolioRows.push({
    day, cash: result.cash, positions_value: result.portfolio.positions_value, total_equity: result.portfolio.total_equity,
    drawdown_pct: result.portfolio.drawdown_pct, open_positions_count: result.still_open_trades.length
  });

  stepCompletions.push(step.id);

  // Naechster Tag: NUR still_* uebernehmen, NICHT new_orders in pendingOrdersApi einhaengen
  // (siehe Modul-Kommentar oben - matcht das echte Live-Verhalten, nicht test_golden_run.py).
  cash = result.cash;
  peakEquity = result.portfolio.peak_equity;
  openTradesApi = result.still_open_trades;
  pendingOrdersApi = result.still_pending_orders;
}

return [{ json: {
  run_id: runId, orderUpdates, newOrderRows, newTradeRows, tradeUpdates, openTradeUpdates, newRecRows, recCloseUpdates,
  positionRows, portfolioRows, stepCompletions, lastDay: steps.length ? String(steps[steps.length - 1].simulated_date).slice(0, 10) : null
} }];

// FIX 2026-08-26: Signal-Berechnung (computeSignals je Ticker) war bisher Teil der einen
// grossen, synchronen "Verarbeite Tage-Paket"-Ausfuehrung - bei 15 Tickern x volle
// Indikatoren-Mathematik (SMA/EMA/RSI/MACD/Bollinger/ATR) je Ticker reichte das aus, um den
// geteilten n8n-Runner-Container komplett zu blockieren (WF15/WF16 blieben waehrenddessen
// haengen). Fix: dieser neue Zweig berechnet die Signale in kleinen Batches (separate n8n-
// Node-Ausfuehrungen statt einer einzigen), "Verarbeite Tage-Paket" liest das fertige
// Ergebnis nur noch, statt es selbst zu berechnen. Alles danach (Order-Fills, Exit-Pruefung,
// Positionsgroessen-Kappung, Hard-Limits) bleibt UNVERAENDERT - das ist bewusst sequenziell
// (eine Position, die HEUTE genehmigt wurde, zaehlt fuer die Pruefung des naechsten Tickers
// DESSELBEN Tages mit) und daher NICHT batchbar, aber auch nicht der teure Teil.
//
// Nimmt an, dass ein Paket genau EINEN Tag enthaelt (aktuell durchgesetzt via
// SIMULATION_DEFAULT_PACKAGE_SIZE=1) - bei mehreren Tagen pro Paket wuerde nur der erste Tag
// batchweise verarbeitet, siehe Warnung unten.

const pktCtx = $('Baue Paket-Kontext').all()[0].json;
const priceRows = $('DB: Preisdaten-Fenster laden').all().map(i => i.json);

const steps = [...pktCtx.steps].sort((a, b) => a.sequence_number - b.sequence_number);
if (steps.length > 1) {
  // Sollte mit der aktuellen Konfiguration (Package-Size 1) nie eintreten - Sicherheitsnetz,
  // falls das je geaendert wird, ohne dieses Batching entsprechend zu erweitern.
  throw new Error('Signal-Batching unterstuetzt aktuell nur genau 1 Tag pro Paket, steps.length=' + steps.length);
}
const day = steps.length ? String(steps[0].simulated_date).slice(0, 10) : null;

const barsByTicker = {};
for (const r of priceRows) {
  const t = r.ticker;
  if (!barsByTicker[t]) barsByTicker[t] = [];
  barsByTicker[t].push({ date: String(r.trading_date).slice(0, 10), open: Number(r.open), high: Number(r.high), low: Number(r.low), close: Number(r.close), volume: Number(r.volume) });
}
for (const t in barsByTicker) barsByTicker[t].sort((a, b) => a.date < b.date ? -1 : (a.date > b.date ? 1 : 0));

function barOn(ticker, dateStr) {
  const all = barsByTicker[ticker] || [];
  return all.find(b => b.date === dateStr) || null;
}
function barsUpTo(ticker, dateStr) {
  const all = barsByTicker[ticker] || [];
  const idx = all.findIndex(b => b.date > dateStr);
  return idx === -1 ? all : all.slice(0, idx);
}

const tickersToday = day ? Object.keys(barsByTicker).filter(t => barOn(t, day) !== null) : [];

// Akkumulator fuer die Batch-Ergebnisse zurücksetzen - persistiert sonst ueber diese
// Ausfuehrung hinaus (n8n Workflow-Static-Data ist workflow-weit dauerhaft), muss also vor
// JEDEM neuen Tick frisch geleert werden, damit kein Rest eines vorherigen (evtl.
// abgebrochenen) Ticks haengen bleibt.
const staticData = $getWorkflowStaticData('global');
staticData.signalsAccumulator = {};
staticData.signalsAccumulatorDay = day;

const _batchItems = tickersToday.map(ticker => ({
  json: { ticker, day, bars: barsUpTo(ticker, day) }
}));
// FIX 2026-08-29: an einem Tag ohne Kursdaten (Sim-Zeitraum reicht ueber den Datenrand hinaus,
// z.B. letzte 3 Tage von Lauf 17) ist tickersToday leer. Ohne mindestens 1 Item wuerde der
// ganze Downstream-Zweig (Batch -> Signale zusammenfuehren -> Verarbeite Tage-Paket -> Baue SQL
// fuer Paket-Ergebnisse -> Step-Status schreiben) nicht ausgefuehrt, der Step bliebe endlos im
// Status "running" und der Worker retry-loopt (attempt bleibt 0, kein simulation_errors-Eintrag).
// Sentinel-Item, das "Berechne Signale (Batch)" ueberspringt; der datenlose Tag wird dann als
// normaler Tag mit 0 Trades verarbeitet und der Step sauber abgeschlossen.
return _batchItems.length ? _batchItems : [{ json: { _noTickers: true, day } }];

// FIX 2026-08-26 (siehe "Baue Ticker-Liste fuer Signal-Batching"): computeSignals()-Logik 1:1 wortwoertlich aus "Verarbeite Tage-Paket" uebernommen (unveraendert), laeuft hier nur noch pro Batch statt fuer alle Ticker auf einmal. Schreibt in den ueber den ganzen Tick geteilten Static-Data-Akkumulator statt das Ergebnis nur als Node-Output zurueckzugeben, weil SplitInBatches-Loop-Iterationen sonst nicht ohne Weiteres nach dem Loop-Ende gemeinsam gelesen werden koennen.

function pgStr(v) { return v === null || v === undefined ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }
function pgBool(v) { return v === null || v === undefined ? 'NULL' : (v ? 'TRUE' : 'FALSE'); }
function pgJsonb(v) { return (v === null || v === undefined) ? "'[]'::jsonb" : `'` + JSON.stringify(v).replace(/'/g, `''`) + `'::jsonb`; }

function sma(values, period) {
  if (values.length < period) return null;
  const slice = values.slice(values.length - period);
  return slice.reduce((a, b) => a + b, 0) / period;
}
function stdev(values, period, mean) {
  if (values.length < period) return null;
  const slice = values.slice(values.length - period);
  const m = mean !== undefined ? mean : slice.reduce((a, b) => a + b, 0) / period;
  const variance = slice.reduce((a, b) => a + (b - m) * (b - m), 0) / period;
  return Math.sqrt(variance);
}
function emaSeries(values, period) {
  if (values.length < period) return [];
  const k = 2 / (period + 1);
  const out = [];
  let prev = values.slice(0, period).reduce((a, b) => a + b, 0) / period;
  out[period - 1] = prev;
  for (let i = period; i < values.length; i++) {
    prev = values[i] * k + prev * (1 - k);
    out[i] = prev;
  }
  return out;
}
function rsi14(closes) {
  const period = 14;
  if (closes.length < period + 1) return null;
  const recent = closes.slice(closes.length - (period + 1));
  let gains = 0, losses = 0;
  for (let i = 1; i < recent.length; i++) {
    const diff = recent[i] - recent[i - 1];
    if (diff >= 0) gains += diff; else losses -= diff;
  }
  const avgGain = gains / period, avgLoss = losses / period;
  if (avgLoss === 0) return 100;
  const rs = avgGain / avgLoss;
  return 100 - 100 / (1 + rs);
}
function macd(closes) {
  const ema12 = emaSeries(closes, 12);
  const ema26 = emaSeries(closes, 26);
  if (!ema26.length) return null;
  const macdLine = [];
  for (let i = 25; i < closes.length; i++) {
    if (ema12[i] === undefined || ema26[i] === undefined) continue;
    macdLine[i] = ema12[i] - ema26[i];
  }
  const macdValues = macdLine.filter(v => v !== undefined);
  if (macdValues.length < 9) return null;
  const signalSeries = emaSeries(macdValues, 9);
  const macdNow = macdValues[macdValues.length - 1];
  const macdPrev = macdValues.length >= 2 ? macdValues[macdValues.length - 2] : null;
  const signalNow = signalSeries.length ? signalSeries[signalSeries.length - 1] : null;
  const signalPrev = signalSeries.length >= 2 ? signalSeries[signalSeries.length - 2] : null;
  if (signalNow === null || signalNow === undefined) return null;
  const histNow = macdNow - signalNow;
  const histPrev = (macdPrev !== null && signalPrev !== null && signalPrev !== undefined) ? macdPrev - signalPrev : null;
  return {
    macd: macdNow, signal: signalNow, histogram: histNow,
    bullishCross: histPrev !== null && histPrev <= 0 && histNow > 0,
    bearishCross: histPrev !== null && histPrev >= 0 && histNow < 0,
    zeroCrossBullish: macdPrev !== null && macdPrev <= 0 && macdNow > 0,
    zeroCrossBearish: macdPrev !== null && macdPrev >= 0 && macdNow < 0,
    histImproving: histPrev !== null && histNow > histPrev,
    histWorsening: histPrev !== null && histNow < histPrev
  };
}
function bollinger(closes) {
  const period = 20;
  if (closes.length < period) return null;
  const mean = sma(closes, period);
  const sd = stdev(closes, period, mean);
