  else if (rsiVal < 38 || rsiVal > 62) { mrScore += 0.15; meanReversionEvidence.push('RSI erhoeht (' + rsiVal.toFixed(1) + ')'); }
  if (kursBeiOben) { mrScore += 0.35; meanReversionEvidence.push('Kurs am oberen Bollinger-Band'); }
  if (kursBeiUnten) { mrScore += 0.35; meanReversionEvidence.push('Kurs am unteren Bollinger-Band'); }
  const emaDistPct = ema20Raw > 0 ? Math.abs(aktuellerKurs - ema20Raw) / ema20Raw : 0;
  if (emaDistPct > 0.01) { mrScore += Math.min(0.25, emaDistPct * 5); meanReversionEvidence.push('Abstand zu EMA20: ' + (emaDistPct * 100).toFixed(1) + '%'); }
  const rsiUeberdehntLong = rsiVal < 32, rsiUeberdehntShort = rsiVal > 68;
  const preisUeberdehntLong = kursBeiUnten || (emaDistPct > 0.01 && aktuellerKurs < ema20Raw);
  const preisUeberdehntShort = kursBeiOben || (emaDistPct > 0.01 && aktuellerKurs > ema20Raw);
  if (rsiUeberdehntLong && preisUeberdehntLong) mrDirection = 'long';
  else if (rsiUeberdehntShort && preisUeberdehntShort) mrDirection = 'short';
  const mrStopTargetEntry = stopTargetEntry('mean_reversion', mrDirection, aktuellerKurs, atr14);
  signals.push({
    strategy: 'mean_reversion', direction: mrDirection, raw_score: liveParityRound(Math.min(1, mrScore), 2),
    regime_fit: liveParityRound(Math.min(1, Math.max(0, 1 - bbWidthPct * 5)), 2), data_quality: dataQuality,
    expected_horizon_days: 3, entry_zone_low: mrStopTargetEntry.entryLow, entry_zone_high: mrStopTargetEntry.entryHigh,
    stop_price: mrStopTargetEntry.stop, target_price: mrStopTargetEntry.target, rule_version: 'strategy-v1', blockers: [],
    evidence: meanReversionEvidence
  });

  // --- trend_following (1:1 WF02) ---
  const trendFollowingEvidence = [];
  let tfScore = 0, tfDirection = 'neutral';
  if (macdKreuzungBullisch) { tfScore += 0.4; trendFollowingEvidence.push('MACD bullische Kreuzung'); }
  else if (macdKreuzungBaerisch) { tfScore += 0.4; trendFollowingEvidence.push('MACD baerische Kreuzung'); }
  else if (macdNullLinieBullisch) { tfScore += 0.3; trendFollowingEvidence.push('MACD ueber Nulllinie gekreuzt'); }
  else if (macdNullLinieBaerisch) { tfScore += 0.3; trendFollowingEvidence.push('MACD unter Nulllinie gekreuzt'); }
  else if (macdHistogrammVerbessert) { tfScore += 0.15; trendFollowingEvidence.push('MACD-Histogramm verbessert sich'); }
  else if (macdHistogrammVerschlechtert) { tfScore += 0.15; trendFollowingEvidence.push('MACD-Histogramm verschlechtert sich'); }
  if (trendAufwaerts) trendFollowingEvidence.push('Kurs ueber EMA20 (Aufwaertstrend)');
  else trendFollowingEvidence.push('Kurs unter EMA20 (Abwaertstrend)');
  const macdMomentumPct = aktuellerKurs > 0 ? Math.abs(macdHistogrammRaw) / aktuellerKurs : 0;
  tfScore += Math.min(0.3, macdMomentumPct * 20);
  if (macdValRaw > macdSignalValRaw && trendAufwaerts) tfDirection = 'long';
  else if (macdValRaw < macdSignalValRaw && !trendAufwaerts) tfDirection = 'short';
  const tfStopTargetEntry = stopTargetEntry('trend_following', tfDirection, aktuellerKurs, atr14);
  signals.push({
    strategy: 'trend_following', direction: tfDirection, raw_score: liveParityRound(Math.min(1, tfScore), 2),
    regime_fit: liveParityRound(Math.min(1, bbWidthPct * 5), 2), data_quality: dataQuality,
    expected_horizon_days: 15, entry_zone_low: tfStopTargetEntry.entryLow, entry_zone_high: tfStopTargetEntry.entryHigh,
    stop_price: tfStopTargetEntry.stop, target_price: tfStopTargetEntry.target, rule_version: 'strategy-v1', blockers: [],
    evidence: trendFollowingEvidence
  });

  // --- breakout (1:1 WF02, immer Bars-52W-Pfad - siehe Kommentar oben) ---
  const breakoutEvidence = [];
  let boScore = 0, boDirection = 'neutral';
  const distZuHoch = hoch52wRaw > 0 ? (hoch52wRaw - aktuellerKurs) / hoch52wRaw : 1;
  const distZuTief = tief52wRaw > 0 ? (aktuellerKurs - tief52wRaw) / tief52wRaw : 1;
  const tatsaechlicherAusbruchLong = aktuellerKurs >= hoch52wRaw;
  const tatsaechlicherAusbruchShort = tief52wRaw > 0 && aktuellerKurs <= tief52wRaw;
  const volumenBestaetigt = volumenErhoeht || volumenOk;
  if (tatsaechlicherAusbruchLong && volumenBestaetigt) { boScore += 0.4; boDirection = 'long'; breakoutEvidence.push('Tatsaechlicher Ausbruch ueber 52-Wochen-Hoch, volumenbestaetigt'); }
  else if (distZuHoch < 0.02) breakoutEvidence.push('Kurs nahe 52-Wochen-Hoch, aber kein bestaetigter Ausbruch (fehlende Volumenbestaetigung oder Kurs noch darunter)');
  if (tatsaechlicherAusbruchShort && volumenBestaetigt) { boScore += 0.4; boDirection = 'short'; breakoutEvidence.push('Tatsaechlicher Ausbruch unter 52-Wochen-Tief, volumenbestaetigt'); }
  else if (distZuTief < 0.02) breakoutEvidence.push('Kurs nahe 52-Wochen-Tief, aber kein bestaetigter Ausbruch (fehlende Volumenbestaetigung oder Kurs noch darueber)');
  if (volumenErhoeht) { boScore += 0.35; breakoutEvidence.push('Volumen deutlich erhoeht (' + volFaktor + 'x Durchschnitt)'); }
  else if (volumenOk) { boScore += 0.15; breakoutEvidence.push('Volumen ueber Durchschnitt (' + volFaktor + 'x)'); }
  if (Math.abs(veraenderungPctRaw) > 2.5) { boScore += 0.25; breakoutEvidence.push('Starke Tagesbewegung (' + veraenderungPctRaw.toFixed(1) + '%)'); }
  const boStopTargetEntry = stopTargetEntry('breakout', boDirection, aktuellerKurs, atr14);
  signals.push({
    strategy: 'breakout', direction: boDirection, raw_score: liveParityRound(Math.min(1, boScore), 2),
    regime_fit: volFaktorRaw !== null ? liveParityRound(Math.min(1, volFaktorRaw / 2), 2) : 0.5, data_quality: dataQuality,
    expected_horizon_days: 7, entry_zone_low: boStopTargetEntry.entryLow, entry_zone_high: boStopTargetEntry.entryHigh,
    stop_price: boStopTargetEntry.stop, target_price: boStopTargetEntry.target, rule_version: 'strategy-v1',
    blockers: breakoutHistoryAusreichend ? [] : ['HISTORY_252_MISSING'],
    evidence: breakoutEvidence
  });

  return { signals: signals.filter(s => s.blockers.length === 0), dataQuality };
}

// ============================================================
// LIVE_PARITY - Schritt 4L (2026-09-08): AVAILABLE_DATA_LIVE_REPLAY Shadow Mode.
//
// Modus wird EINMALIG pro Lauf in trading.backtest_runs.config_snapshot_json.mode
// gespeichert (additiv - config_snapshot_json existiert bereits, wird einmalig bei
// Run-Erstellung eingefroren und unveraendert fuer die gesamte Laufzeit wiederverwendet,
// siehe "Baue Run-Kontext"). KEINE Schema-Migration, KEIN neuer Config-Key noetig.
// Bestehende Laeufe haben (frisch gegen einen echten Lauf geprueft, 2026-09-08) niemals
// ein "mode"-Feld in config_snapshot_json - resolveLiveParityMode() faellt fuer sie
// deshalb IMMER auf RESEARCH_BASELINE zurueck, das bestehende Verhalten bleibt exakt
// unveraendert.
//
// FAIL CLOSED (Phase 20): ein explizit gesetzter, aber unbekannter oder als 'LIVE_PARITY'
// gesetzter Modus wirft einen Fehler und stoppt den Lauf, statt still auf Research oder
// Replay umzuschalten. LIVE_PARITY ist bewusst KEIN waehlbarer Modus - nur ein
// semantischer Eligibility-Status (siehe Schritt 4K), niemals ein Ausfuehrungspfad.
// ============================================================
const LIVE_PARITY_VALID_MODES = ['RESEARCH_BASELINE', 'AVAILABLE_DATA_LIVE_REPLAY'];
function resolveLiveParityMode(runCtxForMode) {
  const raw = runCtxForMode && runCtxForMode.config_snapshot_json && runCtxForMode.config_snapshot_json.mode;
  if (raw === undefined || raw === null) return 'RESEARCH_BASELINE';
  if (!LIVE_PARITY_VALID_MODES.includes(raw)) {
    throw new Error('UNSUPPORTED_LIVE_PARITY_MODE: ' + JSON.stringify(raw) + ' (erlaubt: ' + LIVE_PARITY_VALID_MODES.join(', ') + '; LIVE_PARITY ist kein waehlbarer Ausfuehrungsmodus)');
  }
  return raw;
}


const RULE_VERSION = 'historische-simulation-v1';
const staticData = $getWorkflowStaticData('global');
if (!staticData.signalsAccumulator) staticData.signalsAccumulator = {};

// LIVE_PARITY - Schritt 4L: computeLiveParitySignals() nur berechnen, wenn der Lauf
// tatsaechlich im Modus AVAILABLE_DATA_LIVE_REPLAY laeuft (Default RESEARCH_BASELINE
// ueberspringt dies komplett - keine zusaetzliche CPU-Last fuer den bestehenden,
// bereits einmal wegen genau dieses Kostenproblems in Batches aufgeteilten Forschungspfad,
// siehe Kommentar oben zur Batch-Aufteilung vom 2026-08-26).
const liveParityRunCtx = $('Baue Run-Kontext').all()[0].json;
const liveParityMode = resolveLiveParityMode(liveParityRunCtx);

const items = $input.all();
for (const item of items) {
  if (item.json._noTickers) continue; // FIX 2026-08-29: Sentinel fuer datenlose Tage, s. "Baue Ticker-Liste"
  const { ticker, bars } = item.json;
  staticData.signalsAccumulator[ticker] = computeSignals(bars, RULE_VERSION);
  if (liveParityMode === 'AVAILABLE_DATA_LIVE_REPLAY') {
    staticData.signalsAccumulator[ticker].liveParityShadowSignals = computeLiveParitySignals(bars).signals;
  }
}

return items.map(item => ({ json: { ticker: item.json.ticker } }));

