// Batches hinweg gefuellten Static-Data-Akkumulator und stellt ihn als ein einzelnes Item
// bereit, damit "Verarbeite Tage-Paket" ihn wie zuvor als fertiges signalsToday-Objekt lesen
// kann (Schluessel = Ticker, Wert = computeSignals()-Ergebnis).
const staticData = $getWorkflowStaticData('global');
const signalsToday = staticData.signalsAccumulator || {};
return [{ json: { signalsToday } }];
